static int prepare_show_tables_statement(mylite_db *database,
                                         const struct mylite_sql_ast_node *statement,
                                         mylite_stmt **out_stmt)
{
    char *schema_name = NULL;
    char *like_pattern = NULL;
    char *display_pattern = NULL;
    char *glob_pattern = NULL;
    char *column_name = NULL;
    char *sqlite_sql = NULL;
    int status = copy_show_tables_schema_name(database, statement, &schema_name);

    if (status == MYLITE_OK) {
        status = validate_show_tables_schema(database, schema_name);
    }
    if (status == MYLITE_OK &&
        mylite_ast_find_child_kind(statement, MYLITE_SQL_AST_WHERE_CLAUSE) != NULL) {
        (void)mylite_diagnostics_set_error_message(database, "SHOW TABLES WHERE is not supported");
        status = MYLITE_UNSUPPORTED;
    }
    if (status == MYLITE_OK) {
        like_pattern = copy_show_tables_like_pattern(statement);
        if (mylite_ast_find_child_kind(statement, MYLITE_SQL_AST_LITERAL) != NULL &&
            like_pattern == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK && like_pattern != NULL) {
        display_pattern = copy_show_tables_display_pattern(
            like_pattern, mylite_ascii_case_equal(schema_name, "information_schema"));
        if (display_pattern == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK && display_pattern != NULL) {
        glob_pattern = show_tables_glob_pattern(display_pattern);
        if (glob_pattern == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK) {
        column_name = show_tables_column_name(schema_name, display_pattern);
        if (column_name == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK) {
        sqlite_sql = mylite_show_tables_sql(database, &(const struct mylite_show_tables_query){
                                                          .schema_name = schema_name,
                                                          .column_name = column_name,
                                                          .glob_pattern = glob_pattern,
                                                          .full = statement->show_tables_full,
                                                      });
        if (sqlite_sql == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK) {
        status = prepare_sqlite_statement(database, sqlite_sql, out_stmt);
    }

    if (status == MYLITE_NOMEM) {
        (void)mylite_diagnostics_set_error_message(database, "out of memory");
    }
    free(schema_name);
    free(like_pattern);
    free(display_pattern);
    sqlite3_free(column_name);
    sqlite3_free(glob_pattern);
    sqlite3_free(sqlite_sql);
    return status;
}

static int copy_show_tables_schema_name(mylite_db *database,
                                        const struct mylite_sql_ast_node *statement,
                                        char **out_schema_name)
{
    const struct mylite_sql_ast_node *schema_name =
        mylite_ast_find_child_kind(statement, MYLITE_SQL_AST_IDENTIFIER);

    *out_schema_name = NULL;
    if (schema_name != NULL) {
        *out_schema_name = mylite_copy_identifier_span(schema_name);
        if (*out_schema_name == NULL) {
            return MYLITE_NOMEM;
        }
        return normalize_show_tables_schema_name(out_schema_name);
    }
    if (database->selected_schema == NULL || database->selected_schema[0] == '\0') {
        (void)mylite_diagnostics_set_error_message(database, "No database selected");
        return MYLITE_EXEC_ERROR;
    }

    *out_schema_name = mylite_copy_nonempty_cstring(database->selected_schema);
    if (*out_schema_name == NULL) {
        return MYLITE_NOMEM;
    }
    return normalize_show_tables_schema_name(out_schema_name);
}

static int normalize_show_tables_schema_name(char **schema_name)
{
    char *normalized = NULL;

    if (schema_name == NULL || *schema_name == NULL ||
        !mylite_ascii_case_equal(*schema_name, "information_schema") ||
        strcmp(*schema_name, "information_schema") == 0) {
        return MYLITE_OK;
    }

    normalized = mylite_copy_nonempty_cstring("information_schema");
    if (normalized == NULL) {
        return MYLITE_NOMEM;
    }

    free(*schema_name);
    *schema_name = normalized;
    return MYLITE_OK;
}

static int validate_show_tables_schema(mylite_db *database, const char *schema_name)
{
    struct mylite_schema_presence presence;
    int status = mylite_catalog_schema_exists(database, schema_name, &presence);

    if (status != MYLITE_OK) {
        return status;
    }
    if (!presence.exists) {
        (void)mylite_diagnostics_set_error_message_parts(database, "Unknown database '",
                                                         schema_name, "'");
        return MYLITE_EXEC_ERROR;
    }
    return MYLITE_OK;
}

static char *copy_show_tables_like_pattern(const struct mylite_sql_ast_node *statement)
{
    const struct mylite_sql_ast_node *literal =
        mylite_ast_find_child_kind(statement, MYLITE_SQL_AST_LITERAL);

    if (literal == NULL) {
        return NULL;
    }
    return copy_show_like_pattern_span(literal);
}

static char *copy_show_tables_display_pattern(const char *like_pattern, bool uppercase_pattern)
{
    char *display_pattern = mylite_copy_span_text(like_pattern, strlen(like_pattern));

    if (display_pattern == NULL) {
        return NULL;
    }
    if (uppercase_pattern) {
        uppercase_ascii_text(display_pattern);
    }
    return display_pattern;
}

static void uppercase_ascii_text(char *text)
{
    for (size_t index = 0U; text != NULL && text[index] != '\0'; ++index) {
        if (text[index] >= 'a' && text[index] <= 'z') {
            text[index] = (char)(text[index] - 'a' + 'A');
        }
    }
}

static char *show_tables_column_name(const char *schema_name, const char *like_pattern)
{
    if (like_pattern == NULL) {
        return sqlite3_mprintf("Tables_in_%s", schema_name);
    }
    return sqlite3_mprintf("Tables_in_%s (%s)", schema_name, like_pattern);
}

static char *show_tables_glob_pattern(const char *like_pattern)
{
    sqlite3_str *glob = sqlite3_str_new(NULL);

    if (glob == NULL) {
        return NULL;
    }

    for (size_t index = 0U; like_pattern[index] != '\0'; ++index) {
        char character = like_pattern[index];

        if (character == '\\' && like_pattern[index + 1U] != '\0') {
            append_show_tables_glob_literal(glob, like_pattern[++index]);
        } else if (character == '%') {
            sqlite3_str_append(glob, "*", 1);
        } else if (character == '_') {
            sqlite3_str_append(glob, "?", 1);
        } else {
            append_show_tables_glob_literal(glob, character);
        }
    }
    return sqlite3_str_finish(glob);
}

static int prepare_show_table_status_statement(mylite_db *database,
                                               const struct mylite_sql_ast_node *statement,
                                               mylite_stmt **out_stmt)
{
    char *schema_name = NULL;
    char *like_pattern = NULL;
    char *display_pattern = NULL;
    char *glob_pattern = NULL;
    char *sqlite_sql = NULL;
    int status = copy_show_tables_schema_name(database, statement, &schema_name);

    if (status == MYLITE_OK) {
        status = validate_show_tables_schema(database, schema_name);
    }
    if (status == MYLITE_OK &&
        mylite_ast_find_child_kind(statement, MYLITE_SQL_AST_WHERE_CLAUSE) != NULL) {
        (void)mylite_diagnostics_set_error_message(database,
                                                   "SHOW TABLE STATUS WHERE is not supported");
        status = MYLITE_UNSUPPORTED;
    }
    if (status == MYLITE_OK) {
        like_pattern = copy_show_tables_like_pattern(statement);
        if (mylite_ast_find_child_kind(statement, MYLITE_SQL_AST_LITERAL) != NULL &&
            like_pattern == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK && like_pattern != NULL) {
        display_pattern = copy_show_tables_display_pattern(
            like_pattern, mylite_ascii_case_equal(schema_name, "information_schema"));
        if (display_pattern == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK && display_pattern != NULL) {
        glob_pattern = show_tables_glob_pattern(display_pattern);
        if (glob_pattern == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK) {
        sqlite_sql =
            mylite_show_table_status_sql(database, &(const struct mylite_show_table_status_query){
                                                       .schema_name = schema_name,
                                                       .glob_pattern = glob_pattern,
                                                   });
        if (sqlite_sql == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK) {
        status = prepare_sqlite_statement(database, sqlite_sql, out_stmt);
    }

    if (status == MYLITE_NOMEM) {
        (void)mylite_diagnostics_set_error_message(database, "out of memory");
    }
    free(schema_name);
    free(like_pattern);
    free(display_pattern);
    sqlite3_free(glob_pattern);
    sqlite3_free(sqlite_sql);
    return status;
}

static int prepare_show_columns_statement(mylite_db *database,
                                          const struct mylite_sql_ast_node *statement,
                                          mylite_stmt **out_stmt)
{
    struct mylite_show_columns_target target = {0};
    char *like_pattern = NULL;
    char *sqlite_sql = NULL;
    int status = copy_show_columns_target(database, statement, &target);

    if (status == MYLITE_OK) {
        status = validate_show_columns_target(
            database, &target, "SHOW COLUMNS for information_schema tables is not supported");
    }
    if (status == MYLITE_OK &&
        mylite_ast_find_child_kind(statement, MYLITE_SQL_AST_WHERE_CLAUSE) != NULL) {
        (void)mylite_diagnostics_set_error_message(database, "SHOW COLUMNS WHERE is not supported");
        status = MYLITE_UNSUPPORTED;
    }
    if (status == MYLITE_OK) {
        like_pattern = copy_show_columns_like_pattern(statement);
        if (mylite_ast_find_child_kind(statement, MYLITE_SQL_AST_LITERAL) != NULL &&
            like_pattern == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK) {
        sqlite_sql = mylite_show_columns_sql(database, &(const struct mylite_show_columns_query){
                                                           .schema_name = target.schema_name,
                                                           .table_name = target.table_name,
                                                           .like_pattern = like_pattern,
                                                           .full = statement->show_columns_full,
                                                       });
        if (sqlite_sql == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK) {
        status = prepare_sqlite_statement(database, sqlite_sql, out_stmt);
    }

    if (status == MYLITE_NOMEM) {
        (void)mylite_diagnostics_set_error_message(database, "out of memory");
    }
    show_columns_target_deinit(&target);
    free(like_pattern);
    sqlite3_free(sqlite_sql);
    return status;
}

static int copy_show_columns_target(mylite_db *database,
                                    const struct mylite_sql_ast_node *statement,
                                    struct mylite_show_columns_target *out_target)
{
    const struct mylite_sql_ast_node *table_name = mylite_ast_child_at(statement, 0U);
    const struct mylite_sql_ast_node *possible_schema = mylite_ast_child_at(statement, 1U);
    const struct mylite_sql_ast_node *explicit_schema =
        possible_schema != NULL && possible_schema->kind == MYLITE_SQL_AST_IDENTIFIER
            ? possible_schema
            : NULL;
    int status = MYLITE_OK;

    *out_target = (struct mylite_show_columns_target){0};
    status = copy_show_columns_table_target(
        (struct mylite_show_columns_source_nodes){
            .table_name = table_name,
            .explicit_schema = explicit_schema,
        },
        out_target);
    if (status != MYLITE_OK) {
        if (status == MYLITE_UNSUPPORTED) {
            (void)mylite_diagnostics_set_error_message(
                database, "SHOW COLUMNS table names with more than two parts are not "
                          "supported");
        }
        return status;
    }
    if (out_target->schema_name == NULL) {
        status = copy_show_columns_selected_schema(database, out_target);
    }
    return status;
}

static int copy_show_columns_table_target(struct mylite_show_columns_source_nodes source,
                                          struct mylite_show_columns_target *out_target)
{
    char *parts[3] = {0};
    size_t part_count = 0U;
    int status = copy_select_identifier_parts(source.table_name, parts, &part_count);

    if (status != MYLITE_OK) {
        goto cleanup;
    }
    if (part_count == 0U || part_count > 2U) {
        status = MYLITE_UNSUPPORTED;
        goto cleanup;
    }

    if (source.explicit_schema != NULL) {
        out_target->schema_name = mylite_copy_identifier_span(source.explicit_schema);
        if (out_target->schema_name == NULL) {
            status = MYLITE_NOMEM;
            goto cleanup;
        }
        out_target->table_name = parts[part_count - 1U];
        parts[part_count - 1U] = NULL;
    } else if (part_count == 2U) {
        out_target->schema_name = parts[0];
        out_target->table_name = parts[1];
        parts[0] = NULL;
        parts[1] = NULL;
    } else {
        out_target->table_name = parts[0];
        parts[0] = NULL;
    }

    if (out_target->schema_name != NULL) {
        status = normalize_show_columns_schema_name(&out_target->schema_name);
    }

cleanup:
    for (size_t index = 0U; index < part_count; ++index) {
        free(parts[index]);
    }
    if (status != MYLITE_OK) {
        show_columns_target_deinit(out_target);
    }
    return status;
}

static int copy_show_columns_selected_schema(mylite_db *database,
                                             struct mylite_show_columns_target *target)
{
    if (database->selected_schema == NULL || database->selected_schema[0] == '\0') {
        (void)mylite_diagnostics_set_error_message(database, "No database selected");
        return MYLITE_EXEC_ERROR;
    }

    target->schema_name = mylite_copy_nonempty_cstring(database->selected_schema);
    if (target->schema_name == NULL) {
        return MYLITE_NOMEM;
    }
    return normalize_show_columns_schema_name(&target->schema_name);
}

static int normalize_show_columns_schema_name(char **schema_name)
{
    char *normalized = NULL;

    if (schema_name == NULL || *schema_name == NULL ||
        !mylite_ascii_case_equal(*schema_name, "information_schema") ||
        strcmp(*schema_name, "information_schema") == 0) {
        return MYLITE_OK;
    }

    normalized = mylite_copy_nonempty_cstring("information_schema");
    if (normalized == NULL) {
        return MYLITE_NOMEM;
    }

    free(*schema_name);
    *schema_name = normalized;
    return MYLITE_OK;
}

static int validate_show_columns_target(mylite_db *database,
                                        const struct mylite_show_columns_target *target,
                                        const char *information_schema_unsupported_message)
{
    struct mylite_schema_presence presence;
    bool exists = false;
    int status = mylite_catalog_schema_exists(database, target->schema_name, &presence);

    if (status != MYLITE_OK) {
        return status;
    }
    if (!presence.exists) {
        (void)mylite_diagnostics_set_error_message_parts(database, "Unknown database '",
                                                         target->schema_name, "'");
        return MYLITE_EXEC_ERROR;
    }
    if (mylite_ascii_case_equal(target->schema_name, "information_schema")) {
        if (information_schema_table_from_name(target->table_name) ==
            MYLITE_INFORMATION_SCHEMA_NONE) {
            return set_unknown_information_schema_table_error(database, target->table_name);
        }
        (void)mylite_diagnostics_set_error_message(database,
                                                   information_schema_unsupported_message);
        return MYLITE_UNSUPPORTED;
    }

    status =
        mylite_catalog_table_exists(database, target->schema_name, target->table_name, &exists);
    if (status != MYLITE_OK) {
        return status;
    }
    if (!exists) {
        return set_table_doesnt_exist_error(database, target->schema_name, target->table_name);
    }
    return MYLITE_OK;
}

static int set_unknown_information_schema_table_error(mylite_db *database, const char *table_name)
{
    char *display_name = mylite_copy_nonempty_cstring(table_name);
    char *message = NULL;
    int status = MYLITE_OK;

    if (display_name == NULL) {
        (void)mylite_diagnostics_set_error_message(database, "out of memory");
        return MYLITE_NOMEM;
    }
    uppercase_ascii_text(display_name);

    message = sqlite3_mprintf("Unknown table '%q' in information_schema", display_name);
    free(display_name);
    if (message == NULL) {
        (void)mylite_diagnostics_set_error_message(database, "out of memory");
        return MYLITE_NOMEM;
    }

    status = mylite_diagnostics_set_error_message(database, message);
    if (status == MYLITE_OK) {
        status = mylite_diagnostics_append_error(database, MYLITE_MYSQL_ER_NO_SUCH_TABLE, message);
    }
    sqlite3_free(message);
    return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
}

static char *copy_show_columns_like_pattern(const struct mylite_sql_ast_node *statement)
{
    const struct mylite_sql_ast_node *literal =
        mylite_ast_find_child_kind(statement, MYLITE_SQL_AST_LITERAL);

    if (literal == NULL) {
        return NULL;
    }
    return copy_show_like_pattern_span(literal);
}

static void show_columns_target_deinit(struct mylite_show_columns_target *target)
{
    if (target == NULL) {
        return;
    }

    free(target->schema_name);
    free(target->table_name);
    *target = (struct mylite_show_columns_target){0};
}

