static int infer_literal_collation_info(mylite_db *database,
                                        const struct mylite_sql_ast_node *expression,
                                        struct mylite_charset_collation_info *out_info)
{
    switch (expression->literal_kind) {
    case MYLITE_SQL_AST_LITERAL_NULL:
        *out_info = binary_collation_info(mylite_mysql_coercibility_ignorable);
        return MYLITE_OK;
    case MYLITE_SQL_AST_LITERAL_STRING:
        *out_info = connection_collation_info(database, mylite_mysql_coercibility_coercible);
        return MYLITE_OK;
    case MYLITE_SQL_AST_LITERAL_NATIONAL_STRING:
        *out_info = utf8mb3_general_collation_info(mylite_mysql_coercibility_coercible);
        return MYLITE_OK;
    case MYLITE_SQL_AST_LITERAL_INTEGER:
    case MYLITE_SQL_AST_LITERAL_DECIMAL:
    case MYLITE_SQL_AST_LITERAL_FLOAT:
    case MYLITE_SQL_AST_LITERAL_TRUE:
    case MYLITE_SQL_AST_LITERAL_FALSE:
        *out_info = binary_collation_info(mylite_mysql_coercibility_numeric);
        return MYLITE_OK;
    case MYLITE_SQL_AST_LITERAL_HEX:
    case MYLITE_SQL_AST_LITERAL_BIT:
    case MYLITE_SQL_AST_LITERAL_NONE:
        return infer_descriptor_collation_info(database, NULL, expression,
                                               mylite_mysql_coercibility_coercible, out_info);
    }
    return MYLITE_UNSUPPORTED;
}

static int infer_identifier_collation_info(
    mylite_db *database, const struct mylite_expression_collation_context *context,
    const struct mylite_sql_ast_node *expression, struct mylite_charset_collation_info *out_info)
{
    struct mylite_field_descriptor descriptor = field_descriptor_defaults();
    int status = MYLITE_UNSUPPORTED;

    if (context != NULL && context->table != NULL) {
        status =
            infer_table_identifier_descriptor(database, context->table, expression, &descriptor);
    } else if (context != NULL && context->plan != NULL) {
        status = infer_identifier_descriptor(database, context->plan, expression, &descriptor);
    }
    if (status != MYLITE_OK) {
        return status;
    }
    *out_info = descriptor_collation_info(&descriptor, mylite_mysql_coercibility_implicit);
    return MYLITE_OK;
}

// NOLINTNEXTLINE(misc-no-recursion)
static int infer_function_collation_info(mylite_db *database,
                                         const struct mylite_expression_collation_context *context,
                                         const struct mylite_sql_ast_node *expression,
                                         struct mylite_charset_collation_info *out_info)
{
    const struct mylite_sql_ast_node *name = mylite_ast_child_at(expression, 0U);
    const struct mylite_sql_ast_node *arguments = mylite_ast_child_at(expression, 1U);

    if (function_name_is_char(name)) {
        return infer_char_function_collation_info(database, expression, out_info);
    }
    if (function_name_has_binary_string_result(name)) {
        *out_info = binary_collation_info(mylite_mysql_coercibility_coercible);
        return MYLITE_OK;
    }
    if (function_name_has_connection_string_result(name)) {
        *out_info = connection_collation_info(database, mylite_mysql_coercibility_coercible);
        return MYLITE_OK;
    }
    if (function_name_is_inet_ntoa(name)) {
        *out_info = connection_collation_info(database, mylite_mysql_coercibility_coercible);
        return MYLITE_OK;
    }
    if (function_name_is_charset(name) || function_name_is_collation(name)) {
        *out_info = utf8mb3_general_collation_info(mylite_mysql_coercibility_coercible);
        return MYLITE_OK;
    }
    if (function_name_has_binary_numeric_collation_result(name)) {
        *out_info = binary_collation_info(mylite_mysql_coercibility_numeric);
        return MYLITE_OK;
    }
    if (name != NULL && (mylite_span_equal_ci(name->span, "DATABASE") ||
                         mylite_span_equal_ci(name->span, "SCHEMA") ||
                         mylite_span_equal_ci(name->span, "VERSION"))) {
        *out_info = utf8mb3_general_collation_info(mylite_mysql_coercibility_system_constant);
        return MYLITE_OK;
    }
    if (name != NULL && (mylite_span_equal_ci(name->span, "USER") ||
                         mylite_span_equal_ci(name->span, "SESSION_USER") ||
                         mylite_span_equal_ci(name->span, "SYSTEM_USER") ||
                         mylite_span_equal_ci(name->span, "CURRENT_USER"))) {
        *out_info = utf8mb3_general_collation_info(mylite_mysql_coercibility_system_constant);
        return MYLITE_OK;
    }
    if (name != NULL && mylite_span_equal_ci(name->span, "IF")) {
        return infer_function_arguments_collation_info(database, context, arguments, 1U, false,
                                                       out_info);
    }
    if (name != NULL &&
        (mylite_span_equal_ci(name->span, "IFNULL") || mylite_span_equal_ci(name->span, "NULLIF") ||
         mylite_span_equal_ci(name->span, "COALESCE"))) {
        return infer_function_arguments_collation_info(database, context, arguments, 0U, false,
                                                       out_info);
    }
    if (function_name_is_quote(name)) {
        return infer_quote_function_collation_info(database, context, arguments, out_info);
    }
    if (function_name_has_text_result(name) || function_name_has_slice_string_result(name)) {
        size_t first_argument =
            function_name_is_make_set(name) || function_name_is_elt(name) ? 1U : 0U;

        return infer_function_arguments_collation_info(database, context, arguments, first_argument,
                                                       true, out_info);
    }

    return infer_descriptor_collation_info(database, context, expression,
                                           mylite_mysql_coercibility_coercible, out_info);
}

static int infer_char_function_collation_info(mylite_db *database,
                                              const struct mylite_sql_ast_node *expression,
                                              struct mylite_charset_collation_info *out_info)
{
    const struct mylite_sql_ast_node *charset_node = mylite_ast_child_at(expression, 2U);
    char *charset_name = mylite_copy_schema_text_span(charset_node);

    if (charset_node == NULL) {
        *out_info = binary_collation_info(mylite_mysql_coercibility_coercible);
        return MYLITE_OK;
    }
    if (charset_name == NULL) {
        return MYLITE_NOMEM;
    }
    if (!char_function_charset_name_is_supported(charset_name)) {
        int status = mylite_diagnostics_set_unknown_charset_error(database, charset_name);

        free(charset_name);
        return status;
    }
    *out_info = char_function_collation_info(charset_name);
    free(charset_name);
    return MYLITE_OK;
}

// NOLINTNEXTLINE(misc-no-recursion)
static int infer_quote_function_collation_info(
    mylite_db *database, const struct mylite_expression_collation_context *context,
    const struct mylite_sql_ast_node *arguments, struct mylite_charset_collation_info *out_info)
{
    struct mylite_charset_collation_info source =
        binary_collation_info(mylite_mysql_coercibility_ignorable);
    int status = infer_expression_collation_info(database, context,
                                                 mylite_ast_child_at(arguments, 0U), &source);

    if (status != MYLITE_OK) {
        return status;
    }
    if (source.coercibility == mylite_mysql_coercibility_numeric &&
        mylite_ascii_case_equal(source.character_set, mylite_mysql_binary_charset_name)) {
        *out_info = latin1_swedish_collation_info(source.coercibility);
        return MYLITE_OK;
    }
    if (mylite_ascii_case_equal(source.character_set, mylite_mysql_binary_charset_name)) {
        *out_info = connection_collation_info(database, source.coercibility);
        return MYLITE_OK;
    }
    *out_info = source;
    return MYLITE_OK;
}

static bool
function_name_has_binary_numeric_collation_result(const struct mylite_sql_ast_node *name)
{
    struct mylite_field_descriptor descriptor = field_descriptor_defaults();

    if (function_name_is_coercibility(name) || function_name_has_length_result(name) ||
        function_name_is_bit_count(name) || function_name_is_crc32(name) ||
        function_name_is_inet_aton(name) || function_name_is_is_uuid(name) ||
        function_name_has_integer_result(name) || function_name_is_strcmp(name)) {
        return true;
    }
    if (infer_code_search_function_descriptor(name, true, &descriptor) ||
        infer_list_index_function_descriptor(name, true, &descriptor)) {
        return true;
    }
    if (name == NULL) {
        return false;
    }
    if (mylite_span_equal_ci(name->span, "PI") || mylite_span_equal_ci(name->span, "MOD") ||
        function_name_is_exp(name) || function_name_is_logarithm(name) ||
        function_name_is_power(name) || function_name_is_sqrt(name) ||
        function_name_is_trigonometric(name) || function_name_is_inverse_trigonometric(name) ||
        function_name_is_angle_conversion(name) || mylite_span_equal_ci(name->span, "ISNULL") ||
        mylite_span_equal_ci(name->span, "LAST_INSERT_ID") ||
        mylite_span_equal_ci(name->span, "CONNECTION_ID")) {
        return true;
    }
    return mylite_span_equal_ci(name->span, "ROW_COUNT");
}

// NOLINTNEXTLINE(misc-no-recursion)
static int infer_function_arguments_collation_info(
    mylite_db *database, const struct mylite_expression_collation_context *context,
    const struct mylite_sql_ast_node *arguments, size_t first_argument, bool numeric_as_connection,
    struct mylite_charset_collation_info *out_info)
{
    struct mylite_charset_collation_info best =
        binary_collation_info(mylite_mysql_coercibility_ignorable);
    size_t index = 0U;
    bool saw_candidate = false;

    for (const struct mylite_sql_ast_node *argument = arguments == NULL ? NULL
                                                                        : arguments->first_child;
         argument != NULL; argument = argument->next_sibling, ++index) {
        struct mylite_charset_collation_info current =
            binary_collation_info(mylite_mysql_coercibility_ignorable);
        int status = MYLITE_OK;

        if (index < first_argument) {
            continue;
        }
        status = infer_expression_collation_info(database, context, argument, &current);
        if (status != MYLITE_OK) {
            return status;
        }
        if (numeric_as_connection && current.coercibility == mylite_mysql_coercibility_numeric &&
            mylite_ascii_case_equal(current.character_set, mylite_mysql_binary_charset_name)) {
            current = connection_collation_info(database, mylite_mysql_coercibility_coercible);
        }
        if (current.coercibility == mylite_mysql_coercibility_ignorable) {
            continue;
        }
        if (!saw_candidate || current.coercibility < best.coercibility ||
            (current.coercibility == best.coercibility &&
             mylite_ascii_case_equal(current.character_set, mylite_mysql_binary_charset_name))) {
            best = current;
            saw_candidate = true;
        }
    }
    if (saw_candidate) {
        *out_info = best;
    } else {
        *out_info = binary_collation_info(mylite_mysql_coercibility_ignorable);
    }
    return MYLITE_OK;
}

static int infer_cast_collation_info(mylite_db *database,
                                     const struct mylite_sql_ast_node *expression,
                                     struct mylite_charset_collation_info *out_info)
{
    const struct mylite_sql_ast_node *target = mylite_ast_child_at(expression, 1U);

    if (target == NULL || target->kind != MYLITE_SQL_AST_COLUMN_TYPE) {
        return MYLITE_UNSUPPORTED;
    }
    if (target->column_type == MYLITE_SQL_AST_COLUMN_TYPE_BINARY) {
        *out_info = binary_collation_info(mylite_mysql_coercibility_implicit);
        return MYLITE_OK;
    }
    if (target->column_type == MYLITE_SQL_AST_COLUMN_TYPE_CHAR) {
        char *charset_name = NULL;

        if (!target->has_column_character_set) {
            *out_info = connection_collation_info(database, mylite_mysql_coercibility_implicit);
            return MYLITE_OK;
        }
        charset_name = mylite_copy_unquoted_span_text(target->column_character_set);
        if (charset_name == NULL) {
            return MYLITE_NOMEM;
        }
        if (!char_function_charset_name_is_supported(charset_name)) {
            int status = mylite_diagnostics_set_unknown_charset_error(database, charset_name);

            free(charset_name);
            return status;
        }
        *out_info = char_function_collation_info(charset_name);
        out_info->coercibility = mylite_mysql_coercibility_implicit;
        free(charset_name);
        return MYLITE_OK;
    }
    return infer_descriptor_collation_info(database, NULL, expression,
                                           mylite_mysql_coercibility_coercible, out_info);
}

static int
infer_descriptor_collation_info(mylite_db *database,
                                const struct mylite_expression_collation_context *context,
                                const struct mylite_sql_ast_node *expression, int text_coercibility,
                                struct mylite_charset_collation_info *out_info)
{
    struct mylite_field_descriptor descriptor = field_descriptor_defaults();
    int status = infer_expression_descriptor(database, context == NULL ? NULL : context->plan,
                                             expression, NULL, &descriptor);

    if (status != MYLITE_OK) {
        return status;
    }
    *out_info = descriptor_collation_info(&descriptor, text_coercibility);
    return MYLITE_OK;
}

static int infer_table_identifier_descriptor(mylite_db *database,
                                             const struct mylite_select_table *table,
                                             const struct mylite_sql_ast_node *expression,
                                             struct mylite_field_descriptor *out_descriptor)
{
    size_t column_index = table == NULL ? 0U : table->column_count;
    int status = table == NULL ? MYLITE_UNSUPPORTED
                               : resolve_select_column_reference(table, expression, &column_index);

    (void)database;
    if (status != MYLITE_OK || table == NULL || column_index >= table->column_count) {
        *out_descriptor = field_descriptor_defaults();
        return status == MYLITE_OK ? MYLITE_UNSUPPORTED : status;
    }
    *out_descriptor = table->columns[column_index].descriptor;
    return MYLITE_OK;
}

static struct mylite_charset_collation_info binary_collation_info(int coercibility)
{
    return (struct mylite_charset_collation_info){
        .character_set = mylite_mysql_binary_charset_name,
        .collation = mylite_mysql_binary_charset_name,
        .coercibility = coercibility,
    };
}

static struct mylite_charset_collation_info connection_collation_info(const mylite_db *database,
                                                                      int coercibility)
{
    const char *character_set = database == NULL || database->character_set_connection == NULL
                                    ? mylite_charset_default_name()
                                    : database->character_set_connection;
    const char *collation = database == NULL || database->collation_connection == NULL
                                ? mylite_charset_default_collation_name()
                                : database->collation_connection;

    return (struct mylite_charset_collation_info){
        .character_set = character_set,
        .collation = collation,
        .coercibility = coercibility,
    };
}

static struct mylite_charset_collation_info latin1_swedish_collation_info(int coercibility)
{
    return (struct mylite_charset_collation_info){
        .character_set = mylite_mysql_latin1_charset_name,
        .collation = mylite_mysql_latin1_swedish_ci_collation_name,
        .coercibility = coercibility,
    };
}

static struct mylite_charset_collation_info utf8mb3_general_collation_info(int coercibility)
{
    return (struct mylite_charset_collation_info){
        .character_set = mylite_mysql_utf8mb3_charset_name,
        .collation = mylite_mysql_utf8mb3_general_ci_collation_name,
        .coercibility = coercibility,
    };
}

static struct mylite_charset_collation_info char_function_collation_info(const char *charset_name)
{
    const struct mylite_charset *charset = mylite_charset_lookup(charset_name);
    const struct mylite_collation *collation =
        charset == NULL ? NULL : mylite_collation_lookup(charset->default_collation);

    if (mylite_ascii_case_equal(charset_name, mylite_mysql_binary_charset_name)) {
        return binary_collation_info(mylite_mysql_coercibility_coercible);
    }
    if (mylite_ascii_case_equal(charset_name, "utf8")) {
        return utf8mb3_general_collation_info(mylite_mysql_coercibility_coercible);
    }
    if (mylite_ascii_case_equal(charset_name, mylite_mysql_ascii_charset_name)) {
        return (struct mylite_charset_collation_info){
            .character_set = mylite_mysql_ascii_charset_name,
            .collation = mylite_mysql_ascii_general_ci_collation_name,
            .coercibility = mylite_mysql_coercibility_coercible,
        };
    }
    if (charset != NULL && collation != NULL) {
        return (struct mylite_charset_collation_info){
            .character_set = charset->name,
            .collation = collation->name,
            .coercibility = mylite_mysql_coercibility_coercible,
        };
    }
    return binary_collation_info(mylite_mysql_coercibility_coercible);
}

static struct mylite_charset_collation_info
descriptor_collation_info(const struct mylite_field_descriptor *descriptor, int text_coercibility)
{
    const struct mylite_collation *collation = NULL;

    if (descriptor == NULL || descriptor->type == MYLITE_FIELD_TYPE_NULL) {
        return binary_collation_info(mylite_mysql_coercibility_ignorable);
    }
    if (field_descriptor_has_numeric_result(descriptor) ||
        descriptor->type == MYLITE_FIELD_TYPE_DATE || descriptor->type == MYLITE_FIELD_TYPE_TIME ||
        descriptor->type == MYLITE_FIELD_TYPE_DATETIME ||
        descriptor->type == MYLITE_FIELD_TYPE_TIMESTAMP ||
        descriptor->type == MYLITE_FIELD_TYPE_YEAR) {
        return binary_collation_info(mylite_mysql_coercibility_numeric);
    }
    if (descriptor->type != MYLITE_FIELD_TYPE_STRING &&
        descriptor->type != MYLITE_FIELD_TYPE_VAR_STRING &&
        descriptor->type != MYLITE_FIELD_TYPE_BLOB) {
        return binary_collation_info(mylite_mysql_coercibility_numeric);
    }
    collation = collation_lookup_id(descriptor->charset_id);
    if (collation == NULL) {
        return binary_collation_info(text_coercibility);
    }
    return (struct mylite_charset_collation_info){
        .character_set = collation->character_set,
        .collation = collation->name,
        .coercibility = text_coercibility,
    };
}

static int
evaluate_last_insert_id_function(mylite_stmt *stmt, const struct mylite_sql_ast_node *function_call,
                                 const struct mylite_expression_eval_context *expression_context,
                                 struct mylite_expression_warnings *warnings,
                                 struct mylite_expression_value *out_value)
{
    const struct mylite_sql_ast_node *arguments = mylite_ast_child_at(function_call, 1U);
    const struct mylite_sql_ast_node *argument = mylite_ast_child_at(arguments, 0U);
    struct mylite_expression_value value = {0};
    int status = 0;

    if (stmt == NULL || stmt->database == NULL) {
        return -1;
    }
    if (argument == NULL) {
        *out_value = (struct mylite_expression_value){
            .kind = MYLITE_EXPRESSION_VALUE_UINT64, .uint64_value = stmt->database->last_insert_id};
        return 0;
    }

    status = mylite_expression_eval_with_context(argument, expression_context, warnings, &value);
    if (status != 0) {
        mylite_expression_value_deinit(&value);
        return status;
    }
    if (value.kind == MYLITE_EXPRESSION_VALUE_NULL) {
        stmt->database->last_insert_id = 0U;
        mylite_expression_value_deinit(&value);
        *out_value = (struct mylite_expression_value){.kind = MYLITE_EXPRESSION_VALUE_NULL};
        return 0;
    }

    stmt->database->last_insert_id = session_function_value_to_uint64(&value);
    mylite_expression_value_deinit(&value);
    *out_value = (struct mylite_expression_value){.kind = MYLITE_EXPRESSION_VALUE_UINT64,
                                                  .uint64_value = stmt->database->last_insert_id};
    return 0;
}

static uint64_t session_function_value_to_uint64(const struct mylite_expression_value *value)
{
    if (value == NULL) {
        return 0U;
    }
    switch (value->kind) {
    case MYLITE_EXPRESSION_VALUE_NULL:
        return 0U;
    case MYLITE_EXPRESSION_VALUE_INT64:
        return (uint64_t)value->int64_value;
    case MYLITE_EXPRESSION_VALUE_UINT64:
        return value->uint64_value;
    case MYLITE_EXPRESSION_VALUE_REAL:
        return (uint64_t)value->real_value;
    case MYLITE_EXPRESSION_VALUE_TEXT:
        return value->text_value == NULL ? 0U
                                         : (uint64_t)strtoull(value->text_value, NULL,
                                                              mylite_mysql_decimal_conversion_base);
    }
    return 0U;
}

static int execute_table_select_statement(mylite_stmt *stmt)
{
    if (stmt->sqlite_stmt == NULL && select_plan_table_count(&stmt->select_plan) <= 1U) {
        return MYLITE_MISUSE;
    }
    stmt->executed = true;
    stmt->affected_rows = -1;

    int status = materialize_table_select_result(stmt);

    if (status != MYLITE_OK) {
        return status;
    }
    if (stmt->select_result.next_row >= stmt->select_result.row_count) {
        mylite_statement_table_select_current_values_deinit(&stmt->select_result);
        stmt->select_result.has_current_row = false;
        return MYLITE_DONE;
    }

    status =
        set_table_select_current_row(stmt, &stmt->select_result.rows[stmt->select_result.next_row]);
    if (status != MYLITE_OK) {
        return status;
    }
    ++stmt->select_result.next_row;
    return MYLITE_ROW;
}

static int execute_union_query_statement(mylite_stmt *stmt)
{
    int status = MYLITE_OK;

    stmt->executed = true;
    stmt->affected_rows = -1;

    status = materialize_union_query_result(stmt);
    if (status != MYLITE_OK) {
        return status;
    }
    if (stmt->select_result.next_row >= stmt->select_result.row_count) {
        mylite_statement_table_select_current_values_deinit(&stmt->select_result);
        stmt->select_result.has_current_row = false;
        return MYLITE_DONE;
    }

    status =
        set_table_select_current_row(stmt, &stmt->select_result.rows[stmt->select_result.next_row]);
    if (status != MYLITE_OK) {
        return status;
    }
    ++stmt->select_result.next_row;
    return MYLITE_ROW;
}

static int materialize_union_query_result(mylite_stmt *stmt)
{
    struct mylite_expression_warnings saved_warnings = {0};
    struct mylite_expression_warnings accumulated_warnings = {0};
    int status = MYLITE_OK;

    if (stmt->select_result.materialized) {
        return MYLITE_OK;
    }

    saved_warnings = stmt->database->warnings;
    stmt->database->warnings = (struct mylite_expression_warnings){0};

    for (size_t index = 0U; status == MYLITE_OK && index < stmt->union_plan.operand_count;
         ++index) {
        enum mylite_sql_ast_set_duplicate_mode duplicate_mode =
            index == 0U ? MYLITE_SQL_AST_SET_DUPLICATES_ALL
                        : stmt->union_plan.operators[index - 1U];

        status = scan_union_operand(stmt, stmt->union_plan.operands[index], duplicate_mode);
        if (append_and_clear_union_database_warnings(stmt->database, &accumulated_warnings) !=
            MYLITE_OK) {
            status = MYLITE_NOMEM;
        }
    }

    if (status == MYLITE_OK && stmt->select_plan.order_key_count != 0U) {
        for (size_t index = 0U; status == MYLITE_OK && index < stmt->select_result.row_count;
             ++index) {
            status = evaluate_union_order_values(stmt, &stmt->select_result.rows[index]);
        }
        if (status == MYLITE_OK) {
            status = sort_table_select_result_rows(stmt);
        }
    }
    if (status == MYLITE_OK) {
        status = apply_table_select_limit(stmt);
    }
    if (status == MYLITE_OK) {
        stmt->select_result.materialized = true;
    }

    if (append_and_clear_union_database_warnings(stmt->database, &accumulated_warnings) !=
        MYLITE_OK) {
        status = MYLITE_NOMEM;
    }
    stmt->database->warnings = saved_warnings;
    if (append_subquery_warnings(&stmt->database->warnings, &accumulated_warnings) != MYLITE_OK) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        status = MYLITE_NOMEM;
    }
    mylite_expression_warnings_deinit(&accumulated_warnings);
    return status;
}

static int scan_union_operand(mylite_stmt *stmt, mylite_stmt *operand,
                              enum mylite_sql_ast_set_duplicate_mode duplicate_mode)
{
    bool distinct = duplicate_mode == MYLITE_SQL_AST_SET_DUPLICATES_DISTINCT;

    if (distinct) {
        int status = deduplicate_union_result_rows(stmt);

        if (status != MYLITE_OK) {
            return status;
        }
    }

    for (;;) {
        int status = execute_union_operand_statement(operand);

        if (status == MYLITE_DONE) {
            return MYLITE_OK;
        }
        if (status != MYLITE_ROW) {
            return status;
        }
        status = append_union_operand_current_row(stmt, operand, distinct);
        if (status != MYLITE_OK) {
            return status;
        }
    }
}

static int append_union_operand_current_row(mylite_stmt *stmt, mylite_stmt *operand, bool distinct)
{
    struct mylite_table_select_row row = {0};
    int status = copy_union_operand_current_row(stmt, operand, &row);

    if (status == MYLITE_OK) {
        if (distinct) {
            status = append_union_distinct_row(stmt, &row);
        } else {
            status = append_table_select_result_row(stmt, &row);
        }
    }
    mylite_statement_table_select_row_deinit(&row);
    return status;
}

static int execute_union_operand_statement(mylite_stmt *operand)
{
    if (operand == NULL) {
        return MYLITE_MISUSE;
    }

    switch (operand->kind) {
    case MYLITE_STMT_SQLITE: {
        int rc = sqlite3_step(operand->sqlite_stmt);

        if (rc == SQLITE_ROW) {
            return MYLITE_ROW;
        }
        if (rc == SQLITE_DONE) {
            return MYLITE_DONE;
        }
        return mylite_diagnostics_set_sqlite_error(operand->database);
    }
    case MYLITE_STMT_SCALAR_SELECT:
        return execute_scalar_select_statement(operand);
    case MYLITE_STMT_TABLE_SELECT:
        return execute_table_select_statement(operand);
    case MYLITE_STMT_CREATE_SCHEMA:
    case MYLITE_STMT_ALTER_SCHEMA:
    case MYLITE_STMT_DROP_SCHEMA:
    case MYLITE_STMT_USE_SCHEMA:
    case MYLITE_STMT_SET_NAMES:
    case MYLITE_STMT_SET_CHARACTER_SET:
    case MYLITE_STMT_CREATE_TABLE:
    case MYLITE_STMT_DROP_TABLE:
    case MYLITE_STMT_RENAME_TABLE:
    case MYLITE_STMT_TRUNCATE_TABLE:
    case MYLITE_STMT_ALTER_TABLE:
    case MYLITE_STMT_CREATE_INDEX:
    case MYLITE_STMT_DROP_INDEX:
    case MYLITE_STMT_INSERT_VALUES:
    case MYLITE_STMT_INSERT_SET:
    case MYLITE_STMT_REPLACE_VALUES:
    case MYLITE_STMT_REPLACE_SET:
    case MYLITE_STMT_UNION_QUERY:
    case MYLITE_STMT_UPDATE:
    case MYLITE_STMT_DELETE:
    case MYLITE_STMT_START_TRANSACTION:
    case MYLITE_STMT_BEGIN_TRANSACTION:
    case MYLITE_STMT_COMMIT:
    case MYLITE_STMT_ROLLBACK:
    case MYLITE_STMT_SAVEPOINT:
    case MYLITE_STMT_ROLLBACK_TO_SAVEPOINT:
    case MYLITE_STMT_RELEASE_SAVEPOINT:
        break;
    }
    return MYLITE_UNSUPPORTED;
}

// NOLINTNEXTLINE(bugprone-easily-swappable-parameters)
static int copy_union_operand_current_row(mylite_stmt *stmt, mylite_stmt *operand,
                                          struct mylite_table_select_row *out_row)
{
    size_t column_count = stmt->select_plan.output_count;

    *out_row = (struct mylite_table_select_row){0};
    out_row->output_values = calloc(column_count, sizeof(*out_row->output_values));
    if (out_row->output_values == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    out_row->output_value_count = column_count;

    for (size_t index = 0U; index < column_count; ++index) {
        int status =
            copy_subquery_statement_row_value(operand, index, &out_row->output_values[index]);

        if (status != MYLITE_OK) {
            if (status == MYLITE_NOMEM) {
                (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            }
            return status;
        }
    }
    return MYLITE_OK;
}

static int append_union_distinct_row(mylite_stmt *stmt, struct mylite_table_select_row *row)
{
    if (table_select_distinct_row_exists(stmt, row)) {
        mylite_statement_table_select_row_deinit(row);
        return MYLITE_OK;
    }
    return append_table_select_result_row(stmt, row);
}

static int deduplicate_union_result_rows(mylite_stmt *stmt)
{
    size_t kept = 0U;

    for (size_t index = 0U; index < stmt->select_result.row_count; ++index) {
        bool duplicate = false;

        for (size_t compare = 0U; compare < kept; ++compare) {
            if (table_select_output_values_equal(stmt, &stmt->select_result.rows[compare],
                                                 &stmt->select_result.rows[index])) {
                duplicate = true;
                break;
            }
        }
        if (duplicate) {
            mylite_statement_table_select_row_deinit(&stmt->select_result.rows[index]);
            continue;
        }
        if (kept != index) {
            stmt->select_result.rows[kept] = stmt->select_result.rows[index];
            stmt->select_result.rows[index] = (struct mylite_table_select_row){0};
        }
        ++kept;
    }
    stmt->select_result.row_count = kept;
    return MYLITE_OK;
}

static int evaluate_union_order_values(mylite_stmt *stmt, struct mylite_table_select_row *row)
{
    row->order_values = calloc(stmt->select_plan.order_key_count, sizeof(*row->order_values));
    if (row->order_values == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    row->order_value_count = stmt->select_plan.order_key_count;

    for (size_t index = 0U; index < stmt->select_plan.order_key_count; ++index) {
        int status = evaluate_union_order_key(stmt, row, &stmt->select_plan.order_keys[index],
                                              &row->order_values[index]);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int evaluate_union_order_key(mylite_stmt *stmt, const struct mylite_table_select_row *row,
                                    const struct mylite_select_order_key *order_key,
                                    struct mylite_expression_value *out_value)
{
    if (order_key->kind == MYLITE_SELECT_ORDER_KEY_OUTPUT) {
        if (order_key->output_index >= row->output_value_count ||
            mylite_expression_value_copy(&row->output_values[order_key->output_index], out_value) !=
                0) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        return MYLITE_OK;
    }

    {
        struct mylite_union_expression_context user_context = {
            .stmt = stmt,
            .row = row,
        };
        struct mylite_expression_eval_context context = {
            .user_data = &user_context,
            .resolve_identifier = resolve_union_expression_identifier,
            .eval_session_function = evaluate_union_session_function,
        };
        int status = mylite_expression_eval_with_context(order_key->expression, &context,
                                                         &stmt->database->warnings, out_value);

        if (status == 0) {
            return MYLITE_OK;
        }
        if (status == MYLITE_NOMEM) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        if (stmt->database->error_message != NULL) {
            return MYLITE_EXEC_ERROR;
        }
    }
    return set_select_unsupported_order_error(stmt->database);
}

static int resolve_union_expression_identifier(void *user_data,
                                               const struct mylite_sql_ast_node *identifier,
                                               struct mylite_expression_value *out_value)
{
    struct mylite_union_expression_context *context = user_data;
    char *parts[3] = {0};
    size_t part_count = 0U;
    int status = MYLITE_OK;

    if (context == NULL || context->stmt == NULL || context->row == NULL) {
        return -1;
    }

    status = copy_select_identifier_parts(identifier, parts, &part_count);
    if (status != MYLITE_OK) {
        if (status == MYLITE_NOMEM) {
            (void)mylite_diagnostics_set_error_message(context->stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        return -1;
    }
    if (part_count == 1U) {
        size_t output_index = 0U;
        size_t output_matches =
            select_output_label_count(&context->stmt->select_plan, parts[0], &output_index);

        if (output_matches == 1U && output_index < context->row->output_value_count) {
            status = mylite_expression_value_copy(&context->row->output_values[output_index],
                                                  out_value) == 0
                         ? 0
                         : MYLITE_NOMEM;
        } else {
            status = -1;
        }
    } else {
        status = -1;
    }

    for (size_t index = 0U; index < part_count && index < 3U; ++index) {
        free(parts[index]);
    }
    if (status == MYLITE_NOMEM) {
        (void)mylite_diagnostics_set_error_message(context->stmt->database, "out of memory");
    }
    return status;
}

static int append_and_clear_union_database_warnings(mylite_db *database,
                                                    struct mylite_expression_warnings *warnings)
{
    struct mylite_expression_warnings current = database->warnings;
    int status = MYLITE_OK;

    database->warnings = (struct mylite_expression_warnings){0};
    status = append_subquery_warnings(warnings, &current);
    mylite_expression_warnings_deinit(&current);
    if (status != MYLITE_OK) {
        (void)mylite_diagnostics_set_error_message(database, "out of memory");
    }
    return status;
}

static int materialize_table_select_result(mylite_stmt *stmt)
{
    int status = MYLITE_OK;

    if (stmt->select_result.materialized) {
        return MYLITE_OK;
    }
    if (select_plan_table_count(&stmt->select_plan) > 1U) {
        status = materialize_joined_table_select_result(stmt);
    } else if (stmt->select_plan.has_group_by || stmt->select_plan.has_aggregate ||
               stmt->select_plan.has_having) {
        status = materialize_aggregate_table_select_result(stmt);
    } else if (stmt->select_plan.order_key_count != 0U) {
        status = materialize_ordered_table_select_result(stmt);
    } else {
        status = materialize_unordered_table_select_result(stmt);
    }
    if (status == MYLITE_OK) {
        stmt->select_result.materialized = true;
    }
    return status;
}

static int materialize_ordered_table_select_result(mylite_stmt *stmt)
{
    int status = evaluate_table_select_constant_predicate(stmt);
    int rc = SQLITE_OK;

    if (status != MYLITE_OK) {
        return status;
    }
    if (stmt->select_constant_predicate_evaluated && !stmt->select_constant_predicate_matches) {
        return MYLITE_OK;
    }

    while ((rc = sqlite3_step(stmt->sqlite_stmt)) == SQLITE_ROW) {
        struct mylite_table_select_row row = {0};
        bool matches = false;

        status = copy_table_select_sqlite_row(stmt, &row);
        if (status != MYLITE_OK) {
            return status;
        }
        status = evaluate_table_select_row_matches(stmt, &row, &matches);
        if (status != MYLITE_OK) {
            mylite_statement_table_select_row_deinit(&row);
            return status;
        }
        if (!matches) {
            mylite_statement_table_select_row_deinit(&row);
            continue;
        }

        if (select_duplicate_mode_is_distinct(stmt->select_plan.duplicate_mode)) {
            bool duplicate = false;

            status = check_table_select_distinct_duplicate(stmt, &row, &duplicate);
            if (status != MYLITE_OK) {
                mylite_statement_table_select_row_deinit(&row);
                return status;
            }
            if (duplicate) {
                mylite_statement_table_select_row_deinit(&row);
                continue;
            }
        }
        status = evaluate_table_select_order_values(stmt, &row);
        if (status == MYLITE_OK) {
            status = append_table_select_result_row(stmt, &row);
        }
        if (status != MYLITE_OK) {
            mylite_statement_table_select_row_deinit(&row);
            return status;
        }
    }
    if (rc != SQLITE_DONE) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    status = sort_table_select_result_rows(stmt);
    if (status == MYLITE_OK) {
        status = apply_table_select_limit(stmt);
    }
    return status;
}

static int materialize_unordered_table_select_result(mylite_stmt *stmt)
{
    struct mylite_unordered_table_select_append_state append_state = {0};
    bool distinct = select_duplicate_mode_is_distinct(stmt->select_plan.duplicate_mode);
    int status = MYLITE_OK;
    int rc = SQLITE_OK;

    if (stmt->select_plan.limit.has_limit && stmt->select_plan.limit.row_count == 0U) {
        return MYLITE_OK;
    }

    status = evaluate_table_select_constant_predicate(stmt);
    if (status != MYLITE_OK) {
        return status;
    }
    if (stmt->select_constant_predicate_evaluated && !stmt->select_constant_predicate_matches) {
        return MYLITE_OK;
    }

    while ((rc = sqlite3_step(stmt->sqlite_stmt)) == SQLITE_ROW) {
        struct mylite_table_select_row row = {0};
        bool matches = false;

        status = copy_table_select_sqlite_row(stmt, &row);
        if (status != MYLITE_OK) {
            return status;
        }
        status = evaluate_table_select_row_matches(stmt, &row, &matches);
        if (status != MYLITE_OK) {
            mylite_statement_table_select_row_deinit(&row);
            return status;
        }
        if (!matches) {
            mylite_statement_table_select_row_deinit(&row);
            continue;
        }
        status = append_unordered_table_select_matched_row(stmt, &row, &append_state, distinct);
        if (status != MYLITE_OK) {
            mylite_statement_table_select_row_deinit(&row);
            return status;
        }
        if (append_state.stop) {
            break;
        }
    }
    if (rc != SQLITE_DONE &&
        !table_select_limit_is_full(&stmt->select_plan.limit, stmt->select_result.row_count)) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }
    if (distinct) {
        return apply_table_select_limit(stmt);
    }
    return MYLITE_OK;
}

static int
append_unordered_table_select_matched_row(mylite_stmt *stmt, struct mylite_table_select_row *row,
                                          struct mylite_unordered_table_select_append_state *state,
                                          bool distinct)
{
    if (distinct) {
        return append_unordered_table_select_distinct_row(stmt, row);
    }
    return append_unordered_table_select_limited_row(stmt, row, state);
}

static int append_unordered_table_select_distinct_row(mylite_stmt *stmt,
                                                      struct mylite_table_select_row *row)
{
    bool duplicate = false;
    int status = check_table_select_distinct_duplicate(stmt, row, &duplicate);

    if (status != MYLITE_OK) {
        return status;
    }
    if (duplicate) {
        mylite_statement_table_select_row_deinit(row);
        return MYLITE_OK;
    }
    return append_table_select_result_row(stmt, row);
}

static int
append_unordered_table_select_limited_row(mylite_stmt *stmt, struct mylite_table_select_row *row,
                                          struct mylite_unordered_table_select_append_state *state)
{
    if (table_select_limit_row_is_kept(&stmt->select_plan.limit,
                                       (struct mylite_select_limit_position){
                                           .matched_row = state->matched_row,
                                           .kept_count = stmt->select_result.row_count,
                                       })) {
        int status = append_table_select_result_row(stmt, row);

        if (status != MYLITE_OK) {
            return status;
        }
    } else {
        mylite_statement_table_select_row_deinit(row);
    }
    if (state->matched_row != UINT64_MAX) {
        ++state->matched_row;
    }
    state->stop =
        table_select_limit_is_full(&stmt->select_plan.limit, stmt->select_result.row_count);
    return MYLITE_OK;
}

static int materialize_joined_table_select_result(mylite_stmt *stmt)
{
    size_t table_count = select_plan_table_count(&stmt->select_plan);
    struct mylite_table_select_join_materialize_state state = {0};
    struct mylite_table_select_row row = {0};
    bool aggregate_query = (stmt->select_plan.has_group_by || stmt->select_plan.has_aggregate ||
                            stmt->select_plan.has_having) != 0;
    bool distinct = select_duplicate_mode_is_distinct(stmt->select_plan.duplicate_mode);
    int status = MYLITE_OK;

    if (select_plan_has_outer_join(&stmt->select_plan)) {
        return materialize_outer_joined_table_select_result(stmt);
    }

    if (!aggregate_query && stmt->select_plan.order_key_count == 0U &&
        stmt->select_plan.limit.has_limit && stmt->select_plan.limit.row_count == 0U) {
        return MYLITE_OK;
    }

    status = evaluate_table_select_constant_predicate(stmt);
    if (status != MYLITE_OK) {
        return status;
    }
    if (stmt->select_constant_predicate_evaluated && !stmt->select_constant_predicate_matches) {
        return MYLITE_OK;
    }
    if (table_count == 0U) {
        return MYLITE_UNSUPPORTED;
    }

    state.rowsets = calloc(table_count, sizeof(*state.rowsets));
    if (state.rowsets == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    row.value_count = select_plan_column_count(&stmt->select_plan);
    if (row.value_count != 0U) {
        row.values = calloc(row.value_count, sizeof(*row.values));
        if (row.values == NULL) {
            table_select_table_rowsets_deinit(state.rowsets, table_count);
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
    }

    status = load_table_select_join_rowsets(stmt, state.rowsets);
    if (status == MYLITE_OK) {
        status = scan_joined_table_select_rows(stmt, &state, &row);
    }

    if (status == MYLITE_OK && aggregate_query && state.group_count == 0U &&
        !stmt->select_plan.has_group_by) {
        status = append_empty_implicit_table_select_group(stmt, &state.groups, &state.group_count);
    }
    if (status == MYLITE_OK && aggregate_query) {
        status = append_finalized_table_select_groups(stmt, state.groups, state.group_count);
    }
    if (status == MYLITE_OK && stmt->select_plan.order_key_count != 0U) {
        status = sort_table_select_result_rows(stmt);
    }
    if (status == MYLITE_OK &&
        (aggregate_query || stmt->select_plan.order_key_count != 0U || distinct)) {
        status = apply_table_select_limit(stmt);
    }

    for (size_t index = 0U; index < state.group_count; ++index) {
        table_select_group_deinit(&state.groups[index]);
    }
    free(state.groups);
    mylite_statement_table_select_row_deinit(&row);
    table_select_join_condition_cache_deinit(&state.condition_cache);
    table_select_table_rowsets_deinit(state.rowsets, table_count);
    return status;
}

static bool select_plan_has_outer_join(const struct mylite_select_plan *plan)
{
    for (size_t index = 0U; index < plan->join_step_count; ++index) {
        enum mylite_sql_ast_join_type join_type = plan->join_steps[index].join_type;

        if (join_type == MYLITE_SQL_AST_JOIN_LEFT || join_type == MYLITE_SQL_AST_JOIN_RIGHT) {
            return true;
        }
    }
    return false;
}

static int materialize_outer_joined_table_select_result(mylite_stmt *stmt)
{
    size_t table_count = select_plan_table_count(&stmt->select_plan);
    struct mylite_table_select_join_materialize_state state = {0};
    bool aggregate_query = (stmt->select_plan.has_group_by || stmt->select_plan.has_aggregate ||
                            stmt->select_plan.has_having) != 0;
    bool distinct = select_duplicate_mode_is_distinct(stmt->select_plan.duplicate_mode);
    int status = MYLITE_OK;

    if (!aggregate_query && stmt->select_plan.order_key_count == 0U &&
        stmt->select_plan.limit.has_limit && stmt->select_plan.limit.row_count == 0U) {
        return MYLITE_OK;
    }

    status = evaluate_table_select_constant_predicate(stmt);
    if (status != MYLITE_OK) {
        return status;
    }
    if (stmt->select_constant_predicate_evaluated && !stmt->select_constant_predicate_matches) {
        return MYLITE_OK;
    }
    if (table_count == 0U) {
        return MYLITE_UNSUPPORTED;
    }

    state.rowsets = calloc(table_count, sizeof(*state.rowsets));
    if (state.rowsets == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    status = load_table_select_join_rowsets(stmt, state.rowsets);
    if (status == MYLITE_OK) {
        status = scan_outer_joined_table_select_rows(stmt, &state);
    }

    if (status == MYLITE_OK && aggregate_query && state.group_count == 0U &&
        !stmt->select_plan.has_group_by) {
        status = append_empty_implicit_table_select_group(stmt, &state.groups, &state.group_count);
    }
    if (status == MYLITE_OK && aggregate_query) {
        status = append_finalized_table_select_groups(stmt, state.groups, state.group_count);
    }
    if (status == MYLITE_OK && stmt->select_plan.order_key_count != 0U) {
        status = sort_table_select_result_rows(stmt);
    }
    if (status == MYLITE_OK &&
        (aggregate_query || stmt->select_plan.order_key_count != 0U || distinct)) {
        status = apply_table_select_limit(stmt);
    }

    for (size_t index = 0U; index < state.group_count; ++index) {
        table_select_group_deinit(&state.groups[index]);
    }
    free(state.groups);
    table_select_join_condition_cache_deinit(&state.condition_cache);
    table_select_table_rowsets_deinit(state.rowsets, table_count);
    return status;
}

static int load_table_select_join_rowsets(mylite_stmt *stmt,
                                          struct mylite_table_select_table_rowset *rowsets)
{
    size_t table_count = select_plan_table_count(&stmt->select_plan);

    for (size_t table_index = 0U; table_index < table_count; ++table_index) {
        int status = load_table_select_join_rowset(stmt, table_index, &rowsets[table_index]);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int load_table_select_join_rowset(mylite_stmt *stmt, size_t table_index,
                                         struct mylite_table_select_table_rowset *rowset)
{
    const struct mylite_select_table *table =
        select_plan_table_const(&stmt->select_plan, table_index);
    sqlite3_stmt *scan = NULL;
    char *scan_sql = NULL;
    int rc = SQLITE_OK;

    if (table == NULL) {
        return MYLITE_UNSUPPORTED;
    }

    scan_sql = build_select_table_scan_sql(stmt->database, table);
    if (scan_sql == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    rc = sqlite3_prepare_v3(stmt->database->sqlite, scan_sql, -1, SQLITE_PREPARE_PERSISTENT, &scan,
                            NULL);
    sqlite3_free(scan_sql);
    if (rc != SQLITE_OK) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    while ((rc = sqlite3_step(scan)) == SQLITE_ROW) {
        int status = append_table_select_join_scan_row(stmt, scan, table, rowset);

        if (status != MYLITE_OK) {
            sqlite3_finalize(scan);
            return status;
        }
    }
    sqlite3_finalize(scan);
    return rc == SQLITE_DONE ? MYLITE_OK : mylite_diagnostics_set_sqlite_error(stmt->database);
}

static char *build_select_table_scan_sql(mylite_db *database,
                                         const struct mylite_select_table *table)
{
    sqlite3_str *sql = sqlite3_str_new(database->sqlite);

    if (sql == NULL) {
        return NULL;
    }

    sqlite3_str_append(sql, "SELECT ", (int)strlen("SELECT "));
    for (size_t index = 0U; index < table->column_count; ++index) {
        if (index != 0U) {
            sqlite3_str_append(sql, ",", 1);
        }
        sqlite3_str_appendf(sql, "\"%w\"", table->columns[index].name);
    }
    sqlite3_str_appendf(sql, " FROM \"%w\"", table->physical_name);
    return sqlite3_str_finish(sql);
}

static int append_table_select_join_scan_row(mylite_stmt *stmt, sqlite3_stmt *scan,
                                             const struct mylite_select_table *table,
                                             struct mylite_table_select_table_rowset *rowset)
{
    struct mylite_table_select_row row = {
        .value_count = table->column_count,
    };
    struct mylite_table_select_row *rows = NULL;

    if (row.value_count != 0U) {
        row.values = calloc(row.value_count, sizeof(*row.values));
        if (row.values == NULL) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
    }

    for (size_t index = 0U; index < row.value_count; ++index) {
        if (copy_sqlite_column_value(scan, index, &row.values[index]) != 0) {
            mylite_statement_table_select_row_deinit(&row);
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
    }

    rows = realloc(rowset->rows, (rowset->row_count + 1U) * sizeof(*rowset->rows));
    if (rows == NULL) {
        mylite_statement_table_select_row_deinit(&row);
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    rowset->rows = rows;
    rowset->rows[rowset->row_count++] = row;
    return MYLITE_OK;
}

static int scan_joined_table_select_rows(mylite_stmt *stmt,
                                         struct mylite_table_select_join_materialize_state *state,
                                         struct mylite_table_select_row *row)
{
    size_t table_count = select_plan_table_count(&stmt->select_plan);
    struct mylite_table_select_join_scan_state scan = {
        .row = row,
        .table_count = table_count,
    };
    bool finished = false;
    int status = MYLITE_OK;

    if (state->stop) {
        return MYLITE_OK;
    }

    if (table_count == 0U) {
        return process_joined_table_select_full_row(stmt, state, row);
    }

    scan.frames = calloc(table_count, sizeof(*scan.frames));
    if (scan.frames == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    while (!finished && !state->stop) {
        status = advance_joined_table_select_scan(stmt, state, &scan, &finished);
        if (status != MYLITE_OK) {
            break;
        }
    }

    clear_joined_table_select_scan_copies(stmt, &scan);
    free(scan.frames);
    return status;
}

static int
scan_outer_joined_table_select_rows(mylite_stmt *stmt,
                                    struct mylite_table_select_join_materialize_state *state)
{
    size_t range_count = stmt->select_plan.from_range_count;
    struct mylite_table_select_table_rowset *range_rowsets = NULL;
    int status = MYLITE_OK;

    if (range_count == 0U) {
        return MYLITE_UNSUPPORTED;
    }
    range_rowsets = calloc(range_count, sizeof(*range_rowsets));
    if (range_rowsets == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    for (size_t range_index = 0U; status == MYLITE_OK && range_index < range_count; ++range_index) {
        struct mylite_select_table_range range = stmt->select_plan.from_ranges[range_index];

        status =
            materialize_select_from_range_rowset(stmt, state, range, &range_rowsets[range_index]);
    }
    if (status == MYLITE_OK) {
        status = process_outer_joined_table_range_rows(stmt, state, range_rowsets, range_count);
    }

    for (size_t index = 0U; index < range_count; ++index) {
        table_select_table_rowset_deinit(&range_rowsets[index]);
    }
    free(range_rowsets);
    return status;
}

static int materialize_select_from_range_rowset(
    mylite_stmt *stmt, struct mylite_table_select_join_materialize_state *state,
    struct mylite_select_table_range range, struct mylite_table_select_table_rowset *out_rowset)
{
    int status = materialize_select_base_range_rowset(stmt, state, range, out_rowset);

    for (size_t index = 0U; status == MYLITE_OK && index < stmt->select_plan.join_step_count;
         ++index) {
        const struct mylite_select_join_step *step = &stmt->select_plan.join_steps[index];

        if (!select_join_step_is_in_range(step, range)) {
            continue;
        }
        status = apply_select_join_step_to_rowset(stmt, state, step, out_rowset);
    }
    return status;
}

static int materialize_select_base_range_rowset(
    mylite_stmt *stmt, struct mylite_table_select_join_materialize_state *state,
    struct mylite_select_table_range range, struct mylite_table_select_table_rowset *out_rowset)
{
    const struct mylite_select_table *table =
        select_plan_table_const(&stmt->select_plan, range.first_table);

    if (table == NULL) {
        return MYLITE_UNSUPPORTED;
    }
    for (size_t row_index = 0U; row_index < state->rowsets[range.first_table].row_count;
         ++row_index) {
        struct mylite_table_select_row *row = NULL;
        int status = append_empty_joined_table_select_row(stmt, out_rowset, &row);

        if (status == MYLITE_OK) {
            status = copy_select_base_table_row_values(
                stmt->database, row, table, range.first_table,
                &state->rowsets[range.first_table].rows[row_index], row_index);
        }
        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int apply_select_join_step_to_rowset(
    mylite_stmt *stmt, struct mylite_table_select_join_materialize_state *state,
    const struct mylite_select_join_step *step, struct mylite_table_select_table_rowset *rowset)
{
    const struct mylite_table_select_table_rowset *right =
        &state->rowsets[step->right_range.first_table];
    struct mylite_table_select_table_rowset next = {0};
    bool *right_matched = NULL;
    int status = MYLITE_OK;

    if (step->join_type == MYLITE_SQL_AST_JOIN_RIGHT && right->row_count != 0U) {
        right_matched = calloc(right->row_count, sizeof(*right_matched));
        if (right_matched == NULL) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
    }

    status = append_select_join_step_matches(stmt, state, step, rowset, right_matched, &next);
    if (status == MYLITE_OK && step->join_type == MYLITE_SQL_AST_JOIN_RIGHT) {
        status = append_select_null_extended_right_rows(stmt, step, right, right_matched, &next);
    }

    free(right_matched);
    if (status != MYLITE_OK) {
        table_select_table_rowset_deinit(&next);
        return status;
    }
    table_select_table_rowset_deinit(rowset);
    *rowset = next;
    return MYLITE_OK;
}

static int append_select_join_step_matches(mylite_stmt *stmt,
                                           struct mylite_table_select_join_materialize_state *state,
                                           const struct mylite_select_join_step *step,
                                           const struct mylite_table_select_table_rowset *left,
                                           bool *right_matched,
                                           struct mylite_table_select_table_rowset *out_rowset)
{
    const struct mylite_table_select_table_rowset *right =
        &state->rowsets[step->right_range.first_table];

    for (size_t left_index = 0U; left_index < left->row_count; ++left_index) {
        struct mylite_select_join_match_tracking tracking = {
            .left_matched = false,
            .right_matched = right_matched,
        };
        int status = append_select_join_step_left_matches(
            stmt, state, step, &left->rows[left_index], right, &tracking, out_rowset);

        if (status != MYLITE_OK) {
            return status;
        }
        if (!tracking.left_matched && step->join_type == MYLITE_SQL_AST_JOIN_LEFT) {
            status =
                append_select_null_extended_left_row(stmt, &left->rows[left_index], out_rowset);
            if (status != MYLITE_OK) {
                return status;
            }
        }
    }
    return MYLITE_OK;
}

static int append_select_join_step_left_matches(
    mylite_stmt *stmt, struct mylite_table_select_join_materialize_state *state,
    const struct mylite_select_join_step *step, const struct mylite_table_select_row *left_row,
    const struct mylite_table_select_table_rowset *right,
    struct mylite_select_join_match_tracking *tracking,
    struct mylite_table_select_table_rowset *out_rowset)
{
    tracking->left_matched = false;
    for (size_t right_index = 0U; right_index < right->row_count; ++right_index) {
        struct mylite_select_join_row_pair rows = {
            .left = left_row,
            .right = &right->rows[right_index],
            .right_index = right_index,
        };
        bool matches = false;
        int status = append_select_join_step_match(stmt, state, step, &rows, &matches, out_rowset);

        if (status != MYLITE_OK) {
            return status;
        }
        if (matches) {
            tracking->left_matched = true;
            if (tracking->right_matched != NULL) {
                tracking->right_matched[right_index] = true;
            }
        }
    }
    return MYLITE_OK;
}

static int append_select_join_step_match(mylite_stmt *stmt,
                                         struct mylite_table_select_join_materialize_state *state,
                                         const struct mylite_select_join_step *step,
                                         const struct mylite_select_join_row_pair *rows,
                                         bool *out_matches,
                                         struct mylite_table_select_table_rowset *out_rowset)
{
    const struct mylite_select_table *right_table =
        select_plan_table_const(&stmt->select_plan, step->right_range.first_table);
    struct mylite_table_select_row candidate = {0};
    int status = table_select_row_copy(rows->left, &candidate);

    *out_matches = false;
    if (status == MYLITE_NOMEM) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    if (right_table == NULL) {
        mylite_statement_table_select_row_deinit(&candidate);
        return MYLITE_UNSUPPORTED;
    }

    status = copy_select_base_table_row_values(stmt->database, &candidate, right_table,
                                               step->right_range.first_table, rows->right,
                                               rows->right_index);
    if (status == MYLITE_OK) {
        status =
            evaluate_table_select_join_step_conditions(stmt, state, &candidate, step, out_matches);
    }
    if (status == MYLITE_OK && *out_matches) {
        status = append_table_select_row_to_rowset(stmt, out_rowset, &candidate);
    }
    mylite_statement_table_select_row_deinit(&candidate);
    return status;
}

static int append_select_null_extended_left_row(mylite_stmt *stmt,
                                                const struct mylite_table_select_row *left_row,
                                                struct mylite_table_select_table_rowset *out_rowset)
{
    return append_table_select_row_copy_to_rowset(stmt, out_rowset, left_row);
}

static int append_select_null_extended_right_rows(
    mylite_stmt *stmt, const struct mylite_select_join_step *step,
    const struct mylite_table_select_table_rowset *right, const bool *right_matched,
    struct mylite_table_select_table_rowset *out_rowset)
{
    for (size_t right_index = 0U; right_index < right->row_count; ++right_index) {
        if (right_matched != NULL && right_matched[right_index]) {
            continue;
        }
        int status = append_select_null_extended_right_row(stmt, step, &right->rows[right_index],
                                                           right_index, out_rowset);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int
append_select_null_extended_right_row(mylite_stmt *stmt, const struct mylite_select_join_step *step,
                                      const struct mylite_table_select_row *right_row,
                                      size_t right_row_index,
                                      struct mylite_table_select_table_rowset *out_rowset)
{
    const struct mylite_select_table *right_table =
        select_plan_table_const(&stmt->select_plan, step->right_range.first_table);
    struct mylite_table_select_row *row = NULL;
    int status = append_empty_joined_table_select_row(stmt, out_rowset, &row);

    if (status == MYLITE_OK && right_table == NULL) {
        status = MYLITE_UNSUPPORTED;
    }
    if (status == MYLITE_OK) {
        status = copy_select_base_table_row_values(stmt->database, row, right_table,
                                                   step->right_range.first_table, right_row,
                                                   right_row_index);
    }
    return status;
}

static int append_empty_joined_table_select_row(mylite_stmt *stmt,
                                                struct mylite_table_select_table_rowset *rowset,
                                                struct mylite_table_select_row **out_row)
{
    struct mylite_table_select_row row = {
        .value_count = select_plan_column_count(&stmt->select_plan),
        .source_row_index_count = select_plan_table_count(&stmt->select_plan),
    };
    int status = MYLITE_OK;

    *out_row = NULL;
    if (row.value_count != 0U) {
        row.values = calloc(row.value_count, sizeof(*row.values));
        if (row.values == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK && row.source_row_index_count != 0U) {
        row.source_row_indexes =
            calloc(row.source_row_index_count, sizeof(*row.source_row_indexes));
        if (row.source_row_indexes == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status != MYLITE_OK) {
        mylite_statement_table_select_row_deinit(&row);
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return status;
    }
    for (size_t index = 0U; index < row.source_row_index_count; ++index) {
        row.source_row_indexes[index] = SIZE_MAX;
    }

    status = append_table_select_row_to_rowset(stmt, rowset, &row);
    if (status != MYLITE_OK) {
        mylite_statement_table_select_row_deinit(&row);
        return status;
    }
    *out_row = &rowset->rows[rowset->row_count - 1U];
    return MYLITE_OK;
}

static int append_table_select_row_copy_to_rowset(mylite_stmt *stmt,
                                                  struct mylite_table_select_table_rowset *rowset,
                                                  const struct mylite_table_select_row *row)
{
    struct mylite_table_select_row copy = {0};
    int status = table_select_row_copy(row, &copy);

    if (status == MYLITE_NOMEM) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    status = append_table_select_row_to_rowset(stmt, rowset, &copy);
    if (status != MYLITE_OK) {
        mylite_statement_table_select_row_deinit(&copy);
    }
    return status;
}

static int append_table_select_row_to_rowset(mylite_stmt *stmt,
                                             struct mylite_table_select_table_rowset *rowset,
                                             struct mylite_table_select_row *row)
{
    struct mylite_table_select_row *rows =
        realloc(rowset->rows, (rowset->row_count + 1U) * sizeof(*rowset->rows));

    if (rows == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    rowset->rows = rows;
    rowset->rows[rowset->row_count++] = *row;
    *row = (struct mylite_table_select_row){0};
    return MYLITE_OK;
}

static int copy_select_base_table_row_values(mylite_db *database,
                                             struct mylite_table_select_row *row,
                                             const struct mylite_select_table *table,
                                             size_t table_index,
                                             const struct mylite_table_select_row *source,
                                             size_t source_row_index)
{
    if (table == NULL || row->source_row_index_count <= table_index) {
        return MYLITE_UNSUPPORTED;
    }
    for (size_t index = 0U; index < table->column_count; ++index) {
        size_t column_index = table->first_column_index + index;

        if (column_index >= row->value_count || index >= source->value_count) {
            return MYLITE_UNSUPPORTED;
        }
        mylite_expression_value_deinit(&row->values[column_index]);
        if (mylite_expression_value_copy(&source->values[index], &row->values[column_index]) != 0) {
            (void)mylite_diagnostics_set_error_message(database, "out of memory");
            return MYLITE_NOMEM;
        }
    }
    row->source_row_indexes[table_index] = source_row_index;
    return MYLITE_OK;
}

static int copy_select_row_range_values(struct mylite_table_select_row *target,
                                        const struct mylite_table_select_row *source,
                                        struct mylite_select_table_range range,
                                        const struct mylite_select_plan *plan)
{
    size_t last_table = range.first_table + range.table_count;

    for (size_t table_index = range.first_table; table_index < last_table; ++table_index) {
        const struct mylite_select_table *table = select_plan_table_const(plan, table_index);

        if (table == NULL || table_index >= target->source_row_index_count ||
            table_index >= source->source_row_index_count) {
            return MYLITE_UNSUPPORTED;
        }
        target->source_row_indexes[table_index] = source->source_row_indexes[table_index];
        for (size_t column = 0U; column < table->column_count; ++column) {
            size_t column_index = table->first_column_index + column;

            if (column_index >= target->value_count || column_index >= source->value_count) {
                return MYLITE_UNSUPPORTED;
            }
            mylite_expression_value_deinit(&target->values[column_index]);
            if (mylite_expression_value_copy(&source->values[column_index],
                                             &target->values[column_index]) != 0) {
                return MYLITE_NOMEM;
            }
        }
    }
    return MYLITE_OK;
}

static void table_select_table_rowset_deinit(struct mylite_table_select_table_rowset *rowset)
{
    if (rowset == NULL) {
        return;
    }
    for (size_t row_index = 0U; row_index < rowset->row_count; ++row_index) {
        mylite_statement_table_select_row_deinit(&rowset->rows[row_index]);
    }
    free(rowset->rows);
    *rowset = (struct mylite_table_select_table_rowset){0};
}

static int process_outer_joined_table_range_rows(
    mylite_stmt *stmt, struct mylite_table_select_join_materialize_state *state,
    const struct mylite_table_select_table_rowset *range_rowsets, size_t range_count)
{
    size_t *row_indexes = NULL;
    bool finished = false;
    int status = MYLITE_OK;

    for (size_t range_index = 0U; range_index < range_count; ++range_index) {
        if (range_rowsets[range_index].row_count == 0U) {
            return MYLITE_OK;
        }
    }

    row_indexes = calloc(range_count, sizeof(*row_indexes));
    if (row_indexes == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    while (!finished && !state->stop) {
        status = process_outer_joined_table_range_row(stmt, state, range_rowsets, row_indexes,
                                                      range_count);
        if (status != MYLITE_OK) {
            break;
        }

        for (size_t index = range_count; index > 0U; --index) {
            size_t range_index = index - 1U;

            ++row_indexes[range_index];
            if (row_indexes[range_index] < range_rowsets[range_index].row_count) {
                break;
            }
            row_indexes[range_index] = 0U;
            if (range_index == 0U) {
                finished = true;
            }
        }
    }

    free(row_indexes);
    return status;
}

static int
process_outer_joined_table_range_row(mylite_stmt *stmt,
                                     struct mylite_table_select_join_materialize_state *state,
                                     const struct mylite_table_select_table_rowset *range_rowsets,
                                     const size_t *row_indexes, size_t range_count)
{
    struct mylite_table_select_row row = {0};
    int status = MYLITE_OK;

    row.value_count = select_plan_column_count(&stmt->select_plan);
    row.source_row_index_count = select_plan_table_count(&stmt->select_plan);
    if (row.value_count != 0U) {
        row.values = calloc(row.value_count, sizeof(*row.values));
        if (row.values == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status == MYLITE_OK && row.source_row_index_count != 0U) {
        row.source_row_indexes =
            calloc(row.source_row_index_count, sizeof(*row.source_row_indexes));
        if (row.source_row_indexes == NULL) {
            status = MYLITE_NOMEM;
        }
    }
    if (status != MYLITE_OK) {
        mylite_statement_table_select_row_deinit(&row);
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return status;
    }
    for (size_t index = 0U; index < row.source_row_index_count; ++index) {
        row.source_row_indexes[index] = SIZE_MAX;
    }

    for (size_t range_index = 0U; status == MYLITE_OK && range_index < range_count; ++range_index) {
        struct mylite_select_table_range range = stmt->select_plan.from_ranges[range_index];

        status = copy_select_row_range_values(
            &row, &range_rowsets[range_index].rows[row_indexes[range_index]], range,
            &stmt->select_plan);
    }
    if (status == MYLITE_OK) {
        status = process_joined_table_select_full_row(stmt, state, &row);
    }
    mylite_statement_table_select_row_deinit(&row);
    return status;
}

static int evaluate_table_select_join_step_conditions(
    mylite_stmt *stmt, struct mylite_table_select_join_materialize_state *state,
    const struct mylite_table_select_row *row, const struct mylite_select_join_step *step,
    bool *out_matches)
{
    size_t available_table_count = step->joined_range.first_table + step->joined_range.table_count;
    struct mylite_select_table_range cache_range = {0};
    struct mylite_table_select_join_condition_cache_lookup lookup = {
        .found = false,
        .matches = false,
    };
    int status = MYLITE_OK;

    if (!select_join_stage_cache_range(stmt->database, &stmt->select_plan, available_table_count,
                                       &cache_range)) {
        return evaluate_table_select_join_stage_conditions_uncached(
            stmt, row, available_table_count, out_matches);
    }

    status = lookup_table_select_join_condition_cache_row(&state->condition_cache, row, cache_range,
                                                          &lookup);
    if (status != MYLITE_OK) {
        return status;
    }
    if (lookup.found) {
        *out_matches = lookup.matches;
        return MYLITE_OK;
    }

    status = evaluate_table_select_join_stage_conditions_uncached(stmt, row, available_table_count,
                                                                  out_matches);
    if (status == MYLITE_OK) {
        status = store_table_select_join_condition_cache_row(stmt, &state->condition_cache, row,
                                                             cache_range, *out_matches);
    }
    return status;
}

static int advance_joined_table_select_scan(
    mylite_stmt *stmt, struct mylite_table_select_join_materialize_state *state,
    struct mylite_table_select_join_scan_state *scan, bool *out_finished)
{
    const struct mylite_select_table *table =
        select_plan_table_const(&stmt->select_plan, scan->table_index);
    const struct mylite_table_select_table_rowset *rowset = &state->rowsets[scan->table_index];

    *out_finished = false;
    if (table == NULL) {
        return MYLITE_UNSUPPORTED;
    }
    if (scan->frames[scan->table_index].row_index >= rowset->row_count) {
        return backtrack_joined_table_select_scan(stmt, scan, out_finished);
    }
    return process_joined_table_select_scan_row(stmt, state, scan, table, rowset);
}

static int backtrack_joined_table_select_scan(mylite_stmt *stmt,
                                              struct mylite_table_select_join_scan_state *scan,
                                              bool *out_finished)
{
    const struct mylite_select_table *table = NULL;

    scan->frames[scan->table_index].row_index = 0U;
    if (scan->table_index == 0U) {
        *out_finished = true;
        return MYLITE_OK;
    }

    --scan->table_index;
    table = select_plan_table_const(&stmt->select_plan, scan->table_index);
    if (table == NULL) {
        return MYLITE_UNSUPPORTED;
    }
    clear_joined_table_select_scan_frame(scan, table, scan->table_index);
    ++scan->frames[scan->table_index].row_index;
    return MYLITE_OK;
}

static int process_joined_table_select_scan_row(
    mylite_stmt *stmt, struct mylite_table_select_join_materialize_state *state,
    struct mylite_table_select_join_scan_state *scan, const struct mylite_select_table *table,
    const struct mylite_table_select_table_rowset *rowset)
{
    bool matches = false;
    int status = copy_joined_table_select_row_values(
        scan->row, table, &rowset->rows[scan->frames[scan->table_index].row_index]);

    if (status != MYLITE_OK) {
        if (status == MYLITE_NOMEM) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        }
        return status;
    }

    scan->frames[scan->table_index].copied = true;
    status = evaluate_table_select_join_stage_conditions(stmt, state, scan, &matches);
    if (status != MYLITE_OK) {
        return status;
    }
    if (!matches) {
        clear_joined_table_select_scan_frame(scan, table, scan->table_index);
        ++scan->frames[scan->table_index].row_index;
        return MYLITE_OK;
    }

    if (scan->table_index + 1U == scan->table_count) {
        status = process_joined_table_select_full_row(stmt, state, scan->row);
        clear_joined_table_select_scan_frame(scan, table, scan->table_index);
        ++scan->frames[scan->table_index].row_index;
        return status;
    }

    ++scan->table_index;
    scan->frames[scan->table_index].row_index = 0U;
    scan->frames[scan->table_index].copied = false;
    return MYLITE_OK;
}

static void clear_joined_table_select_scan_frame(struct mylite_table_select_join_scan_state *scan,
                                                 const struct mylite_select_table *table,
                                                 size_t table_index)
{
    if (!scan->frames[table_index].copied) {
        return;
    }
    clear_joined_table_select_row_values(scan->row, table);
    scan->frames[table_index].copied = false;
}

static void
clear_joined_table_select_scan_copies(mylite_stmt *stmt,
                                      const struct mylite_table_select_join_scan_state *scan)
{
    for (size_t index = 0U; index < scan->table_count; ++index) {
        const struct mylite_select_table *table =
            select_plan_table_const(&stmt->select_plan, index);

        if (table != NULL && scan->frames[index].copied) {
            clear_joined_table_select_row_values(scan->row, table);
        }
    }
}

static int copy_joined_table_select_row_values(struct mylite_table_select_row *row,
                                               const struct mylite_select_table *table,
                                               const struct mylite_table_select_row *source)
{
    for (size_t index = 0U; index < table->column_count; ++index) {
        size_t column_index = table->first_column_index + index;

        if (column_index >= row->value_count || index >= source->value_count ||
            mylite_expression_value_copy(&source->values[index], &row->values[column_index]) != 0) {
            for (size_t copied = 0U; copied < index; ++copied) {
                mylite_expression_value_deinit(&row->values[table->first_column_index + copied]);
            }
            return MYLITE_NOMEM;
        }
    }
    return MYLITE_OK;
}

static void clear_joined_table_select_row_values(struct mylite_table_select_row *row,
                                                 const struct mylite_select_table *table)
{
    for (size_t index = 0U; index < table->column_count; ++index) {
        size_t column_index = table->first_column_index + index;

        if (column_index < row->value_count) {
            mylite_expression_value_deinit(&row->values[column_index]);
        }
    }
}

static int evaluate_table_select_join_stage_conditions(
    mylite_stmt *stmt, struct mylite_table_select_join_materialize_state *state,
    const struct mylite_table_select_join_scan_state *scan, bool *out_matches)
{
    struct mylite_select_table_range cache_range = {0};
    struct mylite_table_select_join_condition_cache_lookup lookup = {
        .found = false,
        .matches = false,
    };
    int status = MYLITE_OK;

    if (!select_join_stage_cache_range(stmt->database, &stmt->select_plan, scan->table_index + 1U,
                                       &cache_range)) {
        return evaluate_table_select_join_stage_conditions_uncached(
            stmt, scan->row, scan->table_index + 1U, out_matches);
    }

    status = lookup_table_select_join_condition_cache(&state->condition_cache, scan, cache_range,
                                                      &lookup);
    if (status != MYLITE_OK) {
        return status;
    }
    if (lookup.found) {
        *out_matches = lookup.matches;
        return MYLITE_OK;
    }

    status = evaluate_table_select_join_stage_conditions_uncached(
        stmt, scan->row, scan->table_index + 1U, out_matches);
    if (status == MYLITE_OK) {
        status = store_table_select_join_condition_cache(stmt, &state->condition_cache, scan,
                                                         cache_range, *out_matches);
    }
    return status;
}

static int evaluate_table_select_join_stage_conditions_uncached(
    mylite_stmt *stmt, const struct mylite_table_select_row *row, size_t available_table_count,
    bool *out_matches)
{
    int status =
        evaluate_table_select_using_stage_conditions(stmt, row, available_table_count, out_matches);

    if (status != MYLITE_OK || !*out_matches) {
        return status;
    }
    return evaluate_table_select_join_stage_predicates(stmt, row, available_table_count,
                                                       out_matches);
}

static bool select_join_stage_cache_range(mylite_db *database,
                                          const struct mylite_select_plan *plan,
                                          size_t available_table_count,
                                          struct mylite_select_table_range *out_range)
{
    struct mylite_select_table_range range = {0};
    bool seen = false;

    for (size_t index = 0U; index < plan->using_column_count; ++index) {
        const struct mylite_select_join_using_column *column = &plan->using_columns[index];

        if (column->first_table + column->table_count != available_table_count) {
            continue;
        }
        if (!select_join_stage_cache_range_merge(
                (struct mylite_select_table_range){
                    .first_table = column->first_table,
                    .table_count = column->table_count,
                },
                &range, &seen)) {
            return false;
        }
    }

    for (size_t index = 0U; index < plan->join_predicate_count; ++index) {
        const struct mylite_select_join_predicate *predicate = &plan->join_predicates[index];
        struct mylite_select_table_range predicate_range = {0};

        if (predicate->first_table + predicate->table_count != available_table_count) {
            continue;
        }
        if (!select_join_predicate_cache_range(database, plan, predicate, &predicate_range) ||
            !select_join_stage_cache_range_merge(predicate_range, &range, &seen)) {
            return false;
        }
    }
    *out_range = range;

    if (!seen) {
        return false;
    }
    if (range.table_count == 0U) {
        return true;
    }
    if (range.first_table > 0U) {
        return true;
    }
    return false;
}

static bool select_join_predicate_cache_range(mylite_db *database,
                                              const struct mylite_select_plan *plan,
                                              const struct mylite_select_join_predicate *predicate,
                                              struct mylite_select_table_range *out_range)
{
    bool seen = false;
    struct mylite_select_table_range range = {
        .first_table = predicate->first_table + predicate->table_count,
    };

    if (!select_expression_referenced_table_range(database, plan, predicate->expression,
                                                  (struct mylite_select_table_range){
                                                      .first_table = predicate->first_table,
                                                      .table_count = predicate->table_count,
                                                  },
                                                  &seen, &range)) {
        *out_range = (struct mylite_select_table_range){
            .first_table = predicate->first_table,
            .table_count = predicate->table_count,
        };
        return true;
    }
    *out_range = range;
    return true;
}

// NOLINTNEXTLINE(misc-no-recursion)
static bool select_expression_referenced_table_range(mylite_db *database,
                                                     const struct mylite_select_plan *plan,
                                                     const struct mylite_sql_ast_node *expression,
                                                     struct mylite_select_table_range scope,
                                                     bool *out_seen,
                                                     struct mylite_select_table_range *out_range)
{
    if (expression == NULL) {
        return true;
    }

    if (expression->kind == MYLITE_SQL_AST_IDENTIFIER ||
        expression->kind == MYLITE_SQL_AST_QUALIFIED_IDENTIFIER) {
        size_t column_index = select_plan_column_count(plan);
        struct mylite_select_table_range column_range = {0};

        if (resolve_select_plan_column_reference_in_scope(database, plan, expression, "on clause",
                                                          scope.first_table, scope.table_count,
                                                          &column_index) != MYLITE_OK ||
            !select_column_index_table_range(plan, column_index, &column_range)) {
            return false;
        }
        return select_join_stage_cache_range_merge(column_range, out_range, out_seen);
    }

    for (const struct mylite_sql_ast_node *child = expression->first_child; child != NULL;
         child = child->next_sibling) {
        if (!select_expression_referenced_table_range(database, plan, child, scope, out_seen,
                                                      out_range)) {
            return false;
        }
    }
    return true;
}

static bool select_column_index_table_range(const struct mylite_select_plan *plan,
                                            size_t column_index,
                                            struct mylite_select_table_range *out_range)
{
    for (size_t table_index = 0U; table_index < select_plan_table_count(plan); ++table_index) {
        const struct mylite_select_table *table = select_plan_table_const(plan, table_index);

        if (table != NULL && column_index >= table->first_column_index &&
            column_index < table->first_column_index + table->column_count) {
            *out_range = (struct mylite_select_table_range){
                .first_table = table_index,
                .table_count = 1U,
            };
            return true;
        }
    }
    return false;
}

static bool select_join_stage_cache_range_merge(struct mylite_select_table_range candidate,
                                                struct mylite_select_table_range *out_range,
                                                bool *out_seen)
{
    size_t range_start = out_range->first_table;
    size_t range_end = out_range->first_table + out_range->table_count;
    size_t candidate_end = candidate.first_table + candidate.table_count;

    if (!*out_seen) {
        *out_range = candidate;
        *out_seen = true;
        return true;
    }
    if (candidate.table_count == 0U) {
        return true;
    }
    if (out_range->table_count == 0U) {
        *out_range = candidate;
        return true;
    }
    if (candidate.first_table < range_start) {
        range_start = candidate.first_table;
    }
    if (candidate_end > range_end) {
        range_end = candidate_end;
    }
    out_range->first_table = range_start;
    out_range->table_count = range_end - range_start;
    return true;
}

static int lookup_table_select_join_condition_cache(
    const struct mylite_table_select_join_condition_cache *cache,
    const struct mylite_table_select_join_scan_state *scan, struct mylite_select_table_range range,
    struct mylite_table_select_join_condition_cache_lookup *out_lookup)
{
    *out_lookup = (struct mylite_table_select_join_condition_cache_lookup){
        .found = false,
        .matches = false,
    };
    if (range.first_table > scan->table_count ||
        range.table_count > scan->table_count - range.first_table) {
        return MYLITE_UNSUPPORTED;
    }

    for (size_t index = 0U; index < cache->entry_count; ++index) {
        const struct mylite_table_select_join_condition_cache_entry *entry = &cache->entries[index];

        if (entry->first_table == range.first_table && entry->table_count == range.table_count &&
            table_select_join_cache_row_indexes_match(entry, scan)) {
            out_lookup->found = true;
            out_lookup->matches = entry->matches;
            return MYLITE_OK;
        }
    }
    return MYLITE_OK;
}

static int lookup_table_select_join_condition_cache_row(
    const struct mylite_table_select_join_condition_cache *cache,
    const struct mylite_table_select_row *row, struct mylite_select_table_range range,
    struct mylite_table_select_join_condition_cache_lookup *out_lookup)
{
    *out_lookup = (struct mylite_table_select_join_condition_cache_lookup){
        .found = false,
        .matches = false,
    };
    if (row == NULL || range.first_table > row->source_row_index_count ||
        range.table_count > row->source_row_index_count - range.first_table) {
        return MYLITE_UNSUPPORTED;
    }

    for (size_t index = 0U; index < cache->entry_count; ++index) {
        const struct mylite_table_select_join_condition_cache_entry *entry = &cache->entries[index];

        if (entry->first_table == range.first_table && entry->table_count == range.table_count &&
            table_select_join_cache_row_source_indexes_match(entry, row)) {
            out_lookup->found = true;
            out_lookup->matches = entry->matches;
            return MYLITE_OK;
        }
    }
    return MYLITE_OK;
}

static int
store_table_select_join_condition_cache(mylite_stmt *stmt,
                                        struct mylite_table_select_join_condition_cache *cache,
                                        const struct mylite_table_select_join_scan_state *scan,
                                        struct mylite_select_table_range range, bool matches)
{
    struct mylite_table_select_join_condition_cache_entry entry = {
        .first_table = range.first_table,
        .table_count = range.table_count,
        .matches = matches,
    };
    struct mylite_table_select_join_condition_cache_entry *entries = NULL;

    if (range.first_table > scan->table_count ||
        range.table_count > scan->table_count - range.first_table) {
        return MYLITE_UNSUPPORTED;
    }
    if (range.table_count != 0U) {
        entry.row_indexes = calloc(range.table_count, sizeof(*entry.row_indexes));
    }
    if (entry.row_indexes == NULL && range.table_count != 0U) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    for (size_t index = 0U; index < range.table_count; ++index) {
        entry.row_indexes[index] = scan->frames[range.first_table + index].row_index;
    }

    entries = realloc(cache->entries, (cache->entry_count + 1U) * sizeof(*cache->entries));
    if (entries == NULL) {
        free(entry.row_indexes);
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    cache->entries = entries;
    cache->entries[cache->entry_count++] = entry;
    return MYLITE_OK;
}

static int store_table_select_join_condition_cache_row(
    mylite_stmt *stmt, struct mylite_table_select_join_condition_cache *cache,
    const struct mylite_table_select_row *row, struct mylite_select_table_range range, bool matches)
{
    struct mylite_table_select_join_condition_cache_entry entry = {
        .first_table = range.first_table,
        .table_count = range.table_count,
        .matches = matches,
    };
    struct mylite_table_select_join_condition_cache_entry *entries = NULL;

    if (row == NULL || range.first_table > row->source_row_index_count ||
        range.table_count > row->source_row_index_count - range.first_table) {
        return MYLITE_UNSUPPORTED;
    }
    if (range.table_count != 0U) {
        entry.row_indexes = calloc(range.table_count, sizeof(*entry.row_indexes));
    }
    if (entry.row_indexes == NULL && range.table_count != 0U) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    for (size_t index = 0U; index < range.table_count; ++index) {
        entry.row_indexes[index] = row->source_row_indexes[range.first_table + index];
    }

    entries = realloc(cache->entries, (cache->entry_count + 1U) * sizeof(*cache->entries));
    if (entries == NULL) {
        free(entry.row_indexes);
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    cache->entries = entries;
    cache->entries[cache->entry_count++] = entry;
    return MYLITE_OK;
}

static bool table_select_join_cache_row_indexes_match(
    const struct mylite_table_select_join_condition_cache_entry *entry,
    const struct mylite_table_select_join_scan_state *scan)
{
    for (size_t index = 0U; index < entry->table_count; ++index) {
        if (entry->row_indexes[index] != scan->frames[entry->first_table + index].row_index) {
            return false;
        }
    }
    return true;
}

static bool table_select_join_cache_row_source_indexes_match(
    const struct mylite_table_select_join_condition_cache_entry *entry,
    const struct mylite_table_select_row *row)
{
    for (size_t index = 0U; index < entry->table_count; ++index) {
        if (entry->row_indexes[index] != row->source_row_indexes[entry->first_table + index]) {
            return false;
        }
    }
    return true;
}

static int evaluate_table_select_using_stage_conditions(mylite_stmt *stmt,
                                                        const struct mylite_table_select_row *row,
                                                        size_t available_table_count,
                                                        bool *out_matches)
{
    *out_matches = true;
    for (size_t index = 0U; index < stmt->select_plan.using_column_count; ++index) {
        const struct mylite_select_join_using_column *column =
            &stmt->select_plan.using_columns[index];

        if (column->first_table + column->table_count != available_table_count) {
            continue;
        }
        int status = evaluate_table_select_using_column(stmt, row, column, out_matches);

        if (status != MYLITE_OK || !*out_matches) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int evaluate_table_select_join_stage_predicates(mylite_stmt *stmt,
                                                       const struct mylite_table_select_row *row,
                                                       size_t available_table_count,
                                                       bool *out_matches)
{
    *out_matches = true;
    for (size_t index = 0U; index < stmt->select_plan.join_predicate_count; ++index) {
        const struct mylite_select_join_predicate *predicate =
            &stmt->select_plan.join_predicates[index];

        if (predicate->first_table + predicate->table_count != available_table_count) {
            continue;
        }
        int status = evaluate_table_select_expression_predicate(stmt, row, predicate->expression,
                                                                out_matches);

        if (status != MYLITE_OK || !*out_matches) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int evaluate_table_select_using_column(mylite_stmt *stmt,
                                              const struct mylite_table_select_row *row,
                                              const struct mylite_select_join_using_column *column,
                                              bool *out_matches)
{
    const struct mylite_expression_value *left = NULL;
    const struct mylite_expression_value *right = NULL;
    int comparison = 0;

    *out_matches = false;
    if (row == NULL || column->left_column_index >= row->value_count ||
        column->right_column_index >= row->value_count) {
        return set_where_predicate_eval_error(stmt);
    }

    left = &row->values[column->left_column_index];
    right = &row->values[column->right_column_index];
    if (left->kind == MYLITE_EXPRESSION_VALUE_NULL || right->kind == MYLITE_EXPRESSION_VALUE_NULL) {
        return MYLITE_OK;
    }
    if (mylite_expression_value_compare(left, right, &stmt->database->warnings, &comparison) != 0) {
        return set_where_predicate_eval_error(stmt);
    }
    *out_matches = comparison == 0;
    return MYLITE_OK;
}

static int
process_joined_table_select_full_row(mylite_stmt *stmt,
                                     struct mylite_table_select_join_materialize_state *state,
                                     const struct mylite_table_select_row *row)
{
    bool matches = false;
    bool aggregate_query = (stmt->select_plan.has_group_by || stmt->select_plan.has_aggregate ||
                            stmt->select_plan.has_having) != 0;
    int status = MYLITE_OK;

    if (stmt->select_predicate == NULL || stmt->select_constant_predicate_evaluated) {
        matches = true;
    } else {
        status = evaluate_table_select_row_predicate(stmt, row, &matches);
    }
    if (status != MYLITE_OK || !matches) {
        return status;
    }
    if (!aggregate_query) {
        return process_joined_table_select_nonaggregate_row(stmt, state, row);
    }

    struct mylite_table_select_group *group = NULL;

    status = find_table_select_group(stmt, state->groups, state->group_count, row, &group);
    if (status == MYLITE_OK && group == NULL) {
        status = append_table_select_group(stmt, &state->groups, &state->group_count, row, &group);
    }
    if (status == MYLITE_OK) {
        status = update_table_select_group(stmt, group, row);
    }
    return status;
}

static int process_joined_table_select_nonaggregate_row(
    mylite_stmt *stmt, struct mylite_table_select_join_materialize_state *state,
    const struct mylite_table_select_row *row)
{
    bool distinct = select_duplicate_mode_is_distinct(stmt->select_plan.duplicate_mode);

    if (stmt->select_plan.order_key_count != 0U || distinct) {
        struct mylite_table_select_row copy = {0};
        int status = table_select_row_copy(row, &copy);
        bool duplicate = false;

        if (status == MYLITE_NOMEM) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        }
        if (status == MYLITE_OK && distinct) {
            status = check_table_select_distinct_duplicate(stmt, &copy, &duplicate);
        }
        if (status == MYLITE_OK && duplicate) {
            mylite_statement_table_select_row_deinit(&copy);
            return MYLITE_OK;
        }
        if (status == MYLITE_OK && stmt->select_plan.order_key_count != 0U) {
            status = evaluate_table_select_order_values(stmt, &copy);
        }
        if (status == MYLITE_OK) {
            status = append_table_select_result_row(stmt, &copy);
        }
        mylite_statement_table_select_row_deinit(&copy);
        return status;
    }

    if (table_select_limit_row_is_kept(&stmt->select_plan.limit,
                                       (struct mylite_select_limit_position){
                                           .matched_row = state->matched_row,
                                           .kept_count = stmt->select_result.row_count,
                                       })) {
        int status = append_table_select_result_row_copy(stmt, row);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    if (state->matched_row != UINT64_MAX) {
        ++state->matched_row;
    }
    if (table_select_limit_is_full(&stmt->select_plan.limit, stmt->select_result.row_count)) {
        state->stop = true;
    }
    return MYLITE_OK;
}

static int materialize_aggregate_table_select_result(mylite_stmt *stmt)
{
    struct mylite_table_select_group *groups = NULL;
    size_t group_count = 0U;
    int status = scan_aggregate_table_select_groups(stmt, &groups, &group_count);

    if (status == MYLITE_OK && group_count == 0U && !stmt->select_plan.has_group_by) {
        status = append_empty_implicit_table_select_group(stmt, &groups, &group_count);
    }
    if (status == MYLITE_OK) {
        status = append_finalized_table_select_groups(stmt, groups, group_count);
    }
    if (status == MYLITE_OK && stmt->select_plan.order_key_count != 0U) {
        status = sort_table_select_result_rows(stmt);
    }
    if (status == MYLITE_OK) {
        status = apply_table_select_limit(stmt);
    }

    for (size_t index = 0U; index < group_count; ++index) {
        table_select_group_deinit(&groups[index]);
    }
    free(groups);
    return status;
}

static int scan_aggregate_table_select_groups(mylite_stmt *stmt,
                                              struct mylite_table_select_group **groups,
                                              size_t *group_count)
{
    int status = evaluate_table_select_constant_predicate(stmt);
    int rc = SQLITE_OK;

    *groups = NULL;
    *group_count = 0U;
    if (status != MYLITE_OK) {
        return status;
    }
    if (stmt->select_constant_predicate_evaluated && !stmt->select_constant_predicate_matches) {
        return MYLITE_OK;
    }

    while ((rc = sqlite3_step(stmt->sqlite_stmt)) == SQLITE_ROW) {
        struct mylite_table_select_group *group = NULL;
        struct mylite_table_select_row row = {0};
        bool matches = false;

        status = copy_table_select_sqlite_row(stmt, &row);
        if (status != MYLITE_OK) {
            return status;
        }
        status = evaluate_table_select_row_matches(stmt, &row, &matches);
        if (status != MYLITE_OK) {
            mylite_statement_table_select_row_deinit(&row);
            return status;
        }
        if (!matches) {
            mylite_statement_table_select_row_deinit(&row);
            continue;
        }

        status = find_table_select_group(stmt, *groups, *group_count, &row, &group);
        if (status == MYLITE_OK && group == NULL) {
            status = append_table_select_group(stmt, groups, group_count, &row, &group);
        }
        if (status == MYLITE_OK) {
            status = update_table_select_group(stmt, group, &row);
        }
        mylite_statement_table_select_row_deinit(&row);
        if (status != MYLITE_OK) {
            return status;
        }
    }
    if (rc != SQLITE_DONE) {
        status = mylite_diagnostics_set_sqlite_error(stmt->database);
    }
    return status;
}

static int append_empty_implicit_table_select_group(mylite_stmt *stmt,
                                                    struct mylite_table_select_group **groups,
                                                    size_t *group_count)
{
    struct mylite_table_select_group *new_groups = calloc(1U, sizeof(*new_groups));

    if (new_groups == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    *groups = new_groups;
    *group_count = 1U;
    (*groups)[0].aggregate_states =
        calloc(stmt->select_plan.aggregate_binding_count, sizeof(*(*groups)[0].aggregate_states));
    if ((*groups)[0].aggregate_states == NULL && stmt->select_plan.aggregate_binding_count != 0U) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    (*groups)[0].aggregate_state_count = stmt->select_plan.aggregate_binding_count;
    return MYLITE_OK;
}

static int append_finalized_table_select_groups(mylite_stmt *stmt,
                                                struct mylite_table_select_group *groups,
                                                size_t group_count)
{
    for (size_t index = 0U; index < group_count; ++index) {
        int status = append_finalized_table_select_group(stmt, &groups[index]);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int append_finalized_table_select_group(mylite_stmt *stmt,
                                               struct mylite_table_select_group *group)
{
    struct mylite_table_select_row row = {0};
    bool having_matches = true;
    bool duplicate = false;
    int status = finalize_table_select_group(stmt, group, &row);

    if (status == MYLITE_OK) {
        status = evaluate_table_select_having(stmt, &row, &having_matches);
    }
    if (status == MYLITE_OK && having_matches &&
        select_duplicate_mode_is_distinct(stmt->select_plan.duplicate_mode)) {
        status = check_table_select_distinct_duplicate(stmt, &row, &duplicate);
    }
    if (status == MYLITE_OK && duplicate) {
        mylite_statement_table_select_row_deinit(&row);
        return MYLITE_OK;
    }
    if (status == MYLITE_OK && having_matches && stmt->select_plan.order_key_count != 0U) {
        status = evaluate_table_select_order_values(stmt, &row);
    }
    if (status == MYLITE_OK && having_matches) {
        status = append_table_select_result_row(stmt, &row);
    }
    mylite_statement_table_select_row_deinit(&row);
    return status;
}

static int evaluate_table_select_row_matches(mylite_stmt *stmt,
                                             const struct mylite_table_select_row *row,
                                             bool *out_matches)
{
    *out_matches = true;
    int status = evaluate_table_select_join_conditions(stmt, row, out_matches);

    if (status != MYLITE_OK || !*out_matches) {
        return status;
    }
    if (stmt->select_predicate == NULL || stmt->select_constant_predicate_evaluated) {
        return MYLITE_OK;
    }
    return evaluate_table_select_row_predicate(stmt, row, out_matches);
}

static int evaluate_table_select_join_conditions(mylite_stmt *stmt,
                                                 const struct mylite_table_select_row *row,
                                                 bool *out_matches)
{
    int status = evaluate_table_select_using_conditions(stmt, row, out_matches);

    if (status != MYLITE_OK || !*out_matches) {
        return status;
    }
    return evaluate_table_select_join_predicates(stmt, row, out_matches);
}

static int evaluate_table_select_using_conditions(mylite_stmt *stmt,
                                                  const struct mylite_table_select_row *row,
                                                  bool *out_matches)
{
    *out_matches = true;
    for (size_t index = 0U; index < stmt->select_plan.using_column_count; ++index) {
        const struct mylite_select_join_using_column *column =
            &stmt->select_plan.using_columns[index];
        const struct mylite_expression_value *left = NULL;
        const struct mylite_expression_value *right = NULL;

        if (row == NULL || column->left_column_index >= row->value_count ||
            column->right_column_index >= row->value_count) {
            return set_where_predicate_eval_error(stmt);
        }
        left = &row->values[column->left_column_index];
        right = &row->values[column->right_column_index];
        if (left->kind == MYLITE_EXPRESSION_VALUE_NULL ||
            right->kind == MYLITE_EXPRESSION_VALUE_NULL ||
            compare_table_select_values(left, right) != 0) {
            *out_matches = false;
            return MYLITE_OK;
        }
    }
    return MYLITE_OK;
}

static int evaluate_table_select_join_predicates(mylite_stmt *stmt,
                                                 const struct mylite_table_select_row *row,
                                                 bool *out_matches)
{
    *out_matches = true;
    for (size_t index = 0U; index < stmt->select_plan.join_predicate_count; ++index) {
        int status = evaluate_table_select_expression_predicate(
            stmt, row, stmt->select_plan.join_predicates[index].expression, out_matches);

        if (status != MYLITE_OK || !*out_matches) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int check_table_select_distinct_duplicate(mylite_stmt *stmt,
                                                 struct mylite_table_select_row *row,
                                                 bool *out_duplicate)
{
    int status = materialize_table_select_output_values(stmt, row);

    *out_duplicate = false;
    if (status != MYLITE_OK) {
        return status;
    }
    *out_duplicate = table_select_distinct_row_exists(stmt, row);
    return MYLITE_OK;
}

static int append_table_select_result_row(mylite_stmt *stmt, struct mylite_table_select_row *row)
{
    struct mylite_table_select_row *rows =
        realloc(stmt->select_result.rows,
                (stmt->select_result.row_count + 1U) * sizeof(*stmt->select_result.rows));

    if (rows == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    stmt->select_result.rows = rows;
    stmt->select_result.rows[stmt->select_result.row_count++] = *row;
    *row = (struct mylite_table_select_row){0};
    return MYLITE_OK;
}

static int append_table_select_result_row_copy(mylite_stmt *stmt,
                                               const struct mylite_table_select_row *row)
{
    struct mylite_table_select_row copy = {0};
    int status = table_select_row_copy(row, &copy);

    if (status == MYLITE_NOMEM) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
    }
    if (status == MYLITE_OK) {
        status = append_table_select_result_row(stmt, &copy);
    }
    mylite_statement_table_select_row_deinit(&copy);
    return status;
}

static int table_select_row_copy(const struct mylite_table_select_row *row,
                                 struct mylite_table_select_row *out_row)
{
    int status = MYLITE_OK;

    *out_row = (struct mylite_table_select_row){0};
    out_row->value_count = row->value_count;
    out_row->output_value_count = row->output_value_count;
    out_row->order_value_count = row->order_value_count;
    out_row->aggregate_value_count = row->aggregate_value_count;
    out_row->source_row_index_count = row->source_row_index_count;

    status = allocate_table_select_row_copy(out_row);
    if (status == MYLITE_OK) {
        status = copy_table_select_row_copy_values(row, out_row);
    }
    if (status != MYLITE_OK) {
        mylite_statement_table_select_row_deinit(out_row);
    }
    return status;
}

static int allocate_table_select_row_copy(struct mylite_table_select_row *out_row)
{
    int status = allocate_table_select_expression_values(&out_row->values, out_row->value_count);

    if (status == MYLITE_OK) {
        status = allocate_table_select_expression_values(&out_row->output_values,
                                                         out_row->output_value_count);
    }
    if (status == MYLITE_OK) {
        status = allocate_table_select_expression_values(&out_row->order_values,
                                                         out_row->order_value_count);
    }
    if (status == MYLITE_OK) {
        status = allocate_table_select_expression_values(&out_row->aggregate_values,
                                                         out_row->aggregate_value_count);
    }
    if (status == MYLITE_OK) {
        status = allocate_table_select_source_row_indexes(&out_row->source_row_indexes,
                                                          out_row->source_row_index_count);
    }
    return status;
}

static int allocate_table_select_expression_values(struct mylite_expression_value **out_values,
                                                   size_t value_count)
{
    if (value_count == 0U) {
        return MYLITE_OK;
    }
    *out_values = calloc(value_count, sizeof(**out_values));
    return *out_values == NULL ? MYLITE_NOMEM : MYLITE_OK;
}

static int allocate_table_select_source_row_indexes(size_t **out_indexes, size_t index_count)
{
    if (index_count == 0U) {
        return MYLITE_OK;
    }
    *out_indexes = calloc(index_count, sizeof(**out_indexes));
    return *out_indexes == NULL ? MYLITE_NOMEM : MYLITE_OK;
}

static int copy_table_select_row_copy_values(const struct mylite_table_select_row *row,
                                             struct mylite_table_select_row *out_row)
{
    int status =
        copy_table_select_expression_values(row->values, out_row->values, out_row->value_count);

    if (status == MYLITE_OK) {
        status = copy_table_select_expression_values(row->output_values, out_row->output_values,
                                                     out_row->output_value_count);
    }
    if (status == MYLITE_OK) {
        status = copy_table_select_expression_values(row->order_values, out_row->order_values,
                                                     out_row->order_value_count);
    }
    if (status == MYLITE_OK) {
        status = copy_table_select_expression_values(
            row->aggregate_values, out_row->aggregate_values, out_row->aggregate_value_count);
    }
    if (status == MYLITE_OK && out_row->source_row_index_count != 0U) {
        memcpy(out_row->source_row_indexes, row->source_row_indexes,
               out_row->source_row_index_count * sizeof(*out_row->source_row_indexes));
    }
    return status;
}

static int copy_table_select_expression_values(const struct mylite_expression_value *values,
                                               struct mylite_expression_value *out_values,
                                               size_t value_count)
{
    for (size_t index = 0U; index < value_count; ++index) {
        if (mylite_expression_value_copy(&values[index], &out_values[index]) != 0) {
            return MYLITE_NOMEM;
        }
    }
    return MYLITE_OK;
}

static int copy_table_select_sqlite_row(mylite_stmt *stmt, struct mylite_table_select_row *out_row)
{
    size_t column_count = select_plan_column_count(&stmt->select_plan);

    if (column_count == 0U) {
        *out_row = (struct mylite_table_select_row){0};
        return MYLITE_OK;
    }
    out_row->values = calloc(column_count, sizeof(*out_row->values));
    if (out_row->values == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    out_row->value_count = column_count;

    for (size_t index = 0U; index < column_count; ++index) {
        int status = copy_table_select_column_value(stmt, index, &out_row->values[index]);

        if (status != 0) {
            mylite_statement_table_select_row_deinit(out_row);
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
    }
    return MYLITE_OK;
}

static int copy_sqlite_column_value(sqlite3_stmt *sqlite_stmt, size_t column_index,
                                    struct mylite_expression_value *out_value)
{
    int sqlite_type = SQLITE_NULL;

    if (sqlite_stmt == NULL) {
        return -1;
    }

    sqlite_type = sqlite3_column_type(sqlite_stmt, (int)column_index);
    switch (sqlite_type) {
    case SQLITE_NULL:
        *out_value = (struct mylite_expression_value){.kind = MYLITE_EXPRESSION_VALUE_NULL};
        return 0;
    case SQLITE_INTEGER:
        *out_value = (struct mylite_expression_value){
            .kind = MYLITE_EXPRESSION_VALUE_INT64,
            .int64_value = sqlite3_column_int64(sqlite_stmt, (int)column_index)};
        return 0;
    case SQLITE_FLOAT:
        *out_value = (struct mylite_expression_value){
            .kind = MYLITE_EXPRESSION_VALUE_REAL,
            .real_value = sqlite3_column_double(sqlite_stmt, (int)column_index)};
        return 0;
    case SQLITE_TEXT:
    case SQLITE_BLOB: {
        const unsigned char *text = sqlite3_column_text(sqlite_stmt, (int)column_index);
        int bytes = sqlite3_column_bytes(sqlite_stmt, (int)column_index);

        out_value->kind = MYLITE_EXPRESSION_VALUE_TEXT;
        out_value->preserve_temporal_fraction_digits = false;
        out_value->text_length = bytes < 0 ? 0U : (size_t)bytes;
        out_value->text_value = mylite_copy_span_text((const char *)text, out_value->text_length);
        return out_value->text_value == NULL ? -1 : 0;
    }
    default:
        break;
    }
    return -1;
}

static int append_table_select_group(mylite_stmt *stmt, struct mylite_table_select_group **groups,
                                     size_t *group_count, const struct mylite_table_select_row *row,
                                     struct mylite_table_select_group **out_group)
{
    struct mylite_table_select_group *new_groups =
        realloc(*groups, (*group_count + 1U) * sizeof(**groups));
    int status = MYLITE_OK;

    *out_group = NULL;
    if (new_groups == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    *groups = new_groups;
    (*groups)[*group_count] = (struct mylite_table_select_group){0};
    status = initialize_table_select_group(stmt, &(*groups)[*group_count], row);
    if (status != MYLITE_OK) {
        table_select_group_deinit(&(*groups)[*group_count]);
        return status;
    }

    *out_group = &(*groups)[*group_count];
    *group_count += 1U;
    return MYLITE_OK;
}

static int find_table_select_group(mylite_stmt *stmt, struct mylite_table_select_group *groups,
                                   size_t group_count, const struct mylite_table_select_row *row,
                                   struct mylite_table_select_group **out_group)
{
    struct mylite_expression_value *values = NULL;
    size_t value_count = stmt->select_plan.group_key_count;
    int status = MYLITE_OK;

    *out_group = NULL;
    if (value_count == 0U) {
        if (group_count != 0U) {
            *out_group = &groups[0];
        }
        return MYLITE_OK;
    }

    values = calloc(value_count, sizeof(*values));
    if (values == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    for (size_t index = 0U; index < value_count; ++index) {
        status = evaluate_table_select_group_key(stmt, row, &stmt->select_plan.group_keys[index],
                                                 &values[index]);
        if (status != MYLITE_OK) {
            goto cleanup;
        }
    }

    for (size_t group_index = 0U; group_index < group_count; ++group_index) {
        bool matches = groups[group_index].group_value_count == value_count;

        for (size_t value_index = 0U; matches && value_index < value_count; ++value_index) {
            if (compare_table_select_values(&groups[group_index].group_values[value_index],
                                            &values[value_index]) != 0) {
                matches = false;
            }
        }
        if (matches) {
            *out_group = &groups[group_index];
            break;
        }
    }

cleanup:
    for (size_t index = 0U; index < value_count; ++index) {
        mylite_expression_value_deinit(&values[index]);
    }
    free(values);
    return status;
}

static int initialize_table_select_group(mylite_stmt *stmt, struct mylite_table_select_group *group,
                                         const struct mylite_table_select_row *row)
{
    size_t column_count =
        row == NULL ? select_plan_column_count(&stmt->select_plan) : row->value_count;

    group->representative.value_count = column_count;
    if (column_count != 0U) {
        group->representative.values = calloc(column_count, sizeof(*group->representative.values));
        if (group->representative.values == NULL) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
    }
    if (row != NULL) {
        for (size_t index = 0U; index < column_count; ++index) {
            if (mylite_expression_value_copy(&row->values[index],
                                             &group->representative.values[index]) != 0) {
                (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
                return MYLITE_NOMEM;
            }
        }
        group->has_representative = true;
    }

    group->group_value_count = stmt->select_plan.group_key_count;
    group->group_values = calloc(group->group_value_count, sizeof(*group->group_values));
    if (group->group_values == NULL && group->group_value_count != 0U) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    for (size_t index = 0U; index < group->group_value_count; ++index) {
        int status = evaluate_table_select_group_key(
            stmt, row, &stmt->select_plan.group_keys[index], &group->group_values[index]);

        if (status != MYLITE_OK) {
            return status;
        }
    }

    group->aggregate_state_count = stmt->select_plan.aggregate_binding_count;
    group->aggregate_states =
        calloc(group->aggregate_state_count, sizeof(*group->aggregate_states));
    if (group->aggregate_states == NULL && group->aggregate_state_count != 0U) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    return MYLITE_OK;
}

static int update_table_select_group(mylite_stmt *stmt, struct mylite_table_select_group *group,
                                     const struct mylite_table_select_row *row)
{
    for (size_t index = 0U; index < stmt->select_plan.aggregate_binding_count; ++index) {
        int status =
            update_table_select_aggregate_state(stmt, &group->aggregate_states[index],
                                                &stmt->select_plan.aggregate_bindings[index], row);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int finalize_table_select_group(mylite_stmt *stmt, struct mylite_table_select_group *group,
                                       struct mylite_table_select_row *out_row)
{
    size_t column_count = group->representative.value_count;

    out_row->values = calloc(column_count, sizeof(*out_row->values));
    if (out_row->values == NULL && column_count != 0U) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    out_row->value_count = column_count;
    for (size_t index = 0U; index < column_count; ++index) {
        if (mylite_expression_value_copy(&group->representative.values[index],
                                         &out_row->values[index]) != 0) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
    }

    out_row->aggregate_values =
        calloc(group->aggregate_state_count, sizeof(*out_row->aggregate_values));
    if (out_row->aggregate_values == NULL && group->aggregate_state_count != 0U) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    out_row->aggregate_value_count = group->aggregate_state_count;
    for (size_t index = 0U; index < group->aggregate_state_count; ++index) {
        int status = finalize_table_select_aggregate_state(
            stmt, &group->aggregate_states[index], &stmt->select_plan.aggregate_bindings[index],
            &out_row->aggregate_values[index]);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int evaluate_table_select_group_key(mylite_stmt *stmt,
                                           const struct mylite_table_select_row *row,
                                           const struct mylite_select_group_key *group_key,
                                           struct mylite_expression_value *out_value)
{
    if (group_key->kind == MYLITE_SELECT_GROUP_KEY_OUTPUT) {
        return evaluate_table_select_cached_output_value(stmt, row, group_key->output_index,
                                                         out_value);
    }

    struct mylite_table_select_expression_context user_context = {
        .stmt = stmt,
        .row = row,
    };
    struct mylite_expression_eval_context context = {
        .user_data = &user_context,
        .resolve_identifier = resolve_table_select_expression_identifier,
        .eval_constant = evaluate_table_select_cached_constant_expression,
        .eval_aggregate = evaluate_table_select_aggregate_call,
        .eval_subquery = evaluate_table_select_subquery_expression,
        .eval_in_subquery = evaluate_table_select_in_subquery_expression,
        .eval_quantified_subquery = evaluate_table_select_quantified_subquery_expression,
        .eval_row_subquery = evaluate_table_select_row_subquery_expression,
        .eval_session_function = evaluate_table_select_session_function,
    };
    int status = mylite_expression_eval_with_context(group_key->expression, &context,
                                                     &stmt->database->warnings, out_value);

    if (status != 0) {
        return map_table_select_expression_eval_status(stmt, status);
    }
    return MYLITE_OK;
}

static int evaluate_table_select_having(mylite_stmt *stmt,
                                        const struct mylite_table_select_row *row,
                                        bool *out_matches)
{
    struct mylite_expression_value value = {0};
    int truth = -1;
    int status = 0;

    *out_matches = true;
    if (stmt->select_plan.having_expression == NULL) {
        return MYLITE_OK;
    }

    struct mylite_table_select_expression_context user_context = {
        .stmt = stmt,
        .row = row,
        .having_resolution = true,
    };
    struct mylite_expression_eval_context context = {
        .user_data = &user_context,
        .resolve_identifier = resolve_table_select_expression_identifier,
        .eval_constant = evaluate_table_select_cached_constant_expression,
        .eval_aggregate = evaluate_table_select_aggregate_call,
        .eval_subquery = evaluate_table_select_subquery_expression,
        .eval_in_subquery = evaluate_table_select_in_subquery_expression,
        .eval_quantified_subquery = evaluate_table_select_quantified_subquery_expression,
        .eval_row_subquery = evaluate_table_select_row_subquery_expression,
        .eval_session_function = evaluate_table_select_session_function,
    };

    status = mylite_expression_eval_with_context(stmt->select_plan.having_expression, &context,
                                                 &stmt->database->warnings, &value);
    if (status == 0) {
        status = mylite_expression_value_truth(&value, &stmt->database->warnings, &truth);
    }
    mylite_expression_value_deinit(&value);
    if (status != 0) {
        return map_table_select_expression_eval_status(stmt, status);
    }

    *out_matches = truth == 1;
    return MYLITE_OK;
}

static int
update_table_select_aggregate_state(mylite_stmt *stmt, struct mylite_select_aggregate_state *state,
                                    const struct mylite_select_aggregate_binding *binding,
                                    const struct mylite_table_select_row *row)
{
    struct mylite_expression_value value = {0};
    int status = MYLITE_OK;

    if (state->count != UINT64_MAX) {
        ++state->count;
    }
    if (binding->argument_kind == MYLITE_SQL_AST_AGGREGATE_ARGUMENT_STAR) {
        return MYLITE_OK;
    }
    if (binding->argument_kind == MYLITE_SQL_AST_AGGREGATE_ARGUMENT_DISTINCT_EXPRESSION_LIST) {
        return update_table_select_count_distinct_state(stmt, state, binding, row);
    }

    status = evaluate_table_select_aggregate_argument(stmt, binding, row, &value);
    if (status != MYLITE_OK) {
        return status;
    }
    if (value.kind == MYLITE_EXPRESSION_VALUE_NULL) {
        mylite_expression_value_deinit(&value);
        return MYLITE_OK;
    }
    if (state->non_null_count != UINT64_MAX) {
        ++state->non_null_count;
    }

    switch (binding->kind) {
    case MYLITE_SQL_AST_AGGREGATE_SUM:
    case MYLITE_SQL_AST_AGGREGATE_AVG: {
        struct mylite_aggregate_numeric_value numeric = {0};

        status = aggregate_value_to_double(&stmt->database->warnings, &value, &numeric);
        if (status == MYLITE_OK) {
            state->sum += numeric.value;
            if (state->non_null_count == 1U) {
                state->integral_sum = numeric.integral;
                state->unsigned_sum = numeric.unsigned_value;
            } else {
                state->integral_sum = (state->integral_sum && numeric.integral) != 0;
                state->unsigned_sum = (state->unsigned_sum && numeric.unsigned_value) != 0;
            }
        }
        break;
    }
    case MYLITE_SQL_AST_AGGREGATE_MIN:
    case MYLITE_SQL_AST_AGGREGATE_MAX:
        if (!state->has_value ||
            (binding->kind == MYLITE_SQL_AST_AGGREGATE_MIN &&
             compare_table_select_values(&value, &state->value) < 0) ||
            (binding->kind == MYLITE_SQL_AST_AGGREGATE_MAX &&
             compare_table_select_values(&value, &state->value) > 0)) {
            mylite_expression_value_deinit(&state->value);
            status =
                mylite_expression_value_copy(&value, &state->value) == 0 ? MYLITE_OK : MYLITE_NOMEM;
            state->has_value = status == MYLITE_OK;
        }
        break;
    case MYLITE_SQL_AST_AGGREGATE_COUNT:
    case MYLITE_SQL_AST_AGGREGATE_NONE:
        break;
    }

    mylite_expression_value_deinit(&value);
    if (status == MYLITE_NOMEM) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
    }
    return status;
}

static int
update_table_select_count_distinct_state(mylite_stmt *stmt,
                                         struct mylite_select_aggregate_state *state,
                                         const struct mylite_select_aggregate_binding *binding,
                                         const struct mylite_table_select_row *row)
{
    struct mylite_count_distinct_tuple tuple = {0};
    bool has_null = false;
    int status = evaluate_table_select_count_distinct_tuple(stmt, binding, row, &tuple, &has_null);

    if (status != MYLITE_OK) {
        count_distinct_tuple_deinit(&tuple);
        return status;
    }
    if (has_null || count_distinct_tuple_exists(state, &tuple, binding)) {
        count_distinct_tuple_deinit(&tuple);
        return MYLITE_OK;
    }

    status = append_count_distinct_tuple(state, &tuple);
    if (status != MYLITE_OK) {
        count_distinct_tuple_deinit(&tuple);
        if (status == MYLITE_NOMEM) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        }
        return status;
    }
    if (state->non_null_count != UINT64_MAX) {
        ++state->non_null_count;
    }
    return MYLITE_OK;
}

static int evaluate_table_select_count_distinct_tuple(
    mylite_stmt *stmt, const struct mylite_select_aggregate_binding *binding,
    const struct mylite_table_select_row *row, struct mylite_count_distinct_tuple *out_tuple,
    bool *out_has_null)
{
    size_t value_count = mylite_sql_ast_node_child_count(binding->argument);

    *out_tuple = (struct mylite_count_distinct_tuple){0};
    *out_has_null = false;
    if (value_count == 0U) {
        return MYLITE_UNSUPPORTED;
    }

    out_tuple->values = calloc(value_count, sizeof(*out_tuple->values));
    if (out_tuple->values == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    out_tuple->value_count = value_count;

    size_t index = 0U;
    for (const struct mylite_sql_ast_node *argument = binding->argument->first_child;
         argument != NULL; argument = argument->next_sibling) {
        struct mylite_select_aggregate_binding argument_binding = {
            .argument = argument,
            .argument_kind = MYLITE_SQL_AST_AGGREGATE_ARGUMENT_EXPRESSION,
        };
        int status = evaluate_table_select_aggregate_argument(stmt, &argument_binding, row,
                                                              &out_tuple->values[index]);

        if (status != MYLITE_OK) {
            return status;
        }
        if (out_tuple->values[index].kind == MYLITE_EXPRESSION_VALUE_NULL) {
            *out_has_null = true;
        }
        ++index;
    }
    return MYLITE_OK;
}

static bool count_distinct_tuple_exists(const struct mylite_select_aggregate_state *state,
                                        const struct mylite_count_distinct_tuple *tuple,
                                        const struct mylite_select_aggregate_binding *binding)
{
    for (size_t index = 0U; index < state->distinct_tuple_count; ++index) {
        if (count_distinct_tuples_equal(&state->distinct_tuples[index], tuple, binding)) {
            return true;
        }
    }
    return false;
}

static bool count_distinct_tuples_equal(const struct mylite_count_distinct_tuple *left,
                                        const struct mylite_count_distinct_tuple *right,
                                        const struct mylite_select_aggregate_binding *binding)
{
    if (left->value_count != right->value_count ||
        left->value_count != binding->argument_descriptor_count) {
        return false;
    }

    for (size_t index = 0U; index < left->value_count; ++index) {
        if (compare_table_select_distinct_values(&left->values[index], &right->values[index],
                                                 &binding->argument_descriptors[index]) != 0) {
            return false;
        }
    }
    return true;
}

static int append_count_distinct_tuple(struct mylite_select_aggregate_state *state,
                                       struct mylite_count_distinct_tuple *tuple)
{
    struct mylite_count_distinct_tuple *tuples =
        realloc(state->distinct_tuples,
                (state->distinct_tuple_count + 1U) * sizeof(*state->distinct_tuples));

    if (tuples == NULL) {
        return MYLITE_NOMEM;
    }

    state->distinct_tuples = tuples;
    state->distinct_tuples[state->distinct_tuple_count++] = *tuple;
    *tuple = (struct mylite_count_distinct_tuple){0};
    return MYLITE_OK;
}

static void count_distinct_tuple_deinit(struct mylite_count_distinct_tuple *tuple)
{
    if (tuple == NULL) {
        return;
    }

    for (size_t index = 0U; index < tuple->value_count; ++index) {
        mylite_expression_value_deinit(&tuple->values[index]);
    }
    free(tuple->values);
    *tuple = (struct mylite_count_distinct_tuple){0};
}

static void select_aggregate_state_deinit(struct mylite_select_aggregate_state *state)
{
    if (state == NULL) {
        return;
    }

    mylite_expression_value_deinit(&state->value);
    for (size_t index = 0U; index < state->distinct_tuple_count; ++index) {
        count_distinct_tuple_deinit(&state->distinct_tuples[index]);
    }
    free(state->distinct_tuples);
    *state = (struct mylite_select_aggregate_state){0};
}

static int
finalize_table_select_aggregate_state(mylite_stmt *stmt,
                                      const struct mylite_select_aggregate_state *state,
                                      const struct mylite_select_aggregate_binding *binding,
                                      struct mylite_expression_value *out_value)
{
    switch (binding->kind) {
    case MYLITE_SQL_AST_AGGREGATE_COUNT:
        *out_value = (struct mylite_expression_value){
            .kind = MYLITE_EXPRESSION_VALUE_INT64,
            .int64_value = binding->argument_kind == MYLITE_SQL_AST_AGGREGATE_ARGUMENT_STAR
                               ? (int64_t)state->count
                               : (int64_t)state->non_null_count,
        };
        return MYLITE_OK;
    case MYLITE_SQL_AST_AGGREGATE_SUM:
        if (state->non_null_count == 0U) {
            *out_value = (struct mylite_expression_value){.kind = MYLITE_EXPRESSION_VALUE_NULL};
            return MYLITE_OK;
        }
        if (state->integral_sum) {
            if (state->unsigned_sum) {
                *out_value = (struct mylite_expression_value){
                    .kind = MYLITE_EXPRESSION_VALUE_UINT64,
                    .uint64_value = (uint64_t)state->sum,
                };
            } else {
                *out_value = (struct mylite_expression_value){
                    .kind = MYLITE_EXPRESSION_VALUE_INT64,
                    .int64_value = (int64_t)state->sum,
                };
            }
            return MYLITE_OK;
        }
        return aggregate_format_double(state->sum, out_value);
    case MYLITE_SQL_AST_AGGREGATE_AVG:
        if (state->non_null_count == 0U) {
            *out_value = (struct mylite_expression_value){.kind = MYLITE_EXPRESSION_VALUE_NULL};
            return MYLITE_OK;
        }
        if (state->integral_sum) {
            *out_value = (struct mylite_expression_value){
                .kind = MYLITE_EXPRESSION_VALUE_REAL,
                .real_value = state->sum / (double)state->non_null_count,
            };
            return MYLITE_OK;
        }
        return aggregate_format_double(state->sum / (double)state->non_null_count, out_value);
    case MYLITE_SQL_AST_AGGREGATE_MIN:
    case MYLITE_SQL_AST_AGGREGATE_MAX:
        if (!state->has_value) {
            *out_value = (struct mylite_expression_value){.kind = MYLITE_EXPRESSION_VALUE_NULL};
            return MYLITE_OK;
        }
        if (mylite_expression_value_copy(&state->value, out_value) != 0) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        return MYLITE_OK;
    case MYLITE_SQL_AST_AGGREGATE_NONE:
        break;
    }

    *out_value = (struct mylite_expression_value){.kind = MYLITE_EXPRESSION_VALUE_NULL};
    return MYLITE_OK;
}

static int evaluate_table_select_aggregate_argument(
    mylite_stmt *stmt, const struct mylite_select_aggregate_binding *binding,
    const struct mylite_table_select_row *row, struct mylite_expression_value *out_value)
{
    struct mylite_table_select_expression_context user_context = {
        .stmt = stmt,
        .row = row,
    };
    struct mylite_expression_eval_context context = {
        .user_data = &user_context,
        .resolve_identifier = resolve_table_select_expression_identifier,
        .eval_constant = evaluate_table_select_cached_constant_expression,
        .eval_aggregate = evaluate_table_select_aggregate_call,
        .eval_subquery = evaluate_table_select_subquery_expression,
        .eval_in_subquery = evaluate_table_select_in_subquery_expression,
        .eval_quantified_subquery = evaluate_table_select_quantified_subquery_expression,
        .eval_row_subquery = evaluate_table_select_row_subquery_expression,
        .eval_session_function = evaluate_table_select_session_function,
    };
    int status = mylite_expression_eval_with_context(binding->argument, &context,
                                                     &stmt->database->warnings, out_value);

    if (status != 0) {
        return map_table_select_expression_eval_status(stmt, status);
    }
    return MYLITE_OK;
}

static int append_aggregate_numeric_conversion_warning(struct mylite_expression_warnings *warnings,
                                                       const char *text)
{
    enum {
        message_size = 256,
        excerpt_length = 128,
    };
    char message[message_size];
    int length = snprintf(message, sizeof(message), "Truncated incorrect DOUBLE value: '%.*s'",
                          excerpt_length, text == NULL ? "" : text);

    if (length < 0) {
        return MYLITE_NOMEM;
    }
    return mylite_expression_warnings_append(warnings, MYLITE_MYSQL_ER_TRUNCATED_WRONG_VALUE,
                                             message) == 0
               ? MYLITE_OK
               : MYLITE_NOMEM;
}

static int aggregate_value_to_double(struct mylite_expression_warnings *warnings,
                                     const struct mylite_expression_value *value,
                                     struct mylite_aggregate_numeric_value *out_value)
{
    char *copy = NULL;
    char *start = NULL;
    char *end = NULL;

    *out_value = (struct mylite_aggregate_numeric_value){0};
    if (value->kind == MYLITE_EXPRESSION_VALUE_INT64) {
        out_value->value = (double)value->int64_value;
        out_value->integral = true;
        return MYLITE_OK;
    }
    if (value->kind == MYLITE_EXPRESSION_VALUE_UINT64) {
        out_value->value = (double)value->uint64_value;
        out_value->integral = true;
        out_value->unsigned_value = true;
        return MYLITE_OK;
    }
    if (value->kind == MYLITE_EXPRESSION_VALUE_REAL) {
        out_value->value = value->real_value;
        return MYLITE_OK;
    }
    if (value->kind == MYLITE_EXPRESSION_VALUE_NULL) {
        return MYLITE_OK;
    }

    copy = mylite_copy_span_text(value->text_value == NULL ? "" : value->text_value,
                                 value->text_value == NULL ? 0U : value->text_length);
    if (copy == NULL) {
        return MYLITE_NOMEM;
    }
    start = copy;
    while (isspace((unsigned char)*start)) {
        ++start;
    }
    errno = 0;
    out_value->value = strtod(start, &end);
    while (end != NULL && isspace((unsigned char)*end)) {
        ++end;
    }
    if (end == start || (end != NULL && *end != '\0')) {
        int status = append_aggregate_numeric_conversion_warning(warnings, copy);

        if (end == start) {
            out_value->value = 0.0;
        }
        free(copy);
        return status;
    }
    free(copy);
    return MYLITE_OK;
}

static int aggregate_format_double(double value, struct mylite_expression_value *out_value)
{
    enum { double_buffer_size = 64 };
    char buffer[double_buffer_size];
    int length = snprintf(buffer, sizeof(buffer), "%.16g", value);

    if (length < 0) {
        return MYLITE_NOMEM;
    }
    out_value->kind = MYLITE_EXPRESSION_VALUE_TEXT;
    out_value->text_value = mylite_copy_span_text(buffer, (size_t)length);
    out_value->text_length = (size_t)length;
    return out_value->text_value == NULL ? MYLITE_NOMEM : MYLITE_OK;
}

static int evaluate_table_select_order_values(mylite_stmt *stmt,
                                              struct mylite_table_select_row *row)
{
    size_t order_key_count = stmt->select_plan.order_key_count;

    row->order_values = calloc(order_key_count, sizeof(*row->order_values));
    if (row->order_values == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    row->order_value_count = order_key_count;

    for (size_t index = 0U; index < order_key_count; ++index) {
        int status = evaluate_table_select_order_key(
            stmt, row, &stmt->select_plan.order_keys[index], &row->order_values[index]);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int evaluate_table_select_order_key(mylite_stmt *stmt,
                                           const struct mylite_table_select_row *row,
                                           const struct mylite_select_order_key *order_key,
                                           struct mylite_expression_value *out_value)
{
    if (order_key->kind == MYLITE_SELECT_ORDER_KEY_OUTPUT) {
        return evaluate_table_select_cached_output_value(stmt, row, order_key->output_index,
                                                         out_value);
    }

    struct mylite_table_select_expression_context user_context = {
        .stmt = stmt,
        .row = row,
        .order_resolution = true,
    };
    struct mylite_expression_eval_context context = {
        .user_data = &user_context,
        .resolve_identifier = resolve_table_select_expression_identifier,
        .eval_constant = evaluate_table_select_cached_constant_expression,
        .eval_aggregate = evaluate_table_select_aggregate_call,
        .eval_subquery = evaluate_table_select_subquery_expression,
        .eval_in_subquery = evaluate_table_select_in_subquery_expression,
        .eval_quantified_subquery = evaluate_table_select_quantified_subquery_expression,
        .eval_row_subquery = evaluate_table_select_row_subquery_expression,
        .eval_session_function = evaluate_table_select_session_function,
    };
    int status = mylite_expression_eval_with_context(order_key->expression, &context,
                                                     &stmt->database->warnings, out_value);

    if (status != 0) {
        return map_table_select_expression_eval_status(stmt, status);
    }
    return MYLITE_OK;
}

static int sort_table_select_result_rows(mylite_stmt *stmt)
{
    size_t row_count = stmt->select_result.row_count;
    struct mylite_table_select_row *scratch = NULL;
    int status = MYLITE_OK;

    if (row_count < 2U) {
        return MYLITE_OK;
    }

    scratch = calloc(row_count, sizeof(*scratch));
    if (scratch == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    status = merge_sort_table_select_rows(stmt->select_result.rows, scratch, 0U, row_count,
                                          &stmt->select_plan);
    free(scratch);
    return status;
}

// NOLINTNEXTLINE(misc-no-recursion)
static int merge_sort_table_select_rows(struct mylite_table_select_row *rows,
                                        struct mylite_table_select_row *scratch, size_t first,
                                        size_t last, const struct mylite_select_plan *plan)
{
    size_t count = last - first;
    size_t middle = first + (count / 2U);

    if (count < 2U) {
        return MYLITE_OK;
    }

    int status = merge_sort_table_select_rows(rows, scratch, first, middle, plan);

    if (status == MYLITE_OK) {
        status = merge_sort_table_select_rows(rows, scratch, middle, last, plan);
    }
    if (status == MYLITE_OK) {
        merge_table_select_rows(rows, scratch, first, middle, last, plan);
    }
    return status;
}

static void merge_table_select_rows(struct mylite_table_select_row *rows,
                                    struct mylite_table_select_row *scratch, size_t first,
                                    size_t middle, size_t last,
                                    const struct mylite_select_plan *plan)
{
    size_t left = first;
    size_t right = middle;
    size_t output = first;

    while (left < middle && right < last) {
        if (compare_table_select_rows(&rows[left], &rows[right], plan) <= 0) {
            scratch[output++] = rows[left++];
        } else {
            scratch[output++] = rows[right++];
        }
    }
    while (left < middle) {
        scratch[output++] = rows[left++];
    }
    while (right < last) {
        scratch[output++] = rows[right++];
    }
    for (size_t index = first; index < last; ++index) {
        rows[index] = scratch[index];
    }
}

static int compare_table_select_rows(const struct mylite_table_select_row *left,
                                     const struct mylite_table_select_row *right,
                                     const struct mylite_select_plan *plan)
{
    for (size_t index = 0U; index < plan->order_key_count; ++index) {
        int comparison =
            compare_table_select_values(&left->order_values[index], &right->order_values[index]);

        if (comparison != 0) {
            if (plan->order_keys[index].direction == MYLITE_SQL_AST_KEY_PART_ORDER_DESC) {
                comparison = -comparison;
            }
            return comparison;
        }
    }
    return 0;
}

static int materialize_table_select_output_values(mylite_stmt *stmt,
                                                  struct mylite_table_select_row *row)
{
    if (row->output_value_count == stmt->select_plan.output_count) {
        return MYLITE_OK;
    }

    row->output_values = calloc(stmt->select_plan.output_count, sizeof(*row->output_values));
    if (row->output_values == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    row->output_value_count = stmt->select_plan.output_count;

    for (size_t index = 0U; index < stmt->select_plan.output_count; ++index) {
        int status =
            evaluate_table_select_output_value(stmt, row, index, &row->output_values[index]);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static bool table_select_distinct_row_exists(const mylite_stmt *stmt,
                                             const struct mylite_table_select_row *row)
{
    for (size_t index = 0U; index < stmt->select_result.row_count; ++index) {
        if (table_select_output_values_equal(stmt, &stmt->select_result.rows[index], row)) {
            return true;
        }
    }
    return false;
}

static bool table_select_output_values_equal(const mylite_stmt *stmt,
                                             const struct mylite_table_select_row *left,
                                             const struct mylite_table_select_row *right)
{
    if (left->output_value_count != stmt->select_plan.output_count ||
        right->output_value_count != stmt->select_plan.output_count) {
        return false;
    }

    for (size_t index = 0U; index < stmt->select_plan.output_count; ++index) {
        const struct mylite_field_descriptor *descriptor =
            index < stmt->result_metadata.column_count
                ? &stmt->result_metadata.columns[index].descriptor
                : NULL;

        if (compare_table_select_distinct_values(&left->output_values[index],
                                                 &right->output_values[index], descriptor) != 0) {
            return false;
        }
    }
    return true;
}

static int compare_table_select_distinct_values(const struct mylite_expression_value *left,
                                                const struct mylite_expression_value *right,
                                                const struct mylite_field_descriptor *descriptor)
{
    bool left_null = left->kind == MYLITE_EXPRESSION_VALUE_NULL;
    bool right_null = right->kind == MYLITE_EXPRESSION_VALUE_NULL;

    if (left_null || right_null) {
        if (left_null == right_null) {
            return 0;
        }
        if (left_null) {
            return -1;
        }
        return 1;
    }
    if (left->kind == MYLITE_EXPRESSION_VALUE_TEXT && right->kind == MYLITE_EXPRESSION_VALUE_TEXT &&
        table_select_text_descriptor_is_binary(descriptor)) {
        return compare_table_select_binary_text_values(
            left->text_value, expression_value_text_length(left), right->text_value,
            expression_value_text_length(right));
    }
    return compare_table_select_values(left, right);
}

static int compare_table_select_values(const struct mylite_expression_value *left,
                                       const struct mylite_expression_value *right)
{
    bool left_null = left->kind == MYLITE_EXPRESSION_VALUE_NULL;
    bool right_null = right->kind == MYLITE_EXPRESSION_VALUE_NULL;

    if (left_null || right_null) {
        if (left_null == right_null) {
            return 0;
        }
        if (left_null) {
            return -1;
        }
        return 1;
    }
    if (left->kind == MYLITE_EXPRESSION_VALUE_TEXT && right->kind == MYLITE_EXPRESSION_VALUE_TEXT) {
        return compare_table_select_text_values(
            left->text_value, expression_value_text_length(left), right->text_value,
            expression_value_text_length(right));
    }
    if (left->kind == MYLITE_EXPRESSION_VALUE_REAL || right->kind == MYLITE_EXPRESSION_VALUE_REAL) {
        double left_value = left->kind == MYLITE_EXPRESSION_VALUE_REAL
                                ? left->real_value
                                : (double)mylite_expression_value_to_int64(left);
        double right_value = right->kind == MYLITE_EXPRESSION_VALUE_REAL
                                 ? right->real_value
                                 : (double)mylite_expression_value_to_int64(right);

        return (left_value > right_value) - (left_value < right_value);
    }
    if (left->kind == MYLITE_EXPRESSION_VALUE_UINT64 ||
        right->kind == MYLITE_EXPRESSION_VALUE_UINT64) {
        uint64_t left_value = left->kind == MYLITE_EXPRESSION_VALUE_UINT64
                                  ? left->uint64_value
                                  : (uint64_t)mylite_expression_value_to_int64(left);
        uint64_t right_value = right->kind == MYLITE_EXPRESSION_VALUE_UINT64
                                   ? right->uint64_value
                                   : (uint64_t)mylite_expression_value_to_int64(right);

        return (left_value > right_value) - (left_value < right_value);
    }
    if (left->kind == MYLITE_EXPRESSION_VALUE_TEXT || right->kind == MYLITE_EXPRESSION_VALUE_TEXT) {
        char *left_text = mylite_expression_value_to_text(left);
        char *right_text = mylite_expression_value_to_text(right);
        int comparison =
            compare_table_select_text_values(left_text, nullable_text_length(left_text), right_text,
                                             nullable_text_length(right_text));

        free(left_text);
        free(right_text);
        return comparison;
    }
    return (left->int64_value > right->int64_value) - (left->int64_value < right->int64_value);
}

static int compare_table_select_text_values(const char *left, size_t left_length, const char *right,
                                            size_t right_length)
{
    size_t index = 0U;
    size_t compare_length = 0U;

    if (left == NULL) {
        left = "";
        left_length = 0U;
    }
    if (right == NULL) {
        right = "";
        right_length = 0U;
    }
    compare_length = left_length < right_length ? left_length : right_length;
    while (index < compare_length) {
        unsigned char left_byte = (unsigned char)left[index];
        unsigned char right_byte = (unsigned char)right[index];

        if (left_byte >= 'A' && left_byte <= 'Z') {
            left_byte = (unsigned char)(left_byte - 'A' + 'a');
        }
        if (right_byte >= 'A' && right_byte <= 'Z') {
            right_byte = (unsigned char)(right_byte - 'A' + 'a');
        }
        if (left_byte != right_byte) {
            return (left_byte > right_byte) - (left_byte < right_byte);
        }
        ++index;
    }
    return (left_length > right_length) - (left_length < right_length);
}

static int compare_table_select_binary_text_values(const char *left, size_t left_length,
                                                   const char *right, size_t right_length)
{
    size_t compare_length = 0U;
    int comparison = 0;

    if (left == NULL) {
        left = "";
        left_length = 0U;
    }
    if (right == NULL) {
        right = "";
        right_length = 0U;
    }
    compare_length = left_length < right_length ? left_length : right_length;
    comparison = compare_length == 0U ? 0 : memcmp(left, right, compare_length);
    if (comparison == 0) {
        return (left_length > right_length) - (left_length < right_length);
    }
    return (comparison > 0) - (comparison < 0);
}

static size_t expression_value_text_length(const struct mylite_expression_value *value)
{
    if (value == NULL || value->text_value == NULL) {
        return 0U;
    }
    return value->text_length;
}

static size_t nullable_text_length(const char *text)
{
    return text == NULL ? 0U : strlen(text);
}

static bool table_select_text_descriptor_is_binary(const struct mylite_field_descriptor *descriptor)
{
    if (descriptor == NULL) {
        return false;
    }
    switch (descriptor->type) {
    case MYLITE_FIELD_TYPE_STRING:
    case MYLITE_FIELD_TYPE_VAR_STRING:
    case MYLITE_FIELD_TYPE_BLOB:
        if ((descriptor->flags & MYLITE_FIELD_FLAG_BINARY) != 0U) {
            return true;
        }
        if (descriptor->charset_id == mylite_mysql_binary_charset_id ||
            descriptor->charset_id == mylite_mysql_utf8mb4_bin_charset_id) {
            return true;
        }
        return false;
    default:
        return false;
    }
}

static int apply_table_select_limit(mylite_stmt *stmt)
{
    const struct mylite_select_limit *limit = &stmt->select_plan.limit;
    size_t kept = 0U;

    if (!limit->has_limit) {
        return MYLITE_OK;
    }

    for (size_t index = 0U; index < stmt->select_result.row_count; ++index) {
        if (table_select_limit_row_is_kept(limit, (struct mylite_select_limit_position){
                                                      .matched_row = (uint64_t)index,
                                                      .kept_count = kept,
                                                  })) {
            if (kept != index) {
                stmt->select_result.rows[kept] = stmt->select_result.rows[index];
                stmt->select_result.rows[index] = (struct mylite_table_select_row){0};
            }
            ++kept;
        } else {
            mylite_statement_table_select_row_deinit(&stmt->select_result.rows[index]);
        }
    }
    stmt->select_result.row_count = kept;
    return MYLITE_OK;
}

static bool table_select_limit_row_is_kept(const struct mylite_select_limit *limit,
                                           struct mylite_select_limit_position position)
{
    if (!limit->has_limit) {
        return true;
    }
    if (position.matched_row < limit->offset) {
        return false;
    }
    if (table_select_limit_is_full(limit, position.kept_count)) {
        return false;
    }
    return true;
}

static bool table_select_limit_is_full(const struct mylite_select_limit *limit, size_t kept_count)
{
    if (!limit->has_limit) {
        return false;
    }
    if (limit->row_count > (uint64_t)SIZE_MAX) {
        return false;
    }
    return kept_count >= (size_t)limit->row_count;
}

static int set_table_select_current_row(mylite_stmt *stmt,
                                        const struct mylite_table_select_row *row)
{
    mylite_statement_table_select_current_values_deinit(&stmt->select_result);

    stmt->select_result.current_values =
        calloc(stmt->select_plan.output_count, sizeof(*stmt->select_result.current_values));
    stmt->select_result.current_texts =
        (char **)calloc(stmt->select_plan.output_count, sizeof(*stmt->select_result.current_texts));
    if (stmt->select_result.current_values == NULL || stmt->select_result.current_texts == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    stmt->select_result.current_value_count = stmt->select_plan.output_count;

    for (size_t index = 0U; index < stmt->select_plan.output_count; ++index) {
        int status = evaluate_table_select_cached_output_value(
            stmt, row, index, &stmt->select_result.current_values[index]);

        if (status != MYLITE_OK) {
            return status;
        }
        if (stmt->select_result.current_values[index].kind != MYLITE_EXPRESSION_VALUE_NULL) {
            stmt->select_result.current_texts[index] =
                mylite_expression_value_to_text(&stmt->select_result.current_values[index]);
            if (stmt->select_result.current_texts[index] == NULL) {
                (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
                return MYLITE_NOMEM;
            }
        }
    }
    stmt->select_result.has_current_row = true;
    return MYLITE_OK;
}

static int evaluate_table_select_cached_output_value(mylite_stmt *stmt,
                                                     const struct mylite_table_select_row *row,
                                                     size_t output_index,
                                                     struct mylite_expression_value *out_value)
{
    if (row != NULL && row->output_value_count == stmt->select_plan.output_count &&
        output_index < row->output_value_count) {
        if (mylite_expression_value_copy(&row->output_values[output_index], out_value) != 0) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        return MYLITE_OK;
    }
    return evaluate_table_select_output_value(stmt, row, output_index, out_value);
}

static int evaluate_table_select_output_value(mylite_stmt *stmt,
                                              const struct mylite_table_select_row *row,
                                              size_t output_index,
                                              struct mylite_expression_value *out_value)
{
    const struct mylite_select_output_column *output = &stmt->select_plan.outputs[output_index];

    if (output->kind == MYLITE_SELECT_OUTPUT_COLUMN) {
        if (copy_table_select_row_value(row, output->column_index, out_value) != 0) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        return MYLITE_OK;
    }

    struct mylite_table_select_expression_context user_context = {
        .stmt = stmt,
        .row = row,
        .order_resolution = false,
    };
    struct mylite_expression_eval_context context = {
        .user_data = &user_context,
        .resolve_identifier = resolve_table_select_expression_identifier,
        .eval_constant = evaluate_table_select_cached_constant_expression,
        .eval_aggregate = evaluate_table_select_aggregate_call,
        .eval_subquery = evaluate_table_select_subquery_expression,
        .eval_in_subquery = evaluate_table_select_in_subquery_expression,
        .eval_quantified_subquery = evaluate_table_select_quantified_subquery_expression,
        .eval_row_subquery = evaluate_table_select_row_subquery_expression,
        .eval_session_function = evaluate_table_select_session_function,
    };
    int status = mylite_expression_eval_with_context(output->expression, &context,
                                                     &stmt->database->warnings, out_value);

    if (status != 0) {
        return map_table_select_expression_eval_status(stmt, status);
    }
    return MYLITE_OK;
}

static int copy_table_select_row_value(const struct mylite_table_select_row *row,
                                       size_t column_index,
                                       struct mylite_expression_value *out_value)
{
    if (row == NULL || column_index >= row->value_count) {
        return -1;
    }
    return mylite_expression_value_copy(&row->values[column_index], out_value);
}

static void table_select_table_rowsets_deinit(struct mylite_table_select_table_rowset *rowsets,
                                              size_t rowset_count)
{
    if (rowsets == NULL) {
        return;
    }
    for (size_t rowset_index = 0U; rowset_index < rowset_count; ++rowset_index) {
        for (size_t row_index = 0U; row_index < rowsets[rowset_index].row_count; ++row_index) {
            mylite_statement_table_select_row_deinit(&rowsets[rowset_index].rows[row_index]);
        }
        free(rowsets[rowset_index].rows);
    }
    free(rowsets);
}

static void
table_select_join_condition_cache_deinit(struct mylite_table_select_join_condition_cache *cache)
{
    if (cache == NULL) {
        return;
    }
    for (size_t index = 0U; index < cache->entry_count; ++index) {
        free(cache->entries[index].row_indexes);
    }
    free(cache->entries);
    *cache = (struct mylite_table_select_join_condition_cache){0};
}

static int evaluate_table_select_constant_predicate(mylite_stmt *stmt)
{
    struct mylite_expression_value value = {0};
    int truth = -1;
    int status = 0;

    if (stmt->select_constant_predicate_evaluated ||
        !mylite_expression_is_cacheable_no_table(stmt->select_predicate)) {
        return MYLITE_OK;
    }

    status = mylite_expression_eval(stmt->select_predicate, &stmt->database->warnings, &value);
    if (status == 0) {
        status = mylite_expression_value_truth(&value, &stmt->database->warnings, &truth);
    }
    if (status != 0) {
        mylite_expression_value_deinit(&value);
        return set_where_predicate_eval_error(stmt);
    }

    stmt->select_constant_predicate_evaluated = true;
    stmt->select_constant_predicate_matches = truth == 1;
    mylite_expression_value_deinit(&value);
    return MYLITE_OK;
}

static int evaluate_table_select_expression_predicate(mylite_stmt *stmt,
                                                      const struct mylite_table_select_row *row,
                                                      const struct mylite_sql_ast_node *predicate,
                                                      bool *out_matches)
{
    struct mylite_table_select_expression_context user_context = {
        .stmt = stmt,
        .row = row,
    };
    struct mylite_expression_eval_context context = {
        .user_data = &user_context,
        .resolve_identifier = resolve_table_select_expression_identifier,
        .eval_constant = evaluate_table_select_cached_constant_expression,
        .eval_aggregate = evaluate_table_select_aggregate_call,
        .eval_subquery = evaluate_table_select_subquery_expression,
        .eval_in_subquery = evaluate_table_select_in_subquery_expression,
        .eval_quantified_subquery = evaluate_table_select_quantified_subquery_expression,
        .eval_row_subquery = evaluate_table_select_row_subquery_expression,
        .eval_session_function = evaluate_table_select_session_function,
    };
    struct mylite_expression_value value = {0};
    int truth = 0;
    int status =
        mylite_expression_eval_with_context(predicate, &context, &stmt->database->warnings, &value);

    *out_matches = false;
    if (status == 0) {
        status = mylite_expression_value_truth(&value, &stmt->database->warnings, &truth);
    }
    mylite_expression_value_deinit(&value);
    if (status != 0) {
        return map_table_select_expression_eval_status(stmt, status);
    }

    *out_matches = truth == 1;
    return MYLITE_OK;
}

static int evaluate_table_select_row_predicate(mylite_stmt *stmt,
                                               const struct mylite_table_select_row *row,
                                               bool *out_matches)
{
    return evaluate_table_select_expression_predicate(stmt, row, stmt->select_predicate,
                                                      out_matches);
}

static int evaluate_table_select_cached_constant_expression(
    void *user_data, const struct mylite_sql_ast_node *expression,
    struct mylite_expression_warnings *warnings, struct mylite_expression_value *out_value)
{
    struct mylite_table_select_expression_context *context = user_data;
    mylite_stmt *stmt = context == NULL ? NULL : context->stmt;
    struct mylite_cached_expression_value *entry = NULL;

    if (stmt == NULL || expression == NULL) {
        return -1;
    }

    for (size_t index = 0U; index < stmt->select_constant_value_count; ++index) {
        if (stmt->select_constant_values[index].expression == expression) {
            entry = &stmt->select_constant_values[index];
            break;
        }
    }
    if (entry == NULL) {
        struct mylite_cached_expression_value *values =
            realloc(stmt->select_constant_values, (stmt->select_constant_value_count + 1U) *
                                                      sizeof(*stmt->select_constant_values));

        if (values == NULL) {
            return -1;
        }
        stmt->select_constant_values = values;
        entry = &stmt->select_constant_values[stmt->select_constant_value_count++];
        *entry = (struct mylite_cached_expression_value){.expression = expression};
    }

    if (!entry->evaluated) {
        entry->status = mylite_expression_eval(expression, warnings, &entry->value);
        entry->evaluated = true;
    }
    if (entry->status != 0) {
        return entry->status;
    }
    return mylite_expression_value_copy(&entry->value, out_value);
}

static int evaluate_table_select_session_function(
    void *user_data, const struct mylite_sql_ast_node *function_call,
    const struct mylite_expression_eval_context *expression_context,
    struct mylite_expression_warnings *warnings, struct mylite_expression_value *out_value)
{
    struct mylite_table_select_expression_context *context = user_data;

    return evaluate_statement_session_function(context == NULL ? NULL : context->stmt,
                                               function_call, expression_context, warnings, NULL,
                                               out_value);
}

static int evaluate_table_select_aggregate_call(void *user_data,
                                                const struct mylite_sql_ast_node *aggregate,
                                                struct mylite_expression_value *out_value)
{
    struct mylite_table_select_expression_context *context = user_data;

    if (context == NULL || context->stmt == NULL || context->row == NULL || aggregate == NULL) {
        return -1;
    }

    for (size_t index = 0U; index < context->stmt->select_plan.aggregate_binding_count; ++index) {
        if (context->stmt->select_plan.aggregate_bindings[index].call == aggregate) {
            if (index >= context->row->aggregate_value_count) {
                return -1;
            }
            return mylite_expression_value_copy(&context->row->aggregate_values[index], out_value);
        }
    }
    return -1;
}

static int evaluate_table_select_subquery_expression(void *user_data,
                                                     const struct mylite_sql_ast_node *subquery,
                                                     struct mylite_expression_warnings *warnings,
                                                     struct mylite_expression_value *out_value)
{
    struct mylite_table_select_expression_context *context = user_data;

    if (context == NULL) {
        return MYLITE_UNSUPPORTED;
    }
    return evaluate_select_subquery_expression(context->stmt, subquery, warnings, out_value);
}

static int evaluate_table_select_in_subquery_expression(
    void *user_data, const struct mylite_sql_ast_node *expression,
    const struct mylite_expression_value *left, struct mylite_expression_warnings *warnings,
    struct mylite_expression_value *out_value)
{
    struct mylite_table_select_expression_context *context = user_data;

    if (context == NULL) {
        return MYLITE_UNSUPPORTED;
    }
    return evaluate_in_subquery_expression(context->stmt, expression, left, warnings, out_value);
}

static int evaluate_table_select_quantified_subquery_expression(
    void *user_data, const struct mylite_sql_ast_node *expression,
    const struct mylite_expression_value *left, struct mylite_expression_warnings *warnings,
    struct mylite_expression_value *out_value)
{
    struct mylite_table_select_expression_context *context = user_data;

    if (context == NULL) {
        return MYLITE_UNSUPPORTED;
    }
    return evaluate_quantified_subquery_expression(context->stmt, expression, left, warnings,
                                                   out_value);
}

static int evaluate_table_select_row_subquery_expression(
    void *user_data, const struct mylite_sql_ast_node *expression,
    const struct mylite_expression_eval_context *expression_context,
    struct mylite_expression_warnings *warnings, struct mylite_expression_value *out_value)
{
    struct mylite_table_select_expression_context *context = user_data;

    if (context == NULL) {
        return MYLITE_UNSUPPORTED;
    }
    return evaluate_row_subquery_expression(context->stmt, expression, expression_context, warnings,
                                            out_value);
}

static int resolve_table_select_expression_identifier(void *user_data,
                                                      const struct mylite_sql_ast_node *identifier,
                                                      struct mylite_expression_value *out_value)
{
    struct mylite_table_select_expression_context *context = user_data;
    size_t column_index = 0U;
    int status = MYLITE_OK;

    if (context == NULL || context->stmt == NULL) {
        return -1;
    }

    if (context->having_resolution) {
        enum mylite_select_order_key_kind kind = MYLITE_SELECT_ORDER_KEY_EXPRESSION;
        size_t index = 0U;

        status = resolve_select_having_reference_internal(
            context->stmt->database, &context->stmt->select_plan, identifier, &kind, &index, false);
        if (status != MYLITE_OK) {
            return -1;
        }
        if (kind == MYLITE_SELECT_ORDER_KEY_OUTPUT) {
            return evaluate_table_select_cached_output_value(context->stmt, context->row, index,
                                                             out_value) == MYLITE_OK
                       ? 0
                       : -1;
        }
    }

    if (context->order_resolution) {
        enum mylite_select_order_key_kind kind = MYLITE_SELECT_ORDER_KEY_EXPRESSION;
        size_t index = 0U;

        status = resolve_select_order_reference(
            context->stmt->database, &context->stmt->select_plan, identifier, &kind, &index);
        if (status != MYLITE_OK) {
            return -1;
        }
        if (kind == MYLITE_SELECT_ORDER_KEY_OUTPUT) {
            return evaluate_table_select_cached_output_value(context->stmt, context->row, index,
                                                             out_value) == MYLITE_OK
                       ? 0
                       : -1;
        }
    }

    status =
        resolve_select_plan_column_reference(context->stmt->database, &context->stmt->select_plan,
                                             identifier, "field list", &column_index);
    if (status != MYLITE_OK ||
        column_index == select_plan_column_count(&context->stmt->select_plan)) {
        return -1;
    }
    if (context->row != NULL) {
        return copy_table_select_row_value(context->row, column_index, out_value);
    }
    return copy_table_select_column_value(context->stmt, column_index, out_value);
}

static int copy_table_select_column_value(mylite_stmt *stmt, size_t column_index,
                                          struct mylite_expression_value *out_value)
{
    const struct mylite_select_column *column = NULL;
    int status = 0;

    if (stmt == NULL || stmt->sqlite_stmt == NULL ||
        column_index >= select_plan_column_count(&stmt->select_plan)) {
        return -1;
    }

    status = copy_sqlite_column_value(stmt->sqlite_stmt, column_index, out_value);
    if (status == 0) {
        column = select_plan_column_const(&stmt->select_plan, column_index, NULL);
        out_value->preserve_temporal_fraction_digits =
            field_descriptor_preserves_temporal_fraction_digits(
                column == NULL ? NULL : &column->descriptor);
        out_value->temporal_type =
            expression_temporal_type_from_descriptor(column == NULL ? NULL : &column->descriptor);
    }
    return status;
}

static int map_table_select_expression_eval_status(mylite_stmt *stmt, int status)
{
    if (status == 0) {
        return MYLITE_OK;
    }
    if (status == MYLITE_NOMEM) {
        if (stmt != NULL && stmt->database != NULL && stmt->database->error_message == NULL) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        }
        return MYLITE_NOMEM;
    }
    if (stmt != NULL && stmt->database != NULL && stmt->database->error_message != NULL) {
        return status > 0 ? status : MYLITE_EXEC_ERROR;
    }
    if (stmt == NULL || stmt->database == NULL) {
        return MYLITE_EXEC_ERROR;
    }
    return set_where_predicate_eval_error(stmt);
}

static int set_where_predicate_eval_error(mylite_stmt *stmt)
{
    mylite_db *database = stmt == NULL ? NULL : stmt->database;

    if (database == NULL) {
        return MYLITE_EXEC_ERROR;
    }
    if (database->warnings.count != 0U) {
        const struct mylite_expression_warning *warning =
            &database->warnings.items[database->warnings.count - 1U];

        if (warning->level == MYLITE_EXPRESSION_WARNING_LEVEL_ERROR) {
            int status = mylite_diagnostics_set_error_message(database, warning->message);

            return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
        }
        if (warning->code == MYLITE_MYSQL_ER_WRONG_ARGUMENTS) {
            int status = mylite_diagnostics_set_error_message(database, warning->message);

            return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
        }
    }
    return set_select_unsupported_where_error(database);
}

static int validate_insert_values_target(mylite_stmt *stmt, const char **out_schema_name)
{
    const char *schema_name = stmt->insert_values.schema_name == NULL
                                  ? stmt->database->selected_schema
                                  : stmt->insert_values.schema_name;
    struct mylite_schema_presence presence;
    bool exists = false;
    int status = MYLITE_OK;

    *out_schema_name = NULL;
    if (schema_name == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "No database selected");
        return MYLITE_EXEC_ERROR;
    }

    status = mylite_catalog_schema_exists(stmt->database, schema_name, &presence);
    if (status != MYLITE_OK) {
        return status;
    }
    if (!presence.exists) {
        (void)mylite_diagnostics_set_error_message_parts(stmt->database, "Unknown database '",
                                                         schema_name, "'");
        return MYLITE_EXEC_ERROR;
    }
    if (presence.is_system) {
        (void)mylite_diagnostics_set_error_message_parts(
            stmt->database, "Access to system schema '", schema_name, "' is rejected.");
        return MYLITE_EXEC_ERROR;
    }

    status = mylite_catalog_table_exists(stmt->database, schema_name,
                                         stmt->insert_values.table_name, &exists);
    if (status != MYLITE_OK) {
        return status;
    }
    if (!exists) {
        return set_table_doesnt_exist_error(stmt->database, schema_name,
                                            stmt->insert_values.table_name);
    }

    *out_schema_name = schema_name;
    return MYLITE_OK;
}

static int load_insert_table(mylite_stmt *stmt, const char *schema_name,
                             struct mylite_insert_table *out_table)
{
    return load_write_table(stmt, schema_name, stmt->insert_values.table_name, out_table);
}

static int load_write_table(mylite_stmt *stmt, const char *schema_name, const char *table_name,
                            struct mylite_insert_table *out_table)
{
    sqlite3_stmt *select = NULL;
    uint64_t catalog_auto_increment = 0U;
    bool has_catalog_auto_increment = false;
    static const char sql[] =
        "SELECT auto_increment FROM __mylite_table_catalog WHERE table_schema = ? "
        "AND table_name = ?";
    int rc = sqlite3_prepare_v3(stmt->database->sqlite, sql, -1, SQLITE_PREPARE_PERSISTENT, &select,
                                NULL);
    int status = MYLITE_OK;

    *out_table = (struct mylite_insert_table){0};
    if (rc != SQLITE_OK) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    sqlite3_bind_text(select, 1, schema_name, -1, sqlite_transient_destructor());
    sqlite3_bind_text(select, 2, table_name, -1, sqlite_transient_destructor());
    rc = sqlite3_step(select);
    if (rc == SQLITE_ROW && sqlite3_column_type(select, 0) != SQLITE_NULL) {
        sqlite3_int64 value = sqlite3_column_int64(select, 0);

        if (value > 0) {
            catalog_auto_increment = (uint64_t)value;
            has_catalog_auto_increment = true;
        }
    }
    sqlite3_finalize(select);
    if (rc != SQLITE_ROW) {
        return rc == SQLITE_DONE
                   ? set_table_doesnt_exist_error(stmt->database, schema_name, table_name)
                   : mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    out_table->physical_name = mylite_catalog_physical_table_name(schema_name, table_name);
    if (out_table->physical_name == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    status = load_insert_columns(stmt, schema_name, table_name, out_table);
    if (status == MYLITE_OK) {
        status = load_insert_unique_indexes(stmt, schema_name, table_name, out_table);
    }
    if (status == MYLITE_OK) {
        status = initialize_insert_auto_increment(stmt, out_table, catalog_auto_increment,
                                                  has_catalog_auto_increment);
    }
    return status;
}

static int load_insert_columns(mylite_stmt *stmt, const char *schema_name, const char *table_name,
                               struct mylite_insert_table *table)
{
    sqlite3_stmt *select = NULL;
    static const char sql[] =
        "SELECT column_name, column_default, is_nullable, data_type, extra "
        "FROM __mylite_column_catalog WHERE table_schema = ? AND table_name = ? "
        "ORDER BY ordinal_position";
    int rc = sqlite3_prepare_v3(stmt->database->sqlite, sql, -1, SQLITE_PREPARE_PERSISTENT, &select,
                                NULL);

    if (rc != SQLITE_OK) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    sqlite3_bind_text(select, 1, schema_name, -1, sqlite_transient_destructor());
    sqlite3_bind_text(select, 2, table_name, -1, sqlite_transient_destructor());
    while ((rc = sqlite3_step(select)) == SQLITE_ROW) {
        int status = load_insert_column_from_catalog_row(stmt, select, table);

        if (status != MYLITE_OK) {
            sqlite3_finalize(select);
            return status;
        }
    }
    sqlite3_finalize(select);
    if (rc != SQLITE_DONE) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }
    if (table->column_count == 0U) {
        (void)mylite_diagnostics_set_error_message(stmt->database,
                                                   "INSERT target table has no columns");
        return MYLITE_EXEC_ERROR;
    }
    return MYLITE_OK;
}

static int load_insert_column_from_catalog_row(mylite_stmt *stmt, sqlite3_stmt *select,
                                               struct mylite_insert_table *table)
{
    const char *name = (const char *)sqlite3_column_text(select, 0);
    const char *default_text = (const char *)sqlite3_column_text(select, 1);
    const char *is_nullable = (const char *)sqlite3_column_text(select, 2);
    const char *data_type = (const char *)sqlite3_column_text(select, 3);
    const char *extra = (const char *)sqlite3_column_text(select, 4);
    struct mylite_insert_table_column column = {0};
    int status = MYLITE_OK;

    if (is_nullable != NULL && mylite_ascii_case_equal(is_nullable, "YES")) {
        column.nullable = true;
    }
    column.name = mylite_copy_span_text(name, name == NULL ? 0U : strlen(name));
    if (default_text != NULL) {
        column.default_text = mylite_copy_span_text(default_text, strlen(default_text));
    }
    column.data_type = mylite_copy_span_text(data_type == NULL ? "" : data_type,
                                             data_type == NULL ? 0U : strlen(data_type));
    column.extra =
        mylite_copy_span_text(extra == NULL ? "" : extra, extra == NULL ? 0U : strlen(extra));
    if (column.name == NULL || (default_text != NULL && column.default_text == NULL) ||
        column.data_type == NULL || column.extra == NULL) {
        mylite_dml_insert_table_column_deinit(&column);
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    column.auto_increment = mylite_text_contains_word(column.extra, "auto_increment");
    column.generated_default = mylite_text_contains_word(column.extra, "DEFAULT_GENERATED");
    if (column.auto_increment) {
        table->has_auto_increment = true;
        table->auto_increment_column_index = table->column_count;
    }

    status = add_insert_table_column(table, column);
    if (status != MYLITE_OK) {
        mylite_dml_insert_table_column_deinit(&column);
        if (status == MYLITE_NOMEM) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        }
    }
    return status;
}

static int add_insert_table_column(struct mylite_insert_table *table,
                                   struct mylite_insert_table_column column)
{
    struct mylite_insert_table_column *columns =
        realloc(table->columns, (table->column_count + 1U) * sizeof(*table->columns));

    if (columns == NULL) {
        return MYLITE_NOMEM;
    }

    table->columns = columns;
    table->columns[table->column_count++] = column;
    return MYLITE_OK;
}

static int load_insert_unique_indexes(mylite_stmt *stmt, const char *schema_name,
                                      const char *table_name, struct mylite_insert_table *table)
{
    sqlite3_stmt *select = NULL;
    /* Index rows are inserted in CREATE TABLE index order. */
    static const char sql[] =
        "SELECT index_name, column_name, sub_part FROM __mylite_index_catalog "
        "WHERE table_schema = ? AND table_name = ? AND non_unique = 0 "
        "ORDER BY rowid";
    int rc = sqlite3_prepare_v3(stmt->database->sqlite, sql, -1, SQLITE_PREPARE_PERSISTENT, &select,
                                NULL);

    if (rc != SQLITE_OK) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    sqlite3_bind_text(select, 1, schema_name, -1, sqlite_transient_destructor());
    sqlite3_bind_text(select, 2, table_name, -1, sqlite_transient_destructor());
    while ((rc = sqlite3_step(select)) == SQLITE_ROW) {
        const struct mylite_insert_unique_index_part_name part = {
            .index_name = (const char *)sqlite3_column_text(select, 0),
            .column_name = (const char *)sqlite3_column_text(select, 1),
            .prefix_length = (uint64_t)sqlite3_column_int64(select, 2),
            .has_prefix_length = sqlite3_column_type(select, 2) != SQLITE_NULL,
        };
        int status = add_insert_unique_index_part(stmt->database, table, &part);

        if (status != MYLITE_OK) {
            sqlite3_finalize(select);
            return status;
        }
    }
    sqlite3_finalize(select);
    return rc == SQLITE_DONE ? MYLITE_OK : mylite_diagnostics_set_sqlite_error(stmt->database);
}

static int add_insert_unique_index_part(struct mylite_db *database,
                                        struct mylite_insert_table *table,
                                        const struct mylite_insert_unique_index_part_name *part)
{
    struct mylite_insert_unique_index *index = NULL;
    size_t column_index = insert_table_column_index(table, part->column_name);
    const struct mylite_insert_unique_index_part insert_part = {
        .column_index = column_index,
        .prefix_length = part->prefix_length,
        .has_prefix_length = part->has_prefix_length,
    };

    if (column_index == table->column_count) {
        (void)mylite_diagnostics_set_error_message_parts(
            database, "Index references unknown column '", part->column_name, "'");
        return MYLITE_EXEC_ERROR;
    }

    for (size_t current = 0U; current < table->unique_index_count; ++current) {
        if (mylite_ascii_case_equal(table->unique_indexes[current].name, part->index_name)) {
            int status =
                append_insert_unique_index_part(&table->unique_indexes[current], &insert_part);

            if (status == MYLITE_NOMEM) {
                (void)mylite_diagnostics_set_error_message(database, "out of memory");
            }
            return status;
        }
    }

    index = realloc(table->unique_indexes,
                    (table->unique_index_count + 1U) * sizeof(*table->unique_indexes));
    if (index == NULL) {
        (void)mylite_diagnostics_set_error_message(database, "out of memory");
        return MYLITE_NOMEM;
    }
    table->unique_indexes = index;
    index = &table->unique_indexes[table->unique_index_count++];
    *index = (struct mylite_insert_unique_index){
        .is_primary = mylite_ascii_case_equal(part->index_name, "PRIMARY"),
    };
    index->name = mylite_copy_span_text(part->index_name,
                                        part->index_name == NULL ? 0U : strlen(part->index_name));
    if (index->name == NULL) {
        (void)mylite_diagnostics_set_error_message(database, "out of memory");
        return MYLITE_NOMEM;
    }

    int status = append_insert_unique_index_part(index, &insert_part);
    if (status == MYLITE_NOMEM) {
        (void)mylite_diagnostics_set_error_message(database, "out of memory");
    }
    return status;
}

static int append_insert_unique_index_part(struct mylite_insert_unique_index *index,
                                           const struct mylite_insert_unique_index_part *part)
{
    size_t *column_indexes =
        realloc(index->column_indexes, (index->column_count + 1U) * sizeof(*index->column_indexes));
    uint64_t *prefix_lengths = NULL;
    uint64_t stored_prefix_length = 0U;

    if (column_indexes == NULL) {
        return MYLITE_NOMEM;
    }

    index->column_indexes = column_indexes;
    prefix_lengths =
        realloc(index->prefix_lengths, (index->column_count + 1U) * sizeof(*index->prefix_lengths));
    if (prefix_lengths == NULL) {
        return MYLITE_NOMEM;
    }
    index->prefix_lengths = prefix_lengths;
    if (part->has_prefix_length) {
        stored_prefix_length = part->prefix_length;
    }
    index->column_indexes[index->column_count++] = part->column_index;
    index->prefix_lengths[index->column_count - 1U] = stored_prefix_length;
    return MYLITE_OK;
}

static int initialize_insert_auto_increment(mylite_stmt *stmt, struct mylite_insert_table *table,
                                            uint64_t catalog_auto_increment,
                                            bool has_catalog_auto_increment)
{
    uint64_t max_next_auto_increment = 1U;
    int status = MYLITE_OK;

    if (!table->has_auto_increment) {
        return MYLITE_OK;
    }

    status = read_insert_auto_increment_max(stmt, table, &max_next_auto_increment);
    if (status != MYLITE_OK) {
        return status;
    }
    table->next_auto_increment = max_next_auto_increment;
    if (has_catalog_auto_increment && catalog_auto_increment > table->next_auto_increment) {
        table->next_auto_increment = catalog_auto_increment;
    }
    if (table->next_auto_increment == 0U) {
        table->next_auto_increment = 1U;
    }
    return MYLITE_OK;
}

static int read_insert_auto_increment_max(mylite_stmt *stmt,
                                          const struct mylite_insert_table *table,
                                          uint64_t *out_next_auto_increment)
{
    sqlite3_stmt *select = NULL;
    sqlite3_str *sql = sqlite3_str_new(stmt->database->sqlite);
    char *select_sql = NULL;
    int rc = SQLITE_OK;

    *out_next_auto_increment = 1U;
    if (sql == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    sqlite3_str_appendf(sql, "SELECT max(\"%w\") FROM \"%w\"",
                        table->columns[table->auto_increment_column_index].name,
                        table->physical_name);
    select_sql = sqlite3_str_finish(sql);
    if (select_sql == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    rc = sqlite3_prepare_v3(stmt->database->sqlite, select_sql, -1, SQLITE_PREPARE_PERSISTENT,
                            &select, NULL);
    sqlite3_free(select_sql);
    if (rc != SQLITE_OK) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    rc = sqlite3_step(select);
    if (rc == SQLITE_ROW && sqlite3_column_type(select, 0) != SQLITE_NULL) {
        sqlite3_int64 max_value = sqlite3_column_int64(select, 0);

        if (max_value >= 0) {
            *out_next_auto_increment = (uint64_t)max_value + 1U;
        }
    }
    sqlite3_finalize(select);
    return rc == SQLITE_ROW ? MYLITE_OK : mylite_diagnostics_set_sqlite_error(stmt->database);
}

static int validate_insert_column_list(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                       size_t **out_column_indexes)
{
    size_t *column_indexes = NULL;

    *out_column_indexes = NULL;
    if (!stmt->insert_values.has_column_list) {
        return MYLITE_OK;
    }
    if (stmt->insert_values.column_count == 0U) {
        return MYLITE_OK;
    }

    column_indexes = calloc(stmt->insert_values.column_count, sizeof(*column_indexes));
    if (column_indexes == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    for (size_t index = 0U; index < stmt->insert_values.column_count; ++index) {
        size_t column_index = insert_table_column_index(table, stmt->insert_values.columns[index]);

        if (column_index == table->column_count) {
            int status = mylite_diagnostics_set_error_message_parts(
                stmt->database, "Unknown column '", stmt->insert_values.columns[index],
                "' in 'field list'");
            free(column_indexes);
            return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
        }
        for (size_t previous = 0U; previous < index; ++previous) {
            if (column_indexes[previous] == column_index) {
                int status = mylite_diagnostics_set_error_message_parts(
                    stmt->database, "Column '", stmt->insert_values.columns[index],
                    "' specified twice");
                free(column_indexes);
                return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
            }
        }
        column_indexes[index] = column_index;
    }

    *out_column_indexes = column_indexes;
    return MYLITE_OK;
}

static int validate_insert_row_alias(mylite_stmt *stmt, size_t source_column_count)
{
    const struct mylite_insert_values_plan *plan = &stmt->insert_values;

    if (plan->row_alias == NULL) {
        return MYLITE_OK;
    }
    if (mylite_ascii_case_equal(plan->row_alias, plan->table_name)) {
        int status = mylite_diagnostics_set_error_message_parts(
            stmt->database, "Not unique table/alias: '", plan->row_alias, "'");

        return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
    }
    if (plan->alias_column_count != 0U && plan->alias_column_count != source_column_count) {
        return set_insert_alias_column_count_error(stmt->database);
    }
    for (size_t index = 0U; index < plan->alias_column_count; ++index) {
        for (size_t previous = 0U; previous < index; ++previous) {
            if (mylite_ascii_case_equal(plan->alias_columns[previous],
                                        plan->alias_columns[index])) {
                int status = mylite_diagnostics_set_error_message_parts(
                    stmt->database, "Duplicate column name '", plan->alias_columns[index], "'");

                return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
            }
        }
    }
    return MYLITE_OK;
}

static int
validate_insert_update_assignments(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                   const char *schema_name, const size_t *source_column_indexes,
                                   size_t source_column_count, size_t **out_column_indexes)
{
    size_t assignment_count = stmt->insert_update.assignment_count;
    size_t *column_indexes = NULL;

    *out_column_indexes = NULL;
    if (!stmt->insert_update.has_clause) {
        return MYLITE_OK;
    }
    if (assignment_count == 0U) {
        return MYLITE_UNSUPPORTED;
    }

    column_indexes = calloc(assignment_count, sizeof(*column_indexes));
    if (column_indexes == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    for (size_t index = 0U; index < assignment_count; ++index) {
        const struct mylite_insert_update_assignment *assignment =
            &stmt->insert_update.assignments[index];
        size_t column_index = insert_table_column_reference_index(
            table, schema_name, stmt->insert_values.table_name, &assignment->target);
        int status = MYLITE_OK;

        if (column_index == table->column_count) {
            status = set_insert_update_unknown_column_error(stmt->database,
                                                            assignment->target.column_name);
            free(column_indexes);
            return status;
        }
        column_indexes[index] = column_index;

        status =
            validate_insert_update_assignment_value(stmt, table, schema_name, source_column_indexes,
                                                    source_column_count, &assignment->value);
        if (status != MYLITE_OK) {
            free(column_indexes);
            return status;
        }
    }

    *out_column_indexes = column_indexes;
    return MYLITE_OK;
}

// NOLINTNEXTLINE(misc-no-recursion)
static int validate_insert_update_assignment_value(mylite_stmt *stmt,
                                                   const struct mylite_insert_table *table,
                                                   const char *schema_name,
                                                   const size_t *source_column_indexes,
                                                   size_t source_column_count,
                                                   const struct mylite_insert_value *value)
{
    if (value == NULL) {
        return set_insert_unsupported_expression_error(stmt->database);
    }

    switch (value->kind) {
    case MYLITE_INSERT_VALUE_DEFAULT:
    case MYLITE_INSERT_VALUE_NULL:
    case MYLITE_INSERT_VALUE_INTEGER:
    case MYLITE_INSERT_VALUE_REAL:
    case MYLITE_INSERT_VALUE_TEXT:
    case MYLITE_INSERT_VALUE_CURRENT_TIMESTAMP:
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_COLUMN_REFERENCE: {
        bool candidate = false;
        size_t column_index = table->column_count;

        (void)candidate;
        return resolve_insert_update_column_reference(
            stmt, table, schema_name, source_column_indexes, source_column_count,
            &value->column_reference, &candidate, &column_index);
    }
    case MYLITE_INSERT_VALUE_VALUES_FUNCTION: {
        size_t column_index = insert_table_column_index(table, value->column_reference.column_name);

        if (column_index == table->column_count) {
            return set_insert_update_unknown_column_error(stmt->database,
                                                          value->column_reference.column_name);
        }
        return MYLITE_OK;
    }
    case MYLITE_INSERT_VALUE_UNARY_EXPRESSION:
        return validate_insert_update_assignment_value(
            stmt, table, schema_name, source_column_indexes, source_column_count, value->left);
    case MYLITE_INSERT_VALUE_BINARY_EXPRESSION: {
        int status = validate_insert_update_assignment_value(
            stmt, table, schema_name, source_column_indexes, source_column_count, value->left);

        if (status != MYLITE_OK) {
            return status;
        }
        return validate_insert_update_assignment_value(
            stmt, table, schema_name, source_column_indexes, source_column_count, value->right);
    }
    case MYLITE_INSERT_VALUE_UNSUPPORTED:
        return set_insert_unsupported_expression_error(stmt->database);
    }

    return set_insert_unsupported_expression_error(stmt->database);
}

static int execute_insert_values_transaction(mylite_stmt *stmt, const char *schema_name,
                                             const struct mylite_insert_table *table,
                                             const size_t *column_indexes,
                                             const size_t *update_column_indexes)
{
    size_t source_column_count = table->column_count;
    struct mylite_insert_execution_state state = {
        .next_auto_increment = table->next_auto_increment,
    };
    sqlite3_stmt *insert = NULL;
    char *insert_sql = NULL;
    struct mylite_statement_atomicity atomicity = {0};
    struct mylite_insert_row_column_indexes row_column_indexes = {
        .insert_columns = column_indexes,
        .update_columns = update_column_indexes,
    };
    int status = mylite_transaction_begin_statement_atomicity(stmt->database, &atomicity);
    int rc = SQLITE_OK;

    if (status != MYLITE_OK) {
        return status;
    }
    if (stmt->insert_values.has_column_list) {
        source_column_count = stmt->insert_values.column_count;
    }
    row_column_indexes.source_column_count = source_column_count;

    status = initialize_insert_ignore_warning_state(stmt, table, &state);
    if (status != MYLITE_OK) {
        mylite_transaction_rollback_statement_atomicity(stmt->database, &atomicity);
        return status;
    }
    status = append_insert_values_deprecated_warnings(stmt);
    if (status != MYLITE_OK) {
        insert_execution_state_deinit(&state);
        mylite_transaction_rollback_statement_atomicity(stmt->database, &atomicity);
        return status;
    }

    insert_sql = build_insert_physical_sql(stmt->database, table);
    if (insert_sql == NULL) {
        insert_execution_state_deinit(&state);
        mylite_transaction_rollback_statement_atomicity(stmt->database, &atomicity);
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    rc = sqlite3_prepare_v3(stmt->database->sqlite, insert_sql, -1, SQLITE_PREPARE_PERSISTENT,
                            &insert, NULL);
    sqlite3_free(insert_sql);
    if (rc != SQLITE_OK) {
        insert_execution_state_deinit(&state);
        mylite_transaction_rollback_statement_atomicity(stmt->database, &atomicity);
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    for (size_t row_index = 0U; row_index < stmt->insert_values.row_count; ++row_index) {
        status = execute_insert_row(stmt, insert, table, &row_column_indexes, &state, row_index);
        if (status != MYLITE_OK) {
            break;
        }
    }
    sqlite3_finalize(insert);

    if (status != MYLITE_OK) {
        insert_execution_state_deinit(&state);
        return finish_failed_insert_values_transaction(stmt, schema_name, table, &state, &atomicity,
                                                       status);
    }

    if (table->has_auto_increment) {
        status = update_insert_auto_increment(stmt, schema_name,
                                              insert_auto_increment_next_value(&state));
    }
    if (status == MYLITE_OK) {
        status = mylite_transaction_commit_statement_atomicity(stmt->database, &atomicity);
        if (status == MYLITE_OK) {
            insert_execution_state_deinit(&state);
            stmt->affected_rows = (int64_t)state.accepted_row_count;
            if (state.generated_insert_id) {
                stmt->database->last_insert_id = state.first_insert_id;
            }
            return MYLITE_OK;
        }
    }

    mylite_transaction_rollback_statement_atomicity(stmt->database, &atomicity);
    insert_execution_state_deinit(&state);
    return status;
}

static int finish_failed_insert_values_transaction(
    mylite_stmt *stmt, const char *schema_name, const struct mylite_insert_table *table,
    const struct mylite_insert_execution_state *state,
    const struct mylite_statement_atomicity *atomicity, int original_status)
{
    uint64_t next_auto_increment = insert_auto_increment_next_value(state);
    int status = MYLITE_OK;

    mylite_transaction_rollback_statement_atomicity(stmt->database, atomicity);
    if (table->has_auto_increment && next_auto_increment > table->next_auto_increment) {
        status = update_insert_auto_increment(stmt, schema_name, next_auto_increment);
        if (status != MYLITE_OK) {
            return status;
        }
    }
    if (state->generated_insert_id) {
        stmt->database->last_insert_id = state->first_insert_id;
    }
    return original_status;
}

static int initialize_insert_ignore_warning_state(mylite_stmt *stmt,
                                                  const struct mylite_insert_table *table,
                                                  struct mylite_insert_execution_state *state)
{
    if (!stmt->insert_values.ignore || table->column_count == 0U) {
        return MYLITE_OK;
    }

    state->warned_omitted_no_default_columns =
        calloc(table->column_count, sizeof(*state->warned_omitted_no_default_columns));
    state->warned_null_columns = calloc(table->column_count, sizeof(*state->warned_null_columns));
    if (state->warned_omitted_no_default_columns == NULL || state->warned_null_columns == NULL) {
        insert_execution_state_deinit(state);
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    return MYLITE_OK;
}

static void insert_execution_state_deinit(struct mylite_insert_execution_state *state)
{
    if (state == NULL) {
        return;
    }

    free(state->warned_omitted_no_default_columns);
    state->warned_omitted_no_default_columns = NULL;
    free(state->warned_null_columns);
    state->warned_null_columns = NULL;
}

static char *build_insert_physical_sql(mylite_db *database, const struct mylite_insert_table *table)
{
    sqlite3_str *sql = sqlite3_str_new(database->sqlite);

    if (sql == NULL) {
        return NULL;
    }

    sqlite3_str_appendf(sql, "INSERT INTO \"%w\"(", table->physical_name);
    for (size_t index = 0U; index < table->column_count; ++index) {
        if (index != 0U) {
            sqlite3_str_append(sql, ",", 1);
        }
        sqlite3_str_appendf(sql, "\"%w\"", table->columns[index].name);
    }
    sqlite3_str_append(sql, ") VALUES(", (int)strlen(") VALUES("));
    for (size_t index = 0U; index < table->column_count; ++index) {
        if (index != 0U) {
            sqlite3_str_append(sql, ",", 1);
        }
        sqlite3_str_append(sql, "?", 1);
    }
    sqlite3_str_append(sql, ")", 1);
    return sqlite3_str_finish(sql);
}

static int execute_insert_row(mylite_stmt *stmt, sqlite3_stmt *insert,
                              const struct mylite_insert_table *table,
                              const struct mylite_insert_row_column_indexes *column_indexes,
                              struct mylite_insert_execution_state *state, size_t row_index)
{
    struct mylite_insert_bound_value *values = NULL;
    bool ignored = false;
    int status = MYLITE_OK;

    if (table->column_count == 0U) {
        (void)mylite_diagnostics_set_error_message(stmt->database,
                                                   "INSERT target table has no columns");
        return MYLITE_EXEC_ERROR;
    }

    values = calloc(table->column_count, sizeof(*values));
    if (values == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    status = resolve_insert_row_values(stmt, table, column_indexes->insert_columns, state,
                                       row_index, values);
    if (status == MYLITE_OK && stmt->insert_update.has_clause) {
        status = execute_insert_row_with_duplicate_update(stmt, insert, table, column_indexes,
                                                          state, values);
    } else if (status == MYLITE_OK) {
        status = validate_insert_unique_indexes(stmt, table, values, state, &ignored);
        if (status == MYLITE_OK && !ignored) {
            status = write_insert_candidate_row(stmt, insert, table, values, state);
        }
    }

    mylite_dml_insert_bound_values_deinit(values, table->column_count);
    return status;
}

static int execute_insert_row_with_duplicate_update(
    mylite_stmt *stmt, sqlite3_stmt *insert, const struct mylite_insert_table *table,
    const struct mylite_insert_row_column_indexes *column_indexes,
    struct mylite_insert_execution_state *state, const struct mylite_insert_bound_value *values)
{
    struct mylite_insert_unique_conflict conflict = {0};
    int status = find_insert_unique_conflict(stmt, table, values, &conflict);

    if (status != MYLITE_OK) {
        return status;
    }
    if (!conflict.conflicts) {
        return write_insert_candidate_row(stmt, insert, table, values, state);
    }

    ++state->duplicate_count;
    return execute_insert_duplicate_update_branch(stmt, table, column_indexes, state, values,
                                                  &conflict);
}

static int execute_insert_duplicate_update_branch(
    mylite_stmt *stmt, const struct mylite_insert_table *table,
    const struct mylite_insert_row_column_indexes *column_indexes,
    struct mylite_insert_execution_state *state,
    const struct mylite_insert_bound_value *candidate_values,
    const struct mylite_insert_unique_conflict *conflict)
{
    struct mylite_insert_bound_value *stored_values = NULL;
    struct mylite_insert_bound_value *updated_values = NULL;
    const struct mylite_insert_unique_index *update_conflict = NULL;
    int status = MYLITE_OK;

    if (column_indexes == NULL || column_indexes->update_columns == NULL) {
        return MYLITE_UNSUPPORTED;
    }

    stored_values = calloc(table->column_count, sizeof(*stored_values));
    if (stored_values == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    status = load_insert_conflict_row(stmt, table, conflict->rowid, stored_values);
    if (status == MYLITE_OK) {
        status =
            copy_insert_bound_values(stmt, stored_values, table->column_count, &updated_values);
    }
    if (status == MYLITE_OK) {
        status = apply_insert_update_assignments(stmt, table, column_indexes, candidate_values,
                                                 updated_values);
    }
    if (status == MYLITE_OK) {
        status = validate_insert_update_unique_indexes(stmt, table, updated_values, conflict->rowid,
                                                       &update_conflict);
    }
    if (status == MYLITE_OK && update_conflict != NULL) {
        if (stmt->insert_values.ignore) {
            status = append_insert_duplicate_entry_warning(
                stmt->database, stmt->insert_values.table_name, update_conflict, updated_values);
        } else {
            status = set_insert_duplicate_entry_error(
                stmt->database, stmt->insert_values.table_name, update_conflict, updated_values);
        }
    }
    if (status == MYLITE_OK && update_conflict == NULL &&
        insert_update_row_changed(stored_values, updated_values, table->column_count)) {
        status = write_insert_update_candidate(stmt, table, conflict->rowid, updated_values, state);
        if (status == MYLITE_OK) {
            state->accepted_row_count += 2U;
        }
    }

    mylite_dml_insert_bound_values_deinit(stored_values, table->column_count);
    mylite_dml_insert_bound_values_deinit(updated_values, table->column_count);
    return status;
}

static int write_insert_candidate_row(mylite_stmt *stmt, sqlite3_stmt *insert,
                                      const struct mylite_insert_table *table,
                                      const struct mylite_insert_bound_value *values,
                                      struct mylite_insert_execution_state *state)
{
    int status = MYLITE_OK;
    int rc = SQLITE_OK;

    sqlite3_reset(insert);
    sqlite3_clear_bindings(insert);
    status = bind_insert_row_values(stmt->database, insert, values, table->column_count);
    if (status == MYLITE_OK) {
        rc = sqlite3_step(insert);
        if (rc != SQLITE_DONE) {
            status = mylite_diagnostics_set_sqlite_error(stmt->database);
        }
    }
    if (status == MYLITE_OK) {
        ++state->accepted_row_count;
        record_insert_row_auto_increment_id(table, values, state);
        status = advance_insert_row_auto_increment(table, values, state);
    }
    return status;
}

static int load_insert_conflict_row(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                    sqlite3_int64 rowid, struct mylite_insert_bound_value *values)
{
    sqlite3_stmt *select = NULL;
    char *sql = build_insert_conflict_row_sql(stmt->database, table);
    int rc = SQLITE_OK;
    int status = MYLITE_OK;

    if (sql == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    rc = sqlite3_prepare_v3(stmt->database->sqlite, sql, -1, SQLITE_PREPARE_PERSISTENT, &select,
                            NULL);
    sqlite3_free(sql);
    if (rc != SQLITE_OK) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }
    rc = sqlite3_bind_int64(select, 1, rowid);
    if (rc != SQLITE_OK) {
        sqlite3_finalize(select);
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    rc = sqlite3_step(select);
    if (rc == SQLITE_ROW) {
        for (size_t index = 0U; index < table->column_count; ++index) {
            if (copy_insert_sqlite_column_value(select, (int)index, &values[index]) != 0) {
                status = MYLITE_NOMEM;
                (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
                break;
            }
        }
    } else {
        status = rc == SQLITE_DONE ? MYLITE_EXEC_ERROR
                                   : mylite_diagnostics_set_sqlite_error(stmt->database);
        if (status == MYLITE_EXEC_ERROR) {
            (void)mylite_diagnostics_set_error_message(stmt->database,
                                                       "Duplicate row disappeared during INSERT");
        }
    }

    sqlite3_finalize(select);
    return status;
}

static char *build_insert_conflict_row_sql(mylite_db *database,
                                           const struct mylite_insert_table *table)
{
    sqlite3_str *sql = sqlite3_str_new(database->sqlite);

    if (sql == NULL) {
        return NULL;
    }

    sqlite3_str_append(sql, "SELECT ", (int)strlen("SELECT "));
    for (size_t index = 0U; index < table->column_count; ++index) {
        if (index != 0U) {
            sqlite3_str_append(sql, ",", 1);
        }
        sqlite3_str_appendf(sql, "\"%w\"", table->columns[index].name);
    }
    sqlite3_str_appendf(sql, " FROM \"%w\" WHERE rowid = ?", table->physical_name);
    return sqlite3_str_finish(sql);
}

static int copy_insert_sqlite_column_value(sqlite3_stmt *scan, int column,
                                           struct mylite_insert_bound_value *out_value)
{
    int sqlite_type = sqlite3_column_type(scan, column);

    switch (sqlite_type) {
    case SQLITE_NULL:
        *out_value = (struct mylite_insert_bound_value){.kind = MYLITE_INSERT_BOUND_NULL};
        return 0;
    case SQLITE_INTEGER:
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_INTEGER,
            .integer_value = sqlite3_column_int64(scan, column),
        };
        return 0;
    case SQLITE_FLOAT:
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_REAL,
            .real_value = sqlite3_column_double(scan, column),
        };
        return 0;
    case SQLITE_TEXT:
    case SQLITE_BLOB: {
        const unsigned char *text = sqlite3_column_text(scan, column);
        int bytes = sqlite3_column_bytes(scan, column);

        out_value->kind = MYLITE_INSERT_BOUND_TEXT;
        out_value->text_value =
            mylite_copy_span_text((const char *)text, bytes < 0 ? 0U : (size_t)bytes);
        return out_value->text_value == NULL ? -1 : 0;
    }
    default:
        break;
    }
    return -1;
}

static int
apply_insert_update_assignments(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                const struct mylite_insert_row_column_indexes *column_indexes,
                                const struct mylite_insert_bound_value *candidate_values,
                                struct mylite_insert_bound_value *updated_values)
{
    for (size_t index = 0U; index < stmt->insert_update.assignment_count; ++index) {
        size_t column_index = column_indexes->update_columns[index];
        struct mylite_insert_bound_value value = {0};
        int status =
            evaluate_insert_update_assignment_value(stmt, table, column_index, column_indexes,
                                                    &stmt->insert_update.assignments[index].value,
                                                    updated_values, candidate_values, &value);

        if (status != MYLITE_OK) {
            mylite_dml_insert_bound_value_deinit(&value);
            return status;
        }

        mylite_dml_insert_bound_value_deinit(&updated_values[column_index]);
        updated_values[column_index] = value;
    }
    return MYLITE_OK;
}

static int evaluate_insert_update_assignment_value(
    mylite_stmt *stmt, const struct mylite_insert_table *table, size_t target_column,
    const struct mylite_insert_row_column_indexes *column_indexes,
    const struct mylite_insert_value *value, const struct mylite_insert_bound_value *target_values,
    const struct mylite_insert_bound_value *candidate_values,
    struct mylite_insert_bound_value *out_value)
{
    const struct mylite_insert_table_column *column = &table->columns[target_column];
    int status = MYLITE_OK;

    if (value->kind == MYLITE_INSERT_VALUE_DEFAULT) {
        status = resolve_insert_update_default_value(stmt, column, out_value);
    } else {
        status = evaluate_insert_update_expression(stmt, table, column_indexes, value,
                                                   target_values, candidate_values, out_value);
    }
    if (status == MYLITE_OK) {
        status = validate_insert_update_assignment_result(stmt, column, out_value);
    }
    return status;
}

static int resolve_insert_update_default_value(mylite_stmt *stmt,
                                               const struct mylite_insert_table_column *column,
                                               struct mylite_insert_bound_value *out_value)
{
    if (column->auto_increment) {
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_INTEGER,
            .integer_value = 0,
        };
        return MYLITE_OK;
    }
    if (column->default_text == NULL) {
        if (column->nullable) {
            *out_value = (struct mylite_insert_bound_value){.kind = MYLITE_INSERT_BOUND_NULL};
            return MYLITE_OK;
        }
        return set_insert_no_default_error(stmt->database, column->name);
    }
    if (column_default_is_current_timestamp(column->default_text)) {
        char *timestamp = insert_current_timestamp_text();

        if (timestamp == NULL) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_TEXT,
            .text_value = timestamp,
        };
        return MYLITE_OK;
    }
    if (column->generated_default) {
        return set_insert_unsupported_generated_default_error(stmt->database, column->name);
    }
    return resolve_insert_text_value(stmt, column, column->default_text, NULL, out_value);
}

static int
evaluate_insert_update_expression(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                  const struct mylite_insert_row_column_indexes *column_indexes,
                                  const struct mylite_insert_value *value,
                                  const struct mylite_insert_bound_value *target_values,
                                  const struct mylite_insert_bound_value *candidate_values,
                                  struct mylite_insert_bound_value *out_value)
{
    if (value->kind == MYLITE_INSERT_VALUE_UNARY_EXPRESSION) {
        return evaluate_insert_update_unary_expression(stmt, table, column_indexes, value,
                                                       target_values, candidate_values, out_value);
    }
    if (value->kind == MYLITE_INSERT_VALUE_BINARY_EXPRESSION) {
        return evaluate_insert_update_binary_expression(stmt, table, column_indexes, value,
                                                        target_values, candidate_values, out_value);
    }
    return evaluate_insert_update_simple_expression(stmt, table, column_indexes, value,
                                                    target_values, candidate_values, out_value);
}

static int evaluate_insert_update_simple_expression(
    mylite_stmt *stmt, const struct mylite_insert_table *table,
    const struct mylite_insert_row_column_indexes *column_indexes,
    const struct mylite_insert_value *value, const struct mylite_insert_bound_value *target_values,
    const struct mylite_insert_bound_value *candidate_values,
    struct mylite_insert_bound_value *out_value)
{
    int64_t integer_value = 0;
    double real_value = 0.0;
    char *timestamp = NULL;
    const struct mylite_insert_update_row_values row_values = {
        .target_values = target_values,
        .candidate_values = candidate_values,
    };

    switch (value->kind) {
    case MYLITE_INSERT_VALUE_NULL:
        *out_value = (struct mylite_insert_bound_value){.kind = MYLITE_INSERT_BOUND_NULL};
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_INTEGER:
        if (!parse_insert_integer_text(value->text, &integer_value)) {
            return set_insert_unsupported_expression_error(stmt->database);
        }
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_INTEGER,
            .integer_value = integer_value,
        };
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_REAL:
        if (!parse_insert_real_text(value->text, &real_value)) {
            return set_insert_unsupported_expression_error(stmt->database);
        }
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_REAL,
            .real_value = real_value,
        };
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_TEXT:
        out_value->text_value =
            mylite_copy_span_text(value->text, value->text == NULL ? 0U : strlen(value->text));
        if (out_value->text_value == NULL) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        out_value->kind = MYLITE_INSERT_BOUND_TEXT;
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_CURRENT_TIMESTAMP:
        timestamp = insert_current_timestamp_text();
        if (timestamp == NULL) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_TEXT,
            .text_value = timestamp,
        };
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_COLUMN_REFERENCE:
        return evaluate_insert_update_column_reference(
            stmt, table, column_indexes, &value->column_reference, &row_values, out_value);
    case MYLITE_INSERT_VALUE_VALUES_FUNCTION:
        return evaluate_insert_values_function(stmt, table, &value->column_reference,
                                               candidate_values, out_value);
    case MYLITE_INSERT_VALUE_DEFAULT:
    case MYLITE_INSERT_VALUE_UNSUPPORTED:
    case MYLITE_INSERT_VALUE_UNARY_EXPRESSION:
    case MYLITE_INSERT_VALUE_BINARY_EXPRESSION:
        return set_insert_unsupported_expression_error(stmt->database);
    }

    return set_insert_unsupported_expression_error(stmt->database);
}

static int evaluate_insert_update_unary_expression(
    mylite_stmt *stmt, const struct mylite_insert_table *table,
    const struct mylite_insert_row_column_indexes *column_indexes,
    const struct mylite_insert_value *value, const struct mylite_insert_bound_value *target_values,
    const struct mylite_insert_bound_value *candidate_values,
    struct mylite_insert_bound_value *out_value)
{
    struct mylite_insert_bound_value operand = {0};
    double numeric_value = 0.0;
    bool is_integer = false;
    int status = evaluate_insert_update_simple_expression(
        stmt, table, column_indexes, value->left, target_values, candidate_values, &operand);

    if (status != MYLITE_OK) {
        mylite_dml_insert_bound_value_deinit(&operand);
        return status;
    }
    if (operand.kind == MYLITE_INSERT_BOUND_NULL) {
        *out_value = (struct mylite_insert_bound_value){.kind = MYLITE_INSERT_BOUND_NULL};
        mylite_dml_insert_bound_value_deinit(&operand);
        return MYLITE_OK;
    }
    if (!insert_bound_value_is_numeric(&operand, &numeric_value, &is_integer)) {
        mylite_dml_insert_bound_value_deinit(&operand);
        return set_insert_unsupported_expression_error(stmt->database);
    }

    if (is_integer) {
        int64_t integer = operand.kind == MYLITE_INSERT_BOUND_INTEGER ? operand.integer_value
                                                                      : (int64_t)numeric_value;

        out_value->kind = MYLITE_INSERT_BOUND_INTEGER;
        out_value->integer_value =
            value->operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE ? -integer : integer;
    } else {
        out_value->kind = MYLITE_INSERT_BOUND_REAL;
        out_value->real_value = value->operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE
                                    ? -numeric_value
                                    : numeric_value;
    }
    mylite_dml_insert_bound_value_deinit(&operand);
    return MYLITE_OK;
}

static int evaluate_insert_update_binary_expression(
    mylite_stmt *stmt, const struct mylite_insert_table *table,
    const struct mylite_insert_row_column_indexes *column_indexes,
    const struct mylite_insert_value *value, const struct mylite_insert_bound_value *target_values,
    const struct mylite_insert_bound_value *candidate_values,
    struct mylite_insert_bound_value *out_value)
{
    struct mylite_insert_bound_value left = {0};
    struct mylite_insert_bound_value right = {0};
    double left_number = 0.0;
    double right_number = 0.0;
    bool left_is_integer = false;
    bool right_is_integer = false;
    int status = evaluate_insert_update_simple_expression(stmt, table, column_indexes, value->left,
                                                          target_values, candidate_values, &left);

    if (status == MYLITE_OK) {
        status = evaluate_insert_update_simple_expression(stmt, table, column_indexes, value->right,
                                                          target_values, candidate_values, &right);
    }
    if (status != MYLITE_OK) {
        mylite_dml_insert_bound_value_deinit(&left);
        mylite_dml_insert_bound_value_deinit(&right);
        return status;
    }
    if (left.kind == MYLITE_INSERT_BOUND_NULL || right.kind == MYLITE_INSERT_BOUND_NULL) {
        *out_value = (struct mylite_insert_bound_value){.kind = MYLITE_INSERT_BOUND_NULL};
        mylite_dml_insert_bound_value_deinit(&left);
        mylite_dml_insert_bound_value_deinit(&right);
        return MYLITE_OK;
    }
    if (!insert_bound_value_is_numeric(&left, &left_number, &left_is_integer) ||
        !insert_bound_value_is_numeric(&right, &right_number, &right_is_integer)) {
        mylite_dml_insert_bound_value_deinit(&left);
        mylite_dml_insert_bound_value_deinit(&right);
        return set_insert_unsupported_expression_error(stmt->database);
    }

    if (left_is_integer && right_is_integer &&
        value->operator_kind != MYLITE_SQL_AST_OPERATOR_DIVIDE) {
        int64_t left_int =
            left.kind == MYLITE_INSERT_BOUND_INTEGER ? left.integer_value : (int64_t)left_number;
        int64_t right_int =
            right.kind == MYLITE_INSERT_BOUND_INTEGER ? right.integer_value : (int64_t)right_number;

        out_value->kind = MYLITE_INSERT_BOUND_INTEGER;
        switch (value->operator_kind) {
        case MYLITE_SQL_AST_OPERATOR_ADD:
            out_value->integer_value = left_int + right_int;
            break;
        case MYLITE_SQL_AST_OPERATOR_SUBTRACT:
            out_value->integer_value = left_int - right_int;
            break;
        case MYLITE_SQL_AST_OPERATOR_MULTIPLY:
            out_value->integer_value = left_int * right_int;
            break;
        case MYLITE_SQL_AST_OPERATOR_DIVIDE:
        case MYLITE_SQL_AST_OPERATOR_NONE:
        case MYLITE_SQL_AST_OPERATOR_POSITIVE:
        case MYLITE_SQL_AST_OPERATOR_NEGATIVE:
        default:
            mylite_dml_insert_bound_value_deinit(&left);
            mylite_dml_insert_bound_value_deinit(&right);
            return set_insert_unsupported_expression_error(stmt->database);
        }
    } else {
        if (value->operator_kind == MYLITE_SQL_AST_OPERATOR_DIVIDE && right_number == 0.0) {
            mylite_dml_insert_bound_value_deinit(&left);
            mylite_dml_insert_bound_value_deinit(&right);
            return set_insert_unsupported_expression_error(stmt->database);
        }
        out_value->kind = MYLITE_INSERT_BOUND_REAL;
        switch (value->operator_kind) {
        case MYLITE_SQL_AST_OPERATOR_ADD:
            out_value->real_value = left_number + right_number;
            break;
        case MYLITE_SQL_AST_OPERATOR_SUBTRACT:
            out_value->real_value = left_number - right_number;
            break;
        case MYLITE_SQL_AST_OPERATOR_MULTIPLY:
            out_value->real_value = left_number * right_number;
            break;
        case MYLITE_SQL_AST_OPERATOR_DIVIDE:
            out_value->real_value = left_number / right_number;
            break;
        case MYLITE_SQL_AST_OPERATOR_NONE:
        case MYLITE_SQL_AST_OPERATOR_POSITIVE:
        case MYLITE_SQL_AST_OPERATOR_NEGATIVE:
        default:
            mylite_dml_insert_bound_value_deinit(&left);
            mylite_dml_insert_bound_value_deinit(&right);
            return set_insert_unsupported_expression_error(stmt->database);
        }
    }

    mylite_dml_insert_bound_value_deinit(&left);
    mylite_dml_insert_bound_value_deinit(&right);
    return MYLITE_OK;
}

static int evaluate_insert_update_column_reference(
    mylite_stmt *stmt, const struct mylite_insert_table *table,
    const struct mylite_insert_row_column_indexes *column_indexes,
    const struct mylite_insert_column_reference *ref,
    const struct mylite_insert_update_row_values *row_values,
    struct mylite_insert_bound_value *out_value)
{
    const char *schema_name = stmt->insert_values.schema_name == NULL
                                  ? stmt->database->selected_schema
                                  : stmt->insert_values.schema_name;
    bool candidate = false;
    size_t column_index = table->column_count;
    int status = MYLITE_OK;

    status = resolve_insert_update_column_reference(
        stmt, table, schema_name, column_indexes->insert_columns,
        column_indexes->source_column_count, ref, &candidate, &column_index);
    if (status != MYLITE_OK) {
        return status;
    }
    {
        const struct mylite_insert_bound_value *source_value =
            &row_values->target_values[column_index];

        if (candidate) {
            source_value = &row_values->candidate_values[column_index];
        }
        status = copy_insert_bound_value(source_value, out_value);
    }
    if (status == MYLITE_NOMEM) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
    }
    return status;
}

static int evaluate_insert_values_function(mylite_stmt *stmt,
                                           const struct mylite_insert_table *table,
                                           const struct mylite_insert_column_reference *ref,
                                           const struct mylite_insert_bound_value *candidate_values,
                                           struct mylite_insert_bound_value *out_value)
{
    size_t column_index = insert_table_column_index(table, ref->column_name);
    int status = MYLITE_OK;

    if (column_index == table->column_count) {
        return set_insert_update_unknown_column_error(stmt->database, ref->column_name);
    }

    status = copy_insert_bound_value(&candidate_values[column_index], out_value);
    if (status == MYLITE_NOMEM) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
    }
    return status;
}

static int validate_insert_update_assignment_result(mylite_stmt *stmt,
                                                    const struct mylite_insert_table_column *column,
                                                    struct mylite_insert_bound_value *value)
{
    int64_t integer_value = 0;

    if (value->kind == MYLITE_INSERT_BOUND_NULL) {
        if (column->nullable) {
            return MYLITE_OK;
        }
        return set_insert_null_error(stmt->database, column->name);
    }
    if (!column->auto_increment) {
        return MYLITE_OK;
    }
    if (value->kind == MYLITE_INSERT_BOUND_INTEGER && value->integer_value >= 0) {
        return MYLITE_OK;
    }
    if (value->kind == MYLITE_INSERT_BOUND_TEXT &&
        parse_insert_integer_text(value->text_value, &integer_value) && integer_value >= 0) {
        mylite_dml_insert_bound_value_deinit(value);
        *value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_INTEGER,
            .integer_value = integer_value,
        };
        return MYLITE_OK;
    }
    return set_insert_unsupported_expression_error(stmt->database);
}

static int
validate_insert_update_unique_indexes(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                      const struct mylite_insert_bound_value *values,
                                      sqlite3_int64 rowid,
                                      const struct mylite_insert_unique_index **out_conflict_index)
{
    *out_conflict_index = NULL;
    for (size_t index = 0U; index < table->unique_index_count; ++index) {
        bool conflicts = false;
        sqlite3_int64 conflict_rowid = 0;
        int status =
            insert_unique_index_conflict_rowid(stmt, table, &table->unique_indexes[index], values,
                                               rowid, true, &conflict_rowid, &conflicts);

        (void)conflict_rowid;
        if (status != MYLITE_OK) {
            return status;
        }
        if (conflicts) {
            *out_conflict_index = &table->unique_indexes[index];
            return MYLITE_OK;
        }
    }
    return MYLITE_OK;
}

static int write_insert_update_candidate(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                         sqlite3_int64 rowid,
                                         const struct mylite_insert_bound_value *values,
                                         struct mylite_insert_execution_state *state)
{
    sqlite3_stmt *update = NULL;
    char *sql = build_insert_update_physical_sql(stmt->database, table);
    int rc = SQLITE_OK;
    int status = MYLITE_OK;

    if (sql == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    rc = sqlite3_prepare_v3(stmt->database->sqlite, sql, -1, SQLITE_PREPARE_PERSISTENT, &update,
                            NULL);
    sqlite3_free(sql);
    if (rc != SQLITE_OK) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    status = bind_insert_row_values(stmt->database, update, values, table->column_count);
    if (status == MYLITE_OK) {
        rc = sqlite3_bind_int64(update, (int)table->column_count + 1, rowid);
        if (rc != SQLITE_OK) {
            status = mylite_diagnostics_set_sqlite_error(stmt->database);
        }
    }
    if (status == MYLITE_OK) {
        rc = sqlite3_step(update);
        if (rc != SQLITE_DONE) {
            status = mylite_diagnostics_set_sqlite_error(stmt->database);
        }
    }
    sqlite3_finalize(update);
    if (status == MYLITE_OK) {
        status = advance_insert_row_auto_increment(table, values, state);
    }
    return status;
}

static char *build_insert_update_physical_sql(mylite_db *database,
                                              const struct mylite_insert_table *table)
{
    sqlite3_str *sql = sqlite3_str_new(database->sqlite);

    if (sql == NULL) {
        return NULL;
    }

    sqlite3_str_appendf(sql, "UPDATE \"%w\" SET ", table->physical_name);
    for (size_t index = 0U; index < table->column_count; ++index) {
        if (index != 0U) {
            sqlite3_str_append(sql, ",", 1);
        }
        sqlite3_str_appendf(sql, "\"%w\" = ?", table->columns[index].name);
    }
    sqlite3_str_append(sql, " WHERE rowid = ?", (int)strlen(" WHERE rowid = ?"));
    return sqlite3_str_finish(sql);
}

static bool insert_update_row_changed(const struct mylite_insert_bound_value *stored,
                                      const struct mylite_insert_bound_value *candidate,
                                      size_t value_count)
{
    for (size_t index = 0U; index < value_count; ++index) {
        if (!insert_bound_values_equal(&stored[index], &candidate[index])) {
            return true;
        }
    }
    return false;
}

static bool insert_bound_values_equal(const struct mylite_insert_bound_value *left,
                                      const struct mylite_insert_bound_value *right)
{
    if (left->kind != right->kind) {
        return false;
    }
    switch (left->kind) {
    case MYLITE_INSERT_BOUND_NULL:
        return true;
    case MYLITE_INSERT_BOUND_INTEGER:
        return left->integer_value == right->integer_value;
    case MYLITE_INSERT_BOUND_REAL:
        return left->real_value == right->real_value;
    case MYLITE_INSERT_BOUND_TEXT:
        if (left->text_value == NULL || right->text_value == NULL) {
            return left->text_value == right->text_value;
        }
        return strcmp(left->text_value, right->text_value) == 0;
    }
    return false;
}

static int resolve_insert_update_column_reference(
    mylite_stmt *stmt, const struct mylite_insert_table *table, const char *schema_name,
    const size_t *source_column_indexes, size_t source_column_count,
    const struct mylite_insert_column_reference *ref, bool *out_candidate, size_t *out_column_index)
{
    size_t target_index;
    size_t alias_index = table->column_count;

    *out_candidate = false;
    *out_column_index = table->column_count;
    if (ref->schema_name != NULL) {
        target_index = insert_table_column_reference_index(table, schema_name,
                                                           stmt->insert_values.table_name, ref);
        if (target_index == table->column_count) {
            return set_insert_update_unknown_column_error(stmt->database, ref->column_name);
        }
        *out_column_index = target_index;
        return MYLITE_OK;
    }
    if (ref->table_name != NULL) {
        if (insert_row_alias_matches(&stmt->insert_values, ref->table_name)) {
            alias_index =
                stmt->insert_values.alias_column_count == 0U
                    ? insert_table_column_index(table, ref->column_name)
                    : insert_alias_column_index(&stmt->insert_values, table, source_column_indexes,
                                                source_column_count, ref->column_name);
            if (alias_index == table->column_count) {
                return set_insert_update_unknown_column_error(stmt->database, ref->column_name);
            }
            *out_candidate = true;
            *out_column_index = alias_index;
            return MYLITE_OK;
        }

        target_index = insert_table_column_reference_index(table, schema_name,
                                                           stmt->insert_values.table_name, ref);
        if (target_index == table->column_count) {
            return set_insert_update_unknown_column_error(stmt->database, ref->column_name);
        }
        *out_column_index = target_index;
        return MYLITE_OK;
    }

    target_index = insert_table_column_index(table, ref->column_name);
    if (stmt->insert_values.alias_column_count != 0U) {
        alias_index = insert_alias_column_index(&stmt->insert_values, table, source_column_indexes,
                                                source_column_count, ref->column_name);
    }
    if (target_index != table->column_count && alias_index != table->column_count) {
        return set_insert_update_ambiguous_column_error(stmt->database, ref->column_name);
    }
    if (alias_index != table->column_count) {
        *out_candidate = true;
        *out_column_index = alias_index;
        return MYLITE_OK;
    }
    if (target_index != table->column_count) {
        *out_column_index = target_index;
        return MYLITE_OK;
    }
    return set_insert_update_unknown_column_error(stmt->database, ref->column_name);
}

static size_t insert_alias_column_index(const struct mylite_insert_values_plan *plan,
                                        const struct mylite_insert_table *table,
                                        const size_t *source_column_indexes,
                                        size_t source_column_count, const char *column_name)
{
    for (size_t index = 0U; index < plan->alias_column_count; ++index) {
        if (mylite_ascii_case_equal(plan->alias_columns[index], column_name)) {
            if (index >= source_column_count) {
                return table->column_count;
            }
            if (source_column_indexes != NULL) {
                return source_column_indexes[index];
            }
            if (plan->has_column_list) {
                return insert_table_column_index(table, plan->columns[index]);
            }
            return index;
        }
    }
    return table->column_count;
}

static bool insert_row_alias_matches(const struct mylite_insert_values_plan *plan,
                                     const char *table_name)
{
    if (plan->row_alias == NULL || table_name == NULL) {
        return false;
    }
    return mylite_ascii_case_equal(plan->row_alias, table_name);
}

static int set_insert_update_unknown_column_error(mylite_db *database, const char *column_name)
{
    int status = mylite_diagnostics_set_error_message_parts(database, "Unknown column '",
                                                            column_name, "' in 'field list'");

    return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
}

static int set_insert_update_ambiguous_column_error(mylite_db *database, const char *column_name)
{
    int status = mylite_diagnostics_set_error_message_parts(database, "Column '", column_name,
                                                            "' in field list is ambiguous");

    return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
}

static int set_insert_alias_column_count_error(mylite_db *database)
{
    static const char message[] =
        "In definition of view, derived table or common table expression, "
        "SELECT list and column names list have different column counts";
    int status = mylite_diagnostics_set_error_message(database, message);

    return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
}

static int append_insert_values_deprecated_warnings(mylite_stmt *stmt)
{
    size_t warning_count = 0U;

    if (!stmt->insert_update.has_clause) {
        return MYLITE_OK;
    }
    for (size_t index = 0U; index < stmt->insert_update.assignment_count; ++index) {
        warning_count += stmt->insert_update.assignments[index].value.values_function_count;
    }
    for (size_t index = 0U; index < warning_count; ++index) {
        int status = append_insert_values_deprecated_warning(stmt->database);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int append_insert_values_deprecated_warning(mylite_db *database)
{
    static const char message[] =
        "'VALUES function' is deprecated and will be removed in a future release. Please use an "
        "alias (INSERT INTO ... VALUES (...) AS alias) and replace VALUES(col) in the ON "
        "DUPLICATE KEY UPDATE clause with alias.col instead";

    return mylite_diagnostics_append_warning(database, MYLITE_MYSQL_ER_WARN_DEPRECATED_SYNTAX,
                                             message);
}

static void record_insert_row_auto_increment_id(const struct mylite_insert_table *table,
                                                const struct mylite_insert_bound_value *values,
                                                struct mylite_insert_execution_state *state)
{
    const struct mylite_insert_bound_value *auto_value = NULL;

    if (!table->has_auto_increment || state->generated_insert_id) {
        return;
    }

    auto_value = &values[table->auto_increment_column_index];
    if (auto_value->generated_auto_increment && auto_value->kind == MYLITE_INSERT_BOUND_INTEGER &&
        auto_value->integer_value > 0) {
        state->first_insert_id = (uint64_t)auto_value->integer_value;
        state->generated_insert_id = true;
    }
}

static int advance_insert_row_auto_increment(const struct mylite_insert_table *table,
                                             const struct mylite_insert_bound_value *values,
                                             struct mylite_insert_execution_state *state)
{
    const struct mylite_insert_bound_value *auto_value = NULL;

    if (!table->has_auto_increment) {
        return MYLITE_OK;
    }

    auto_value = &values[table->auto_increment_column_index];
    if (auto_value->kind == MYLITE_INSERT_BOUND_INTEGER && auto_value->integer_value > 0 &&
        (uint64_t)auto_value->integer_value >= state->next_auto_increment) {
        state->next_auto_increment = (uint64_t)auto_value->integer_value + 1U;
    }
    return MYLITE_OK;
}

static int resolve_insert_row_values(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                     const size_t *column_indexes,
                                     struct mylite_insert_execution_state *state, size_t row_index,
                                     struct mylite_insert_bound_value *values)
{
    const struct mylite_insert_row *row = &stmt->insert_values.rows[row_index];
    size_t expected_count = insert_row_target_column_count(&stmt->insert_values, table, row_index);

    if (row->value_count != expected_count) {
        return set_insert_wrong_value_count_error(stmt->database, row_index);
    }
    if (stmt->insert_values.has_column_list) {
        return resolve_insert_column_list_row_values(stmt, table, row, column_indexes, state,
                                                     values);
    }
    return resolve_insert_positional_row_values(stmt, table, row_index, state, values);
}

static int resolve_insert_column_list_row_values(mylite_stmt *stmt,
                                                 const struct mylite_insert_table *table,
                                                 const struct mylite_insert_row *row,
                                                 const size_t *column_indexes,
                                                 struct mylite_insert_execution_state *state,
                                                 struct mylite_insert_bound_value *values)
{
    if (stmt->insert_values.column_count == 0U) {
        return resolve_insert_default_row_values(stmt, table, state, values);
    }
    if (column_indexes == NULL) {
        return MYLITE_UNSUPPORTED;
    }

    for (size_t column = 0U; column < table->column_count; ++column) {
        const struct mylite_insert_value *explicit_value =
            insert_column_list_value_for_column(&stmt->insert_values, row, column_indexes, column);
        int status =
            explicit_value == NULL
                ? resolve_insert_omitted_default_value(stmt, &table->columns[column], state, column,
                                                       &values[column])
                : resolve_insert_explicit_value(stmt, &table->columns[column], explicit_value,
                                                state, column, &values[column]);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static const struct mylite_insert_value *
insert_column_list_value_for_column(const struct mylite_insert_values_plan *plan,
                                    const struct mylite_insert_row *row,
                                    const size_t *column_indexes, size_t column)
{
    for (size_t target = 0U; target < plan->column_count; ++target) {
        if (column_indexes[target] == column) {
            return &row->values[target];
        }
    }
    return NULL;
}

static int resolve_insert_positional_row_values(mylite_stmt *stmt,
                                                const struct mylite_insert_table *table,
                                                size_t row_index,
                                                struct mylite_insert_execution_state *state,
                                                struct mylite_insert_bound_value *values)
{
    if (insert_row_uses_all_defaults(&stmt->insert_values, row_index)) {
        return resolve_insert_default_row_values(stmt, table, state, values);
    }

    for (size_t column = 0U; column < table->column_count; ++column) {
        int status = resolve_insert_explicit_value(
            stmt, &table->columns[column], &stmt->insert_values.rows[row_index].values[column],
            state, column, &values[column]);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int resolve_insert_default_row_values(mylite_stmt *stmt,
                                             const struct mylite_insert_table *table,
                                             struct mylite_insert_execution_state *state,
                                             struct mylite_insert_bound_value *values)
{
    for (size_t column = 0U; column < table->column_count; ++column) {
        int status = resolve_insert_omitted_default_value(stmt, &table->columns[column], state,
                                                          column, &values[column]);

        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int validate_insert_set_assignments(mylite_stmt *stmt,
                                           const struct mylite_insert_table *table,
                                           const char *schema_name, size_t **out_column_indexes)
{
    size_t assignment_count = stmt->insert_set.assignment_count;
    size_t *column_indexes = NULL;

    *out_column_indexes = NULL;
    if (assignment_count == 0U) {
        return MYLITE_UNSUPPORTED;
    }

    column_indexes = calloc(assignment_count, sizeof(*column_indexes));
    if (column_indexes == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    for (size_t index = 0U; index < assignment_count; ++index) {
        const struct mylite_insert_column_reference *target =
            &stmt->insert_set.assignments[index].target;
        size_t column_index = insert_table_column_reference_index(
            table, schema_name, stmt->insert_values.table_name, target);

        if (column_index == table->column_count) {
            int status = mylite_diagnostics_set_error_message_parts(
                stmt->database, "Unknown column '", target->column_name, "' in 'field list'");

            free(column_indexes);
            return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
        }
        column_indexes[index] = column_index;
    }

    for (size_t index = 0U; index < assignment_count; ++index) {
        for (size_t previous = 0U; previous < index; ++previous) {
            if (column_indexes[previous] == column_indexes[index]) {
                int status = mylite_diagnostics_set_error_message_parts(
                    stmt->database, "Column '",
                    stmt->insert_set.assignments[index].target.column_name, "' specified twice");

                free(column_indexes);
                return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
            }
        }
    }

    *out_column_indexes = column_indexes;
    return MYLITE_OK;
}

static int execute_insert_set_transaction(mylite_stmt *stmt, const char *schema_name,
                                          const struct mylite_insert_table *table,
                                          const size_t *column_indexes,
                                          const size_t *update_column_indexes)
{
    struct mylite_insert_execution_state state = {
        .next_auto_increment = table->next_auto_increment,
    };
    struct mylite_insert_set_row_state row_state = {0};
    struct mylite_insert_bound_value *values = NULL;
    const struct mylite_insert_row_column_indexes row_column_indexes = {
        .insert_columns = column_indexes,
        .update_columns = update_column_indexes,
        .source_column_count = stmt->insert_set.assignment_count,
    };
    sqlite3_stmt *insert = NULL;
    char *insert_sql = NULL;
    struct mylite_statement_atomicity atomicity = {0};
    int status = MYLITE_OK;
    int rc = SQLITE_OK;

    if (table->column_count == 0U) {
        (void)mylite_diagnostics_set_error_message(stmt->database,
                                                   "INSERT target table has no columns");
        return MYLITE_EXEC_ERROR;
    }

    status = mylite_transaction_begin_statement_atomicity(stmt->database, &atomicity);
    if (status != MYLITE_OK) {
        return status;
    }
    status = initialize_insert_ignore_warning_state(stmt, table, &state);
    if (status != MYLITE_OK) {
        mylite_transaction_rollback_statement_atomicity(stmt->database, &atomicity);
        return status;
    }
    status = append_insert_values_deprecated_warnings(stmt);
    if (status != MYLITE_OK) {
        insert_execution_state_deinit(&state);
        mylite_transaction_rollback_statement_atomicity(stmt->database, &atomicity);
        return status;
    }

    values = calloc(table->column_count, sizeof(*values));
    row_state.generate_auto_increment =
        calloc(table->column_count, sizeof(*row_state.generate_auto_increment));
    row_state.assigned_columns = calloc(table->column_count, sizeof(*row_state.assigned_columns));
    if (values == NULL || row_state.generate_auto_increment == NULL ||
        row_state.assigned_columns == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        status = MYLITE_NOMEM;
        goto cleanup;
    }

    insert_sql = build_insert_physical_sql(stmt->database, table);
    if (insert_sql == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        status = MYLITE_NOMEM;
        goto cleanup;
    }

    rc = sqlite3_prepare_v3(stmt->database->sqlite, insert_sql, -1, SQLITE_PREPARE_PERSISTENT,
                            &insert, NULL);
    sqlite3_free(insert_sql);
    insert_sql = NULL;
    if (rc != SQLITE_OK) {
        status = mylite_diagnostics_set_sqlite_error(stmt->database);
        goto cleanup;
    }

    status = execute_insert_set_row(stmt, table, column_indexes, insert, &row_column_indexes,
                                    &state, values, &row_state);

cleanup:
    sqlite3_free(insert_sql);
    sqlite3_finalize(insert);
    mylite_dml_insert_bound_values_deinit(values, table->column_count);
    free(row_state.generate_auto_increment);
    free(row_state.assigned_columns);

    if (status != MYLITE_OK) {
        insert_execution_state_deinit(&state);
        return finish_failed_insert_values_transaction(stmt, schema_name, table, &state, &atomicity,
                                                       status);
    }

    if (table->has_auto_increment) {
        status = update_insert_auto_increment(stmt, schema_name,
                                              insert_auto_increment_next_value(&state));
    }
    if (status == MYLITE_OK) {
        status = mylite_transaction_commit_statement_atomicity(stmt->database, &atomicity);
        if (status == MYLITE_OK) {
            insert_execution_state_deinit(&state);
            stmt->affected_rows = (int64_t)state.accepted_row_count;
            if (state.generated_insert_id) {
                stmt->database->last_insert_id = state.first_insert_id;
            }
            return MYLITE_OK;
        }
    }

    mylite_transaction_rollback_statement_atomicity(stmt->database, &atomicity);
    insert_execution_state_deinit(&state);
    return status;
}

static int execute_insert_set_row(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                  const size_t *column_indexes, sqlite3_stmt *insert,
                                  const struct mylite_insert_row_column_indexes *row_column_indexes,
                                  struct mylite_insert_execution_state *state,
                                  struct mylite_insert_bound_value *values,
                                  struct mylite_insert_set_row_state *row_state)
{
    bool ignored = false;
    int status = initialize_insert_set_row_values(stmt, table, state, values, row_state);

    if (status == MYLITE_OK) {
        status = apply_insert_set_assignments(stmt, table, column_indexes, values, row_state);
    }
    if (status == MYLITE_OK) {
        status = finish_insert_set_row_values(stmt, table, state, values, row_state);
    }
    if (status == MYLITE_OK && stmt->insert_update.has_clause) {
        return execute_insert_row_with_duplicate_update(stmt, insert, table, row_column_indexes,
                                                        state, values);
    }
    if (status == MYLITE_OK) {
        status = validate_insert_unique_indexes(stmt, table, values, state, &ignored);
    }
    if (status != MYLITE_OK || ignored) {
        return status;
    }

    return write_insert_candidate_row(stmt, insert, table, values, state);
}

static int execute_replace_values_transaction(mylite_stmt *stmt, const char *schema_name,
                                              const struct mylite_insert_table *table,
                                              const size_t *column_indexes)
{
    size_t source_column_count = table->column_count;
    struct mylite_insert_execution_state state = {
        .next_auto_increment = table->next_auto_increment,
    };
    struct mylite_insert_row_column_indexes row_column_indexes = {
        .insert_columns = column_indexes,
    };
    sqlite3_stmt *insert = NULL;
    sqlite3_stmt *delete_stmt = NULL;
    char *insert_sql = NULL;
    char *delete_sql = NULL;
    struct mylite_statement_atomicity atomicity = {0};
    int status = mylite_transaction_begin_statement_atomicity(stmt->database, &atomicity);
    int rc = SQLITE_OK;

    if (status != MYLITE_OK) {
        return status;
    }
    if (stmt->insert_values.has_column_list) {
        source_column_count = stmt->insert_values.column_count;
    }
    row_column_indexes.source_column_count = source_column_count;

    insert_sql = build_insert_physical_sql(stmt->database, table);
    delete_sql = build_replace_delete_sql(stmt->database, table);
    if (insert_sql == NULL || delete_sql == NULL) {
        sqlite3_free(insert_sql);
        sqlite3_free(delete_sql);
        mylite_transaction_rollback_statement_atomicity(stmt->database, &atomicity);
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    rc = sqlite3_prepare_v3(stmt->database->sqlite, insert_sql, -1, SQLITE_PREPARE_PERSISTENT,
                            &insert, NULL);
    sqlite3_free(insert_sql);
    insert_sql = NULL;
    if (rc == SQLITE_OK) {
        rc = sqlite3_prepare_v3(stmt->database->sqlite, delete_sql, -1, SQLITE_PREPARE_PERSISTENT,
                                &delete_stmt, NULL);
    }
    sqlite3_free(delete_sql);
    delete_sql = NULL;
    if (rc != SQLITE_OK) {
        sqlite3_finalize(insert);
        mylite_transaction_rollback_statement_atomicity(stmt->database, &atomicity);
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    for (size_t row_index = 0U; row_index < stmt->insert_values.row_count; ++row_index) {
        status = execute_replace_row(stmt, insert, delete_stmt, table, &row_column_indexes, &state,
                                     row_index);
        if (status != MYLITE_OK) {
            break;
        }
    }
    sqlite3_finalize(delete_stmt);
    sqlite3_finalize(insert);

    if (status != MYLITE_OK) {
        return finish_failed_insert_values_transaction(stmt, schema_name, table, &state, &atomicity,
                                                       status);
    }
    return finish_successful_replace_transaction(stmt, schema_name, table, &state, &atomicity);
}

static int execute_replace_row(mylite_stmt *stmt, sqlite3_stmt *insert, sqlite3_stmt *delete_stmt,
                               const struct mylite_insert_table *table,
                               const struct mylite_insert_row_column_indexes *column_indexes,
                               struct mylite_insert_execution_state *state, size_t row_index)
{
    struct mylite_insert_bound_value *values = NULL;
    int status = MYLITE_OK;

    if (table->column_count == 0U) {
        (void)mylite_diagnostics_set_error_message(stmt->database,
                                                   "REPLACE target table has no columns");
        return MYLITE_EXEC_ERROR;
    }

    values = calloc(table->column_count, sizeof(*values));
    if (values == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    status = resolve_insert_row_values(stmt, table, column_indexes->insert_columns, state,
                                       row_index, values);
    if (status == MYLITE_OK) {
        status = execute_replace_candidate_row(stmt, insert, delete_stmt, table, state, values);
    }

    mylite_dml_insert_bound_values_deinit(values, table->column_count);
    return status;
}

// NOLINTNEXTLINE(bugprone-easily-swappable-parameters)
static int execute_replace_candidate_row(mylite_stmt *stmt, sqlite3_stmt *insert,
                                         sqlite3_stmt *delete_stmt,
                                         const struct mylite_insert_table *table,
                                         struct mylite_insert_execution_state *state,
                                         const struct mylite_insert_bound_value *values)
{
    for (;;) {
        struct mylite_insert_unique_conflict conflict = {0};
        int status = find_insert_unique_conflict(stmt, table, values, &conflict);

        if (status != MYLITE_OK) {
            return status;
        }
        if (!conflict.conflicts) {
            break;
        }
        status = delete_replace_conflict_row(stmt, delete_stmt, conflict.rowid, state);
        if (status != MYLITE_OK) {
            return status;
        }
    }
    return write_insert_candidate_row(stmt, insert, table, values, state);
}

static int delete_replace_conflict_row(mylite_stmt *stmt, sqlite3_stmt *delete_stmt,
                                       sqlite3_int64 rowid,
                                       struct mylite_insert_execution_state *state)
{
    int rc = SQLITE_OK;

    sqlite3_reset(delete_stmt);
    sqlite3_clear_bindings(delete_stmt);
    rc = sqlite3_bind_int64(delete_stmt, 1, rowid);
    if (rc != SQLITE_OK) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    rc = sqlite3_step(delete_stmt);
    if (rc != SQLITE_DONE) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }
    ++state->duplicate_count;
    return MYLITE_OK;
}

static int execute_replace_set_transaction(mylite_stmt *stmt, const char *schema_name,
                                           const struct mylite_insert_table *table,
                                           const size_t *column_indexes)
{
    struct mylite_insert_execution_state state = {
        .next_auto_increment = table->next_auto_increment,
    };
    struct mylite_insert_set_row_state row_state = {0};
    struct mylite_insert_bound_value *values = NULL;
    sqlite3_stmt *insert = NULL;
    sqlite3_stmt *delete_stmt = NULL;
    char *insert_sql = NULL;
    char *delete_sql = NULL;
    struct mylite_statement_atomicity atomicity = {0};
    int status = MYLITE_OK;
    int rc = SQLITE_OK;

    if (table->column_count == 0U) {
        (void)mylite_diagnostics_set_error_message(stmt->database,
                                                   "REPLACE target table has no columns");
        return MYLITE_EXEC_ERROR;
    }

    status = mylite_transaction_begin_statement_atomicity(stmt->database, &atomicity);
    if (status != MYLITE_OK) {
        return status;
    }
    values = calloc(table->column_count, sizeof(*values));
    row_state.generate_auto_increment =
        calloc(table->column_count, sizeof(*row_state.generate_auto_increment));
    row_state.assigned_columns = calloc(table->column_count, sizeof(*row_state.assigned_columns));
    if (values == NULL || row_state.generate_auto_increment == NULL ||
        row_state.assigned_columns == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        status = MYLITE_NOMEM;
        goto cleanup;
    }

    insert_sql = build_insert_physical_sql(stmt->database, table);
    delete_sql = build_replace_delete_sql(stmt->database, table);
    if (insert_sql == NULL || delete_sql == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        status = MYLITE_NOMEM;
        goto cleanup;
    }

    rc = sqlite3_prepare_v3(stmt->database->sqlite, insert_sql, -1, SQLITE_PREPARE_PERSISTENT,
                            &insert, NULL);
    if (rc == SQLITE_OK) {
        rc = sqlite3_prepare_v3(stmt->database->sqlite, delete_sql, -1, SQLITE_PREPARE_PERSISTENT,
                                &delete_stmt, NULL);
    }
    if (rc != SQLITE_OK) {
        status = mylite_diagnostics_set_sqlite_error(stmt->database);
        goto cleanup;
    }

    status = execute_replace_set_row(stmt, insert, delete_stmt, table, column_indexes, &state,
                                     values, &row_state);

cleanup:
    sqlite3_free(insert_sql);
    sqlite3_free(delete_sql);
    sqlite3_finalize(delete_stmt);
    sqlite3_finalize(insert);
    mylite_dml_insert_bound_values_deinit(values, table->column_count);
    free(row_state.generate_auto_increment);
    free(row_state.assigned_columns);

    if (status != MYLITE_OK) {
        return finish_failed_insert_values_transaction(stmt, schema_name, table, &state, &atomicity,
                                                       status);
    }
    return finish_successful_replace_transaction(stmt, schema_name, table, &state, &atomicity);
}

static int execute_replace_set_row(mylite_stmt *stmt, sqlite3_stmt *insert,
                                   sqlite3_stmt *delete_stmt,
                                   const struct mylite_insert_table *table,
                                   const size_t *column_indexes,
                                   struct mylite_insert_execution_state *state,
                                   struct mylite_insert_bound_value *values,
                                   struct mylite_insert_set_row_state *row_state)
{
    int status = initialize_insert_set_row_values(stmt, table, state, values, row_state);

    if (status == MYLITE_OK) {
        status = apply_insert_set_assignments(stmt, table, column_indexes, values, row_state);
    }
    if (status == MYLITE_OK) {
        status = finish_insert_set_row_values(stmt, table, state, values, row_state);
    }
    if (status != MYLITE_OK) {
        return status;
    }
    return execute_replace_candidate_row(stmt, insert, delete_stmt, table, state, values);
}

static char *build_replace_delete_sql(mylite_db *database, const struct mylite_insert_table *table)
{
    sqlite3_str *sql = sqlite3_str_new(database->sqlite);

    if (sql == NULL) {
        return NULL;
    }

    sqlite3_str_appendf(sql, "DELETE FROM \"%w\" WHERE rowid = ?", table->physical_name);
    return sqlite3_str_finish(sql);
}

static int append_replace_delayed_warning(mylite_stmt *stmt)
{
    if (!stmt->insert_values.replace_delayed) {
        return MYLITE_OK;
    }
    return mylite_diagnostics_append_warning(
        stmt->database, MYLITE_MYSQL_ER_WARN_LEGACY_SYNTAX_CONVERTED,
        "REPLACE DELAYED is no longer supported. The statement was "
        "converted to REPLACE.");
}

static int finish_successful_replace_transaction(mylite_stmt *stmt, const char *schema_name,
                                                 const struct mylite_insert_table *table,
                                                 const struct mylite_insert_execution_state *state,
                                                 struct mylite_statement_atomicity *atomicity)
{
    int status = MYLITE_OK;

    if (table->has_auto_increment) {
        status = update_insert_auto_increment(stmt, schema_name,
                                              insert_auto_increment_next_value(state));
    }
    if (status == MYLITE_OK) {
        status = mylite_transaction_commit_statement_atomicity(stmt->database, atomicity);
        if (status == MYLITE_OK) {
            stmt->affected_rows =
                (int64_t)state->accepted_row_count + (int64_t)state->duplicate_count;
            if (state->generated_insert_id) {
                stmt->database->last_insert_id = state->first_insert_id;
            }
            return MYLITE_OK;
        }
    }

    mylite_transaction_rollback_statement_atomicity(stmt->database, atomicity);
    return status;
}

static int initialize_insert_set_row_values(mylite_stmt *stmt,
                                            const struct mylite_insert_table *table,
                                            struct mylite_insert_execution_state *state,
                                            struct mylite_insert_bound_value *values,
                                            struct mylite_insert_set_row_state *row_state)
{
    for (size_t column = 0U; column < table->column_count; ++column) {
        int status = MYLITE_OK;

        if (table->columns[column].auto_increment) {
            status = set_insert_set_candidate_auto_value(&values[column]);
            row_state->generate_auto_increment[column] = true;
        } else if (table->columns[column].default_text != NULL || table->columns[column].nullable) {
            status =
                resolve_insert_default_value(stmt, &table->columns[column], state, &values[column]);
        } else {
            status = resolve_insert_implicit_expression_default(stmt, &table->columns[column],
                                                                &values[column]);
        }
        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int apply_insert_set_assignments(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                        const size_t *column_indexes,
                                        struct mylite_insert_bound_value *values,
                                        struct mylite_insert_set_row_state *row_state)
{
    for (size_t index = 0U; index < stmt->insert_set.assignment_count; ++index) {
        size_t column_index = column_indexes[index];
        struct mylite_insert_bound_value value = {0};
        bool generate_auto = false;
        int status = evaluate_insert_set_assignment_value(
            stmt, table, column_index, &stmt->insert_set.assignments[index].value, values,
            &generate_auto, &value);

        if (status != MYLITE_OK) {
            mylite_dml_insert_bound_value_deinit(&value);
            return status;
        }

        mylite_dml_insert_bound_value_deinit(&values[column_index]);
        values[column_index] = value;
        row_state->generate_auto_increment[column_index] = generate_auto;
        row_state->assigned_columns[column_index] = true;
    }
    return MYLITE_OK;
}

static int finish_insert_set_row_values(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                        struct mylite_insert_execution_state *state,
                                        struct mylite_insert_bound_value *values,
                                        const struct mylite_insert_set_row_state *row_state)
{
    for (size_t column = 0U; column < table->column_count; ++column) {
        const struct mylite_insert_table_column *table_column = &table->columns[column];
        int status =
            finish_insert_set_required_omission(stmt, table_column, state, column, row_state);

        if (status != MYLITE_OK) {
            return status;
        }
        if (table_column->auto_increment && row_state->generate_auto_increment[column]) {
            mylite_dml_insert_bound_value_deinit(&values[column]);
            status = allocate_insert_auto_increment(stmt, state, &values[column]);

            if (status != MYLITE_OK) {
                return status;
            }
        }
        status = finish_insert_set_required_null(stmt, table_column, &values[column]);
        if (status != MYLITE_OK) {
            return status;
        }
    }
    return MYLITE_OK;
}

static int finish_insert_set_required_omission(mylite_stmt *stmt,
                                               const struct mylite_insert_table_column *column,
                                               struct mylite_insert_execution_state *state,
                                               size_t column_index,
                                               const struct mylite_insert_set_row_state *row_state)
{
    if (column->auto_increment || column->nullable || column->default_text != NULL ||
        row_state->assigned_columns[column_index]) {
        return MYLITE_OK;
    }
    if (!stmt->insert_values.ignore) {
        return set_insert_no_default_error(stmt->database, column->name);
    }
    return append_insert_no_default_warning_once(stmt, column, state, column_index);
}

static int finish_insert_set_required_null(mylite_stmt *stmt,
                                           const struct mylite_insert_table_column *column,
                                           struct mylite_insert_bound_value *value)
{
    if (column->auto_increment || column->nullable || value->kind != MYLITE_INSERT_BOUND_NULL) {
        return MYLITE_OK;
    }
    if (!stmt->insert_values.ignore) {
        return set_insert_null_error(stmt->database, column->name);
    }

    int status = append_insert_null_warning(stmt->database, column->name);

    if (status != MYLITE_OK) {
        return status;
    }
    mylite_dml_insert_bound_value_deinit(value);
    return resolve_insert_implicit_expression_default(stmt, column, value);
}

static int evaluate_insert_set_assignment_value(
    mylite_stmt *stmt, const struct mylite_insert_table *table, size_t target_column,
    const struct mylite_insert_value *value, const struct mylite_insert_bound_value *values,
    bool *out_generate_auto_increment, struct mylite_insert_bound_value *out_value)
{
    const struct mylite_insert_table_column *column = &table->columns[target_column];
    int status = MYLITE_OK;

    *out_generate_auto_increment = false;
    if (value->kind == MYLITE_INSERT_VALUE_DEFAULT) {
        if (column->auto_increment) {
            *out_generate_auto_increment = true;
            return set_insert_set_candidate_auto_value(out_value);
        }
        return resolve_insert_explicit_default_value(stmt, column, NULL, out_value);
    }

    status = evaluate_insert_set_expression(stmt, table, value, values, out_value);
    if (status != MYLITE_OK) {
        return status;
    }

    if (column->auto_increment) {
        if (out_value->kind == MYLITE_INSERT_BOUND_NULL ||
            (out_value->kind == MYLITE_INSERT_BOUND_INTEGER && out_value->integer_value == 0)) {
            mylite_dml_insert_bound_value_deinit(out_value);
            *out_generate_auto_increment = true;
            return set_insert_set_candidate_auto_value(out_value);
        }
        if (out_value->kind != MYLITE_INSERT_BOUND_INTEGER || out_value->integer_value < 0) {
            mylite_dml_insert_bound_value_deinit(out_value);
            return set_insert_unsupported_expression_error(stmt->database);
        }
    } else if (!column->nullable && out_value->kind == MYLITE_INSERT_BOUND_NULL) {
        if (stmt->insert_values.ignore) {
            int warning_status = append_insert_null_warning(stmt->database, column->name);

            if (warning_status != MYLITE_OK) {
                mylite_dml_insert_bound_value_deinit(out_value);
                return warning_status;
            }
            mylite_dml_insert_bound_value_deinit(out_value);
            return resolve_insert_implicit_expression_default(stmt, column, out_value);
        }
        mylite_dml_insert_bound_value_deinit(out_value);
        return set_insert_null_error(stmt->database, column->name);
    }
    return MYLITE_OK;
}

static int evaluate_insert_set_expression(mylite_stmt *stmt,
                                          const struct mylite_insert_table *table,
                                          const struct mylite_insert_value *value,
                                          const struct mylite_insert_bound_value *values,
                                          struct mylite_insert_bound_value *out_value)
{
    if (value->kind == MYLITE_INSERT_VALUE_UNARY_EXPRESSION) {
        return evaluate_insert_set_unary_expression(stmt, table, value, values, out_value);
    }
    if (value->kind == MYLITE_INSERT_VALUE_BINARY_EXPRESSION) {
        return evaluate_insert_set_binary_expression(stmt, table, value, values, out_value);
    }
    return evaluate_insert_set_simple_expression(stmt, table, value, values, out_value);
}

static int evaluate_insert_set_unary_expression(mylite_stmt *stmt,
                                                const struct mylite_insert_table *table,
                                                const struct mylite_insert_value *value,
                                                const struct mylite_insert_bound_value *values,
                                                struct mylite_insert_bound_value *out_value)
{
    struct mylite_insert_bound_value operand = {0};
    double numeric_value = 0.0;
    bool is_integer = false;
    int status = evaluate_insert_set_simple_expression(stmt, table, value->left, values, &operand);

    if (status != MYLITE_OK) {
        mylite_dml_insert_bound_value_deinit(&operand);
        return status;
    }
    if (operand.kind == MYLITE_INSERT_BOUND_NULL) {
        *out_value = (struct mylite_insert_bound_value){.kind = MYLITE_INSERT_BOUND_NULL};
        mylite_dml_insert_bound_value_deinit(&operand);
        return MYLITE_OK;
    }
    if (!insert_bound_value_is_numeric(&operand, &numeric_value, &is_integer)) {
        mylite_dml_insert_bound_value_deinit(&operand);
        return set_insert_unsupported_expression_error(stmt->database);
    }

    if (is_integer) {
        int64_t integer_value = operand.kind == MYLITE_INSERT_BOUND_INTEGER
                                    ? operand.integer_value
                                    : (int64_t)numeric_value;

        out_value->kind = MYLITE_INSERT_BOUND_INTEGER;
        out_value->integer_value = value->operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE
                                       ? -integer_value
                                       : integer_value;
    } else {
        out_value->kind = MYLITE_INSERT_BOUND_REAL;
        out_value->real_value = value->operator_kind == MYLITE_SQL_AST_OPERATOR_NEGATIVE
                                    ? -numeric_value
                                    : numeric_value;
    }
    mylite_dml_insert_bound_value_deinit(&operand);
    return MYLITE_OK;
}

static int evaluate_insert_set_binary_expression(mylite_stmt *stmt,
                                                 const struct mylite_insert_table *table,
                                                 const struct mylite_insert_value *value,
                                                 const struct mylite_insert_bound_value *values,
                                                 struct mylite_insert_bound_value *out_value)
{
    struct mylite_insert_bound_value left = {0};
    struct mylite_insert_bound_value right = {0};
    double left_number = 0.0;
    double right_number = 0.0;
    bool left_is_integer = false;
    bool right_is_integer = false;
    int status = evaluate_insert_set_simple_expression(stmt, table, value->left, values, &left);

    if (status == MYLITE_OK) {
        status = evaluate_insert_set_simple_expression(stmt, table, value->right, values, &right);
    }
    if (status != MYLITE_OK) {
        mylite_dml_insert_bound_value_deinit(&left);
        mylite_dml_insert_bound_value_deinit(&right);
        return status;
    }
    if (left.kind == MYLITE_INSERT_BOUND_NULL || right.kind == MYLITE_INSERT_BOUND_NULL) {
        *out_value = (struct mylite_insert_bound_value){.kind = MYLITE_INSERT_BOUND_NULL};
        mylite_dml_insert_bound_value_deinit(&left);
        mylite_dml_insert_bound_value_deinit(&right);
        return MYLITE_OK;
    }
    if (!insert_bound_value_is_numeric(&left, &left_number, &left_is_integer) ||
        !insert_bound_value_is_numeric(&right, &right_number, &right_is_integer)) {
        mylite_dml_insert_bound_value_deinit(&left);
        mylite_dml_insert_bound_value_deinit(&right);
        return set_insert_unsupported_expression_error(stmt->database);
    }

    if (left_is_integer && right_is_integer &&
        value->operator_kind != MYLITE_SQL_AST_OPERATOR_DIVIDE) {
        int64_t left_int =
            left.kind == MYLITE_INSERT_BOUND_INTEGER ? left.integer_value : (int64_t)left_number;
        int64_t right_int =
            right.kind == MYLITE_INSERT_BOUND_INTEGER ? right.integer_value : (int64_t)right_number;

        out_value->kind = MYLITE_INSERT_BOUND_INTEGER;
        switch (value->operator_kind) {
        case MYLITE_SQL_AST_OPERATOR_ADD:
            out_value->integer_value = left_int + right_int;
            break;
        case MYLITE_SQL_AST_OPERATOR_SUBTRACT:
            out_value->integer_value = left_int - right_int;
            break;
        case MYLITE_SQL_AST_OPERATOR_MULTIPLY:
            out_value->integer_value = left_int * right_int;
            break;
        case MYLITE_SQL_AST_OPERATOR_DIVIDE:
        case MYLITE_SQL_AST_OPERATOR_NONE:
        case MYLITE_SQL_AST_OPERATOR_POSITIVE:
        case MYLITE_SQL_AST_OPERATOR_NEGATIVE:
        default:
            mylite_dml_insert_bound_value_deinit(&left);
            mylite_dml_insert_bound_value_deinit(&right);
            return set_insert_unsupported_expression_error(stmt->database);
        }
    } else {
        if (value->operator_kind == MYLITE_SQL_AST_OPERATOR_DIVIDE && right_number == 0.0) {
            mylite_dml_insert_bound_value_deinit(&left);
            mylite_dml_insert_bound_value_deinit(&right);
            return set_insert_unsupported_expression_error(stmt->database);
        }
        out_value->kind = MYLITE_INSERT_BOUND_REAL;
        switch (value->operator_kind) {
        case MYLITE_SQL_AST_OPERATOR_ADD:
            out_value->real_value = left_number + right_number;
            break;
        case MYLITE_SQL_AST_OPERATOR_SUBTRACT:
            out_value->real_value = left_number - right_number;
            break;
        case MYLITE_SQL_AST_OPERATOR_MULTIPLY:
            out_value->real_value = left_number * right_number;
            break;
        case MYLITE_SQL_AST_OPERATOR_DIVIDE:
            out_value->real_value = left_number / right_number;
            break;
        case MYLITE_SQL_AST_OPERATOR_NONE:
        case MYLITE_SQL_AST_OPERATOR_POSITIVE:
        case MYLITE_SQL_AST_OPERATOR_NEGATIVE:
        default:
            mylite_dml_insert_bound_value_deinit(&left);
            mylite_dml_insert_bound_value_deinit(&right);
            return set_insert_unsupported_expression_error(stmt->database);
        }
    }

    mylite_dml_insert_bound_value_deinit(&left);
    mylite_dml_insert_bound_value_deinit(&right);
    return MYLITE_OK;
}

static int evaluate_insert_set_simple_expression(mylite_stmt *stmt,
                                                 const struct mylite_insert_table *table,
                                                 const struct mylite_insert_value *value,
                                                 const struct mylite_insert_bound_value *values,
                                                 struct mylite_insert_bound_value *out_value)
{
    int64_t integer_value = 0;
    double real_value = 0.0;
    char *timestamp = NULL;

    switch (value->kind) {
    case MYLITE_INSERT_VALUE_NULL:
        *out_value = (struct mylite_insert_bound_value){.kind = MYLITE_INSERT_BOUND_NULL};
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_INTEGER:
        if (!parse_insert_integer_text(value->text, &integer_value)) {
            return set_insert_unsupported_expression_error(stmt->database);
        }
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_INTEGER,
            .integer_value = integer_value,
        };
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_REAL:
        if (!parse_insert_real_text(value->text, &real_value)) {
            return set_insert_unsupported_expression_error(stmt->database);
        }
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_REAL,
            .real_value = real_value,
        };
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_TEXT:
        out_value->text_value =
            mylite_copy_span_text(value->text, value->text == NULL ? 0U : strlen(value->text));
        if (out_value->text_value == NULL) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        out_value->kind = MYLITE_INSERT_BOUND_TEXT;
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_CURRENT_TIMESTAMP:
        timestamp = insert_current_timestamp_text();
        if (timestamp == NULL) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_TEXT,
            .text_value = timestamp,
        };
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_COLUMN_REFERENCE:
        return evaluate_insert_set_column_reference(stmt, table, &value->column_reference, values,
                                                    out_value);
    case MYLITE_INSERT_VALUE_DEFAULT:
    case MYLITE_INSERT_VALUE_UNSUPPORTED:
    case MYLITE_INSERT_VALUE_VALUES_FUNCTION:
    case MYLITE_INSERT_VALUE_UNARY_EXPRESSION:
    case MYLITE_INSERT_VALUE_BINARY_EXPRESSION:
        return set_insert_unsupported_expression_error(stmt->database);
    }

    return set_insert_unsupported_expression_error(stmt->database);
}

static int evaluate_insert_set_column_reference(mylite_stmt *stmt,
                                                const struct mylite_insert_table *table,
                                                const struct mylite_insert_column_reference *ref,
                                                const struct mylite_insert_bound_value *values,
                                                struct mylite_insert_bound_value *out_value)
{
    size_t column_index = insert_table_column_reference_index(
        table,
        stmt->insert_values.schema_name == NULL ? stmt->database->selected_schema
                                                : stmt->insert_values.schema_name,
        stmt->insert_values.table_name, ref);

    if (column_index == table->column_count) {
        int status = mylite_diagnostics_set_error_message_parts(
            stmt->database, "Unknown column '", ref->column_name, "' in 'field list'");

        return status == MYLITE_NOMEM ? MYLITE_NOMEM : MYLITE_EXEC_ERROR;
    }
    int status = copy_insert_bound_value(&values[column_index], out_value);

    if (status == MYLITE_NOMEM) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
    }
    return status;
}

static int copy_insert_bound_value(const struct mylite_insert_bound_value *value,
                                   struct mylite_insert_bound_value *out_value)
{
    *out_value = *value;
    out_value->text_value = NULL;
    if (value->kind == MYLITE_INSERT_BOUND_TEXT && value->text_value != NULL) {
        out_value->text_value = mylite_copy_span_text(value->text_value, strlen(value->text_value));
        if (out_value->text_value == NULL) {
            return MYLITE_NOMEM;
        }
    }
    return MYLITE_OK;
}

static int copy_insert_bound_values(mylite_stmt *stmt,
                                    const struct mylite_insert_bound_value *values,
                                    size_t value_count,
                                    struct mylite_insert_bound_value **out_values)
{
    struct mylite_insert_bound_value *copy = NULL;

    *out_values = NULL;
    copy = calloc(value_count, sizeof(*copy));
    if (copy == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    for (size_t index = 0U; index < value_count; ++index) {
        int status = copy_insert_bound_value(&values[index], &copy[index]);

        if (status != MYLITE_OK) {
            mylite_dml_insert_bound_values_deinit(copy, value_count);
            if (status == MYLITE_NOMEM) {
                (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            }
            return status;
        }
    }

    *out_values = copy;
    return MYLITE_OK;
}

static bool insert_bound_value_is_numeric(const struct mylite_insert_bound_value *value,
                                          double *out_value, bool *out_is_integer)
{
    int64_t integer_value = 0;

    *out_value = 0.0;
    *out_is_integer = false;
    if (value->kind == MYLITE_INSERT_BOUND_INTEGER) {
        *out_value = (double)value->integer_value;
        *out_is_integer = true;
        return true;
    }
    if (value->kind == MYLITE_INSERT_BOUND_REAL) {
        *out_value = value->real_value;
        return true;
    }
    if (value->kind == MYLITE_INSERT_BOUND_TEXT &&
        parse_insert_integer_text(value->text_value, &integer_value)) {
        *out_value = (double)integer_value;
        *out_is_integer = true;
        return true;
    }
    if (value->kind == MYLITE_INSERT_BOUND_TEXT &&
        parse_insert_real_text(value->text_value, out_value)) {
        return true;
    }
    return false;
}

static int
resolve_insert_implicit_expression_default(mylite_stmt *stmt,
                                           const struct mylite_insert_table_column *column,
                                           struct mylite_insert_bound_value *out_value)
{
    const char *text_default = "";

    if (insert_column_uses_numeric_implicit_default(column)) {
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_INTEGER,
            .integer_value = 0,
        };
        return MYLITE_OK;
    }
    if (column != NULL && column->data_type != NULL) {
        if (mylite_ascii_case_equal(column->data_type, "date")) {
            text_default = "0000-00-00";
        } else if (mylite_ascii_case_equal(column->data_type, "time")) {
            text_default = "00:00:00";
        } else if (mylite_ascii_case_equal(column->data_type, "datetime") ||
                   mylite_ascii_case_equal(column->data_type, "timestamp")) {
            text_default = "0000-00-00 00:00:00";
        }
    }

    out_value->text_value = mylite_copy_span_text(text_default, strlen(text_default));
    if (out_value->text_value == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    out_value->kind = MYLITE_INSERT_BOUND_TEXT;
    return MYLITE_OK;
}

static int set_insert_set_candidate_auto_value(struct mylite_insert_bound_value *out_value)
{
    *out_value = (struct mylite_insert_bound_value){
        .kind = MYLITE_INSERT_BOUND_INTEGER,
        .integer_value = 0,
    };
    return MYLITE_OK;
}

static int resolve_insert_explicit_value(mylite_stmt *stmt,
                                         const struct mylite_insert_table_column *column,
                                         const struct mylite_insert_value *value,
                                         struct mylite_insert_execution_state *state,
                                         size_t column_index,
                                         struct mylite_insert_bound_value *out_value)
{
    char *timestamp = NULL;

    switch (value->kind) {
    case MYLITE_INSERT_VALUE_DEFAULT:
        return resolve_insert_explicit_default_value(stmt, column, state, out_value);
    case MYLITE_INSERT_VALUE_NULL:
        if (column->auto_increment) {
            return allocate_insert_auto_increment(stmt, state, out_value);
        }
        if (!column->nullable) {
            if (stmt->insert_values.ignore) {
                int status = append_insert_null_warning_once(stmt, column, state, column_index);

                if (status != MYLITE_OK) {
                    return status;
                }
                return resolve_insert_implicit_expression_default(stmt, column, out_value);
            }
            return set_insert_null_error(stmt->database, column->name);
        }
        *out_value = (struct mylite_insert_bound_value){.kind = MYLITE_INSERT_BOUND_NULL};
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_INTEGER:
        return resolve_insert_text_value(stmt, column, value->text, state, out_value);
    case MYLITE_INSERT_VALUE_REAL:
        if (column->auto_increment) {
            return set_insert_unsupported_expression_error(stmt->database);
        }
        return resolve_insert_text_value(stmt, column, value->text, state, out_value);
    case MYLITE_INSERT_VALUE_TEXT:
        return resolve_insert_quoted_text_value(stmt, column, value->text, state, out_value);
    case MYLITE_INSERT_VALUE_CURRENT_TIMESTAMP:
        if (column->auto_increment) {
            return set_insert_unsupported_expression_error(stmt->database);
        }
        timestamp = insert_current_timestamp_text();
        if (timestamp == NULL) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_TEXT,
            .text_value = timestamp,
        };
        return MYLITE_OK;
    case MYLITE_INSERT_VALUE_UNSUPPORTED:
    case MYLITE_INSERT_VALUE_COLUMN_REFERENCE:
    case MYLITE_INSERT_VALUE_VALUES_FUNCTION:
    case MYLITE_INSERT_VALUE_UNARY_EXPRESSION:
    case MYLITE_INSERT_VALUE_BINARY_EXPRESSION:
        return set_insert_unsupported_expression_error(stmt->database);
    }

    return set_insert_unsupported_expression_error(stmt->database);
}

static int resolve_insert_explicit_default_value(mylite_stmt *stmt,
                                                 const struct mylite_insert_table_column *column,
                                                 struct mylite_insert_execution_state *state,
                                                 struct mylite_insert_bound_value *out_value)
{
    if (stmt->insert_values.ignore && !column->auto_increment && !column->nullable &&
        column->default_text == NULL) {
        int status = append_insert_no_default_warning(stmt->database, column->name);

        if (status != MYLITE_OK) {
            return status;
        }
        return resolve_insert_implicit_expression_default(stmt, column, out_value);
    }
    return resolve_insert_default_value(stmt, column, state, out_value);
}

static int resolve_insert_omitted_default_value(mylite_stmt *stmt,
                                                const struct mylite_insert_table_column *column,
                                                struct mylite_insert_execution_state *state,
                                                size_t column_index,
                                                struct mylite_insert_bound_value *out_value)
{
    if (stmt->insert_values.ignore && !column->auto_increment && !column->nullable &&
        column->default_text == NULL) {
        int status = append_insert_no_default_warning_once(stmt, column, state, column_index);

        if (status != MYLITE_OK) {
            return status;
        }
        return resolve_insert_implicit_expression_default(stmt, column, out_value);
    }
    return resolve_insert_default_value(stmt, column, state, out_value);
}

static int resolve_insert_default_value(mylite_stmt *stmt,
                                        const struct mylite_insert_table_column *column,
                                        struct mylite_insert_execution_state *state,
                                        struct mylite_insert_bound_value *out_value)
{
    if (column->auto_increment) {
        return allocate_insert_auto_increment(stmt, state, out_value);
    }
    if (column->default_text == NULL) {
        if (column->nullable) {
            *out_value = (struct mylite_insert_bound_value){.kind = MYLITE_INSERT_BOUND_NULL};
            return MYLITE_OK;
        }
        return set_insert_no_default_error(stmt->database, column->name);
    }
    if (column_default_is_current_timestamp(column->default_text)) {
        char *timestamp = insert_current_timestamp_text();

        if (timestamp == NULL) {
            (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
            return MYLITE_NOMEM;
        }
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_TEXT,
            .text_value = timestamp,
        };
        return MYLITE_OK;
    }
    if (column->generated_default) {
        return set_insert_unsupported_generated_default_error(stmt->database, column->name);
    }
    return resolve_insert_text_value(stmt, column, column->default_text, state, out_value);
}

static int resolve_insert_text_value(mylite_stmt *stmt,
                                     const struct mylite_insert_table_column *column,
                                     const char *text, struct mylite_insert_execution_state *state,
                                     struct mylite_insert_bound_value *out_value)
{
    int64_t integer_value = 0;
    double real_value = 0.0;

    if (text == NULL) {
        if (!column->nullable) {
            return set_insert_null_error(stmt->database, column->name);
        }
        *out_value = (struct mylite_insert_bound_value){.kind = MYLITE_INSERT_BOUND_NULL};
        return MYLITE_OK;
    }
    if (parse_insert_integer_text(text, &integer_value)) {
        if (column->auto_increment && integer_value == 0) {
            return allocate_insert_auto_increment(stmt, state, out_value);
        }
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_INTEGER,
            .integer_value = integer_value,
        };
        return MYLITE_OK;
    }
    if (column->auto_increment) {
        return set_insert_unsupported_expression_error(stmt->database);
    }
    if (parse_insert_real_text(text, &real_value)) {
        *out_value = (struct mylite_insert_bound_value){
            .kind = MYLITE_INSERT_BOUND_REAL,
            .real_value = real_value,
        };
        return MYLITE_OK;
    }

    return set_insert_bound_text_value(stmt, text, out_value);
}

static int resolve_insert_quoted_text_value(mylite_stmt *stmt,
                                            const struct mylite_insert_table_column *column,
                                            const char *text,
                                            struct mylite_insert_execution_state *state,
                                            struct mylite_insert_bound_value *out_value)
{
    if (text == NULL || !insert_column_uses_text_storage(column)) {
        return resolve_insert_text_value(stmt, column, text, state, out_value);
    }
    return set_insert_bound_text_value(stmt, text, out_value);
}

static bool insert_column_uses_text_storage(const struct mylite_insert_table_column *column)
{
    static const char *const text_types[] = {
        "char",   "varchar",   "tinytext", "text", "mediumtext", "longtext",
        "binary", "varbinary", "tinyblob", "blob", "mediumblob", "longblob",
    };

    if (column == NULL || column->data_type == NULL) {
        return false;
    }
    for (size_t index = 0U; index < sizeof(text_types) / sizeof(text_types[0]); ++index) {
        if (mylite_ascii_case_equal(column->data_type, text_types[index])) {
            return true;
        }
    }
    return false;
}

static int set_insert_bound_text_value(mylite_stmt *stmt, const char *text,
                                       struct mylite_insert_bound_value *out_value)
{
    out_value->text_value = mylite_copy_span_text(text, strlen(text));
    if (out_value->text_value == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }
    out_value->kind = MYLITE_INSERT_BOUND_TEXT;
    return MYLITE_OK;
}

static int allocate_insert_auto_increment(mylite_stmt *stmt,
                                          struct mylite_insert_execution_state *state,
                                          struct mylite_insert_bound_value *out_value)
{
    uint64_t value = state->next_auto_increment == 0U ? 1U : state->next_auto_increment;
    int status = MYLITE_OK;

    if (value > (uint64_t)INT64_MAX) {
        (void)mylite_diagnostics_set_error_message(stmt->database,
                                                   "AUTO_INCREMENT value is out of range");
        return MYLITE_EXEC_ERROR;
    }
    status = reserve_insert_auto_increment(stmt, state, value);
    if (status != MYLITE_OK) {
        return status;
    }
    state->next_auto_increment = value + 1U;
    *out_value = (struct mylite_insert_bound_value){
        .kind = MYLITE_INSERT_BOUND_INTEGER,
        .integer_value = (int64_t)value,
        .generated_auto_increment = true,
    };
    return MYLITE_OK;
}

static int reserve_insert_auto_increment(mylite_stmt *stmt,
                                         struct mylite_insert_execution_state *state,
                                         uint64_t first_value)
{
    uint64_t row_count = insert_statement_row_count(stmt);

    if (state->reserved_auto_increment_end != 0U) {
        return MYLITE_OK;
    }
    if (row_count > (uint64_t)INT64_MAX - first_value) {
        (void)mylite_diagnostics_set_error_message(stmt->database,
                                                   "AUTO_INCREMENT value is out of range");
        return MYLITE_EXEC_ERROR;
    }
    state->reserved_auto_increment_end = first_value + row_count;
    return MYLITE_OK;
}

static uint64_t insert_statement_row_count(const mylite_stmt *stmt)
{
    if (stmt->kind == MYLITE_STMT_INSERT_SET || stmt->kind == MYLITE_STMT_REPLACE_SET) {
        return 1U;
    }
    return (uint64_t)stmt->insert_values.row_count;
}

static uint64_t insert_auto_increment_next_value(const struct mylite_insert_execution_state *state)
{
    if (state->reserved_auto_increment_end > state->next_auto_increment) {
        return state->reserved_auto_increment_end;
    }
    return state->next_auto_increment;
}

static size_t insert_table_column_index(const struct mylite_insert_table *table,
                                        const char *column_name)
{
    for (size_t index = 0U; index < table->column_count; ++index) {
        if (mylite_ascii_case_equal(table->columns[index].name, column_name)) {
            return index;
        }
    }
    return table->column_count;
}

static size_t
insert_table_column_reference_index(const struct mylite_insert_table *table,
                                    const char *schema_name, const char *table_name,
                                    const struct mylite_insert_column_reference *reference)
{
    if (!insert_column_reference_qualifiers_match(reference, schema_name, table_name)) {
        return table->column_count;
    }
    return insert_table_column_index(table, reference->column_name);
}

static bool
insert_column_reference_qualifiers_match(const struct mylite_insert_column_reference *reference,
                                         const char *schema_name, const char *table_name)
{
    if (reference->schema_name != NULL &&
        !mylite_ascii_case_equal(reference->schema_name, schema_name)) {
        return false;
    }
    if (reference->table_name != NULL &&
        !mylite_ascii_case_equal(reference->table_name, table_name)) {
        return false;
    }
    return true;
}

static int bind_insert_row_values(mylite_db *database, sqlite3_stmt *insert,
                                  const struct mylite_insert_bound_value *values,
                                  size_t value_count)
{
    (void)database;
    for (size_t index = 0U; index < value_count; ++index) {
        int rc = bind_insert_bound_value(insert, (int)index + 1, &values[index]);

        if (rc != SQLITE_OK) {
            return mylite_diagnostics_set_sqlite_error(database);
        }
    }
    return MYLITE_OK;
}

static int bind_insert_bound_value(sqlite3_stmt *stmt, int index,
                                   const struct mylite_insert_bound_value *value)
{
    switch (value->kind) {
    case MYLITE_INSERT_BOUND_NULL:
        return sqlite3_bind_null(stmt, index);
    case MYLITE_INSERT_BOUND_INTEGER:
        return sqlite3_bind_int64(stmt, index, (sqlite3_int64)value->integer_value);
    case MYLITE_INSERT_BOUND_REAL:
        return sqlite3_bind_double(stmt, index, value->real_value);
    case MYLITE_INSERT_BOUND_TEXT:
        return sqlite3_bind_text(stmt, index, value->text_value, -1, sqlite_transient_destructor());
    }

    return SQLITE_MISUSE;
}

static int validate_insert_unique_indexes(mylite_stmt *stmt,
                                          const struct mylite_insert_table *table,
                                          const struct mylite_insert_bound_value *values,
                                          struct mylite_insert_execution_state *state,
                                          bool *out_ignored)
{
    *out_ignored = false;
    for (size_t index = 0U; index < table->unique_index_count; ++index) {
        bool conflicts = false;
        int status = insert_unique_index_conflicts(stmt, table, &table->unique_indexes[index],
                                                   values, &conflicts);

        if (status != MYLITE_OK) {
            return status;
        }
        if (conflicts) {
            if (stmt->insert_values.ignore) {
                ++state->duplicate_count;
                *out_ignored = true;
                return append_insert_duplicate_entry_warning(stmt->database,
                                                             stmt->insert_values.table_name,
                                                             &table->unique_indexes[index], values);
            }
            return set_insert_duplicate_entry_error(stmt->database, stmt->insert_values.table_name,
                                                    &table->unique_indexes[index], values);
        }
    }
    return MYLITE_OK;
}

static int insert_unique_index_conflicts(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                         const struct mylite_insert_unique_index *index,
                                         const struct mylite_insert_bound_value *values,
                                         bool *out_conflicts)
{
    char *sql = NULL;
    sqlite3_stmt *check = NULL;
    int rc = SQLITE_OK;
    int status = MYLITE_OK;

    *out_conflicts = false;
    for (size_t part = 0U; part < index->column_count; ++part) {
        if (values[index->column_indexes[part]].kind == MYLITE_INSERT_BOUND_NULL) {
            return MYLITE_OK;
        }
    }

    sql = build_insert_unique_check_sql(stmt->database, table, index, values);
    if (sql == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    rc = sqlite3_prepare_v3(stmt->database->sqlite, sql, -1, SQLITE_PREPARE_PERSISTENT, &check,
                            NULL);
    sqlite3_free(sql);
    if (rc != SQLITE_OK) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    status = bind_insert_unique_check_values(stmt->database, check, index, values);
    if (status == MYLITE_OK) {
        rc = sqlite3_step(check);
        if (rc == SQLITE_ROW) {
            *out_conflicts = true;
        } else if (rc != SQLITE_DONE) {
            status = mylite_diagnostics_set_sqlite_error(stmt->database);
        }
    }
    sqlite3_finalize(check);
    return status;
}

static int find_insert_unique_conflict(mylite_stmt *stmt, const struct mylite_insert_table *table,
                                       const struct mylite_insert_bound_value *values,
                                       struct mylite_insert_unique_conflict *out_conflict)
{
    *out_conflict = (struct mylite_insert_unique_conflict){0};
    for (size_t index = 0U; index < table->unique_index_count; ++index) {
        bool conflicts = false;
        sqlite3_int64 rowid = 0;
        int status = insert_unique_index_conflict_rowid(stmt, table, &table->unique_indexes[index],
                                                        values, 0, false, &rowid, &conflicts);

        if (status != MYLITE_OK) {
            return status;
        }
        if (conflicts) {
            *out_conflict = (struct mylite_insert_unique_conflict){
                .index = &table->unique_indexes[index],
                .rowid = rowid,
                .conflicts = true,
            };
            return MYLITE_OK;
        }
    }
    return MYLITE_OK;
}

static int insert_unique_index_conflict_rowid(mylite_stmt *stmt,
                                              const struct mylite_insert_table *table,
                                              const struct mylite_insert_unique_index *index,
                                              const struct mylite_insert_bound_value *values,
                                              sqlite3_int64 excluded_rowid, bool has_excluded_rowid,
                                              sqlite3_int64 *out_rowid, bool *out_conflicts)
{
    char *sql = NULL;
    sqlite3_stmt *check = NULL;
    int rc = SQLITE_OK;
    int status = MYLITE_OK;

    *out_rowid = 0;
    *out_conflicts = false;
    for (size_t part = 0U; part < index->column_count; ++part) {
        if (values[index->column_indexes[part]].kind == MYLITE_INSERT_BOUND_NULL) {
            return MYLITE_OK;
        }
    }

    sql = build_insert_unique_conflict_sql(stmt->database, table, index, has_excluded_rowid);
    if (sql == NULL) {
        (void)mylite_diagnostics_set_error_message(stmt->database, "out of memory");
        return MYLITE_NOMEM;
    }

    rc = sqlite3_prepare_v3(stmt->database->sqlite, sql, -1, SQLITE_PREPARE_PERSISTENT, &check,
                            NULL);
    sqlite3_free(sql);
    if (rc != SQLITE_OK) {
        return mylite_diagnostics_set_sqlite_error(stmt->database);
    }

    status = bind_insert_unique_conflict_values(stmt->database, check, index, values,
                                                excluded_rowid, has_excluded_rowid);
    if (status == MYLITE_OK) {
        rc = sqlite3_step(check);
        if (rc == SQLITE_ROW) {
            *out_conflicts = true;
            *out_rowid = sqlite3_column_int64(check, 0);
        } else if (rc != SQLITE_DONE) {
            status = mylite_diagnostics_set_sqlite_error(stmt->database);
        }
    }
    sqlite3_finalize(check);
    return status;
}

static char *build_insert_unique_conflict_sql(mylite_db *database,
                                              const struct mylite_insert_table *table,
                                              const struct mylite_insert_unique_index *index,
                                              bool has_excluded_rowid)
{
    sqlite3_str *sql = sqlite3_str_new(database->sqlite);

    if (sql == NULL) {
        return NULL;
    }

    sqlite3_str_appendf(sql, "SELECT rowid FROM \"%w\" WHERE ", table->physical_name);
    for (size_t part = 0U; part < index->column_count; ++part) {
        size_t column_index = index->column_indexes[part];

        if (part != 0U) {
            sqlite3_str_append(sql, " AND ", (int)strlen(" AND "));
        }
        if (index->prefix_lengths[part] != 0U) {
            sqlite3_str_appendf(sql, "substr(\"%w\",1,%llu) = substr(?,1,%llu)",
                                table->columns[column_index].name,
                                (unsigned long long)index->prefix_lengths[part],
                                (unsigned long long)index->prefix_lengths[part]);
        } else {
            sqlite3_str_appendf(sql, "\"%w\" = ?", table->columns[column_index].name);
        }
    }
    if (has_excluded_rowid) {
        sqlite3_str_append(sql, " AND rowid <> ?", (int)strlen(" AND rowid <> ?"));
    }
    sqlite3_str_append(sql, " LIMIT 1", (int)strlen(" LIMIT 1"));
    return sqlite3_str_finish(sql);
}

static int bind_insert_unique_conflict_values(mylite_db *database, sqlite3_stmt *check,
                                              const struct mylite_insert_unique_index *index,
                                              const struct mylite_insert_bound_value *values,
                                              sqlite3_int64 excluded_rowid, bool has_excluded_rowid)
{
    for (size_t part = 0U; part < index->column_count; ++part) {
        int rc =
            bind_insert_bound_value(check, (int)part + 1, &values[index->column_indexes[part]]);

        if (rc != SQLITE_OK) {
            return mylite_diagnostics_set_sqlite_error(database);
        }
    }
    if (has_excluded_rowid) {
        int rc = sqlite3_bind_int64(check, (int)index->column_count + 1, excluded_rowid);

        if (rc != SQLITE_OK) {
            return mylite_diagnostics_set_sqlite_error(database);
        }
    }
    return MYLITE_OK;
}

static char *build_insert_unique_check_sql(mylite_db *database,
                                           const struct mylite_insert_table *table,
                                           const struct mylite_insert_unique_index *index,
                                           const struct mylite_insert_bound_value *values)
{
    sqlite3_str *sql = sqlite3_str_new(database->sqlite);

    (void)values;
    if (sql == NULL) {
        return NULL;
    }

    sqlite3_str_appendf(sql, "SELECT 1 FROM \"%w\" WHERE ", table->physical_name);
    for (size_t part = 0U; part < index->column_count; ++part) {
        size_t column_index = index->column_indexes[part];

        if (part != 0U) {
            sqlite3_str_append(sql, " AND ", (int)strlen(" AND "));
        }
        if (index->prefix_lengths[part] != 0U) {
            sqlite3_str_appendf(sql, "substr(\"%w\",1,%llu) = substr(?,1,%llu)",
                                table->columns[column_index].name,
                                (unsigned long long)index->prefix_lengths[part],
                                (unsigned long long)index->prefix_lengths[part]);
        } else {
            sqlite3_str_appendf(sql, "\"%w\" = ?", table->columns[column_index].name);
        }
    }
    sqlite3_str_append(sql, " LIMIT 1", (int)strlen(" LIMIT 1"));
    return sqlite3_str_finish(sql);
}

static int bind_insert_unique_check_values(mylite_db *database, sqlite3_stmt *check,
                                           const struct mylite_insert_unique_index *index,
                                           const struct mylite_insert_bound_value *values)
{
    for (size_t part = 0U; part < index->column_count; ++part) {
        int rc =
            bind_insert_bound_value(check, (int)part + 1, &values[index->column_indexes[part]]);

        if (rc != SQLITE_OK) {
            return mylite_diagnostics_set_sqlite_error(database);
        }
    }
    return MYLITE_OK;
}

static int update_insert_auto_increment(mylite_stmt *stmt, const char *schema_name,
                                        uint64_t next_auto_increment)
{
    return update_table_auto_increment(stmt, schema_name, stmt->insert_values.table_name,
                                       next_auto_increment);
}

static int update_table_auto_increment(mylite_stmt *stmt, const char *schema_name,
                                       const char *table_name, uint64_t next_auto_increment)
{
    int status = mylite_catalog_update_auto_increment(stmt->database, schema_name, table_name,
                                                      next_auto_increment);

    if (status != MYLITE_OK) {
        return status;
    }
    return mylite_transaction_record_pending_auto_increment(stmt->database, schema_name, table_name,
                                                            next_auto_increment);
}

static bool insert_row_uses_all_defaults(const struct mylite_insert_values_plan *plan,
                                         size_t row_index)
{
    if (plan->has_column_list) {
        return false;
    }
    if (plan->rows[row_index].value_count == 0U) {
        return true;
    }
    return false;
}

static size_t insert_row_target_column_count(const struct mylite_insert_values_plan *plan,
                                             const struct mylite_insert_table *table,
                                             size_t row_index)
{
    if (plan->has_column_list) {
        return plan->column_count;
    }
    if (plan->rows[row_index].value_count == 0U) {
        return 0U;
    }
    return table->column_count;
}

static int set_insert_wrong_value_count_error(mylite_db *database, size_t row_index)
{
    enum { row_number_buffer_size = 64 };
    char buffer[row_number_buffer_size];

    (void)snprintf(buffer, sizeof(buffer), "%zu", row_index + 1U);
    if (mylite_diagnostics_set_error_message_parts(database,
                                                   "Column count doesn't match value count at row ",
                                                   buffer, "") == MYLITE_NOMEM) {
        return MYLITE_NOMEM;
    }
    return MYLITE_EXEC_ERROR;
}

